window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"조선 선조 때 학자인 매헌(梅軒) 금보(琴輔, 1521­1586)가 60세 때 처음 지었다. 정면 4칸, 측면 1칸 반 규모의 一자형 집으로, 현재의 건물은 1933년 문중에서 중수하였다. 수운정(水雲亭)이라는 이름은 금보가 자연을 사랑하여 항상 물 맑고 경치 좋은 곳에 아담한 정자를 지어 물과 구름을 벗하며 사우(士友)들과 학문을 논하고 후학을 양성하고자 하는 뜻으로 이름지었다고 한다. 비록 20세기 초에 중수하였으나, 이전 건물의 건축양식을 그대로 적용한 건물로 현재 19세기 건축물의 특징으로 드러나는 평면 및 구조양식을 잘 지니고 있다.","a":"안동수운정","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663438.jpg"},{"q":"마을 앞 논 가운데 자리하고 있으며, 탑이 속해있던 절의 역사는 전하는 것이 없다. 전체적인 모습은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 형태이다. 기단부는 크게 파손되어 전체가 동쪽으로 13∼15도 정도 기울어져 있던 것을, 1979년에 해체 ·보수하였다. 위층 기단 윗면은 연꽃무늬를 돌아가며 새기고, 가운데에 윗돌을 괴기 위한 높직한 괴임을 두었다. 탑신부의 1층 몸돌에는 문짝모양을 새겼다. 급한 경사가 흐르는 지붕돌은 밑면에 4단의 받침을 두었는데, 몸돌에 비해 처마가 좁고 줄어드는 비율도 적어 무거워 보인다. 높직한 탑신괴임이나 지붕돌의 모습으로…","a":"안동임하동동삼층석탑","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640433.jpg"},{"q":"우물이 자리한 지역은 부여 두리라는 자연마을로서, 부여 왕씨의 하나인 부여서씨가 거주한 지역으로 전해지며 오래전부터 이 지역은 만가대(萬家垈)라 불리어져 왔다. 우물 깊이는 5.2m이며, 지상부는 정자형(井字形)으로 결구되어 있는데 석재가구 한변의 길이는 180cm이고 높이는 45cm이다. 동리 이장에 의하면, 우물은 5∼6m 깊이를 굴광하여 밑바닥에는 잘 다듬은 석판을 깔아 놓았다 하며, 그 위에 잘 다듬은 각재석을 장방형으로 결구하여 겹쳐 쌓아 올리다가 중간부터는 크기가 다른 자연석 단면을 이용하여 원형으로 쌓았으며 지상부의 맨 윗쪽에는 부정형 장대석을 십자맞춤으…","a":"부여용당리우물","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661566.jpg"},{"q":"영화학당(현:○○○○○)은 선교의 목적으로 신식교육을 위하여 설립된 교육기관이다. ○○○○○동 교사는 우각현의 대지 1,226평(1909년 토지매입)에 연면적 212평 3층 규모의 교사로 1910년 3월30일 착공하여 1911년 9월14일 완공되었다. 현 위치는 동쪽 언덕 위에 여선교사합숙소(현, ○○기독교사회복지관)과 남선교사합숙소(구, 동○○세무소청사), 아펜젤러 사택(현, 변전소) 부근에 있으며 특히 여선교사합숙소와 근접하여 건립된 이유로는 당시의 교사들이 대부분 여선교사들이었기 때문으로 추정한다. 이 건물은 현관부분을 돌출시킨 십자가 형태를 띠고 있었으나 19…","a":"인천 영화초등학교 구 본관","c":"시도유형문화유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637101.jpg"},{"q":"○○○란 어떠한 사건이나 사업에 관련된 사실이나 자취를 기록해 놓은 비이다. 이 비는 조선 영조 49년(1773) 호남좌수사로 부임해온 김영수가 전라○○○의 성을 크게 다시 지어 새로이 하고, 군사를 정비하며, 군기, 잡물 등을 마련한 사실과 월과미(月課米:중앙에서 지방의 관아에 매달마다 부과하였던 세금), 털 없는 겉벼 등을 마련해 놓았던 사실을 적고 있다. 비각 안에 모셔둔 비는 네모난 받침돌 위로 비몸을 세우고 머릿돌을 올린 모습으로, 비몸 앞면에 ‘호○○○○○’라는 비의 명칭을 가로로 새겨 놓았다. 비문은 한줄에 42∼45자씩 14줄의 글을 세로로 적어 놓았다…","a":"여수호좌수영수성창설사적비","c":"문화유산자료","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662230.jpg"},{"q":"정암 조광조를 중심으로 덕촌 최희정을 기리고 있는 서원으로 1960년 지방 유림이 지었다. 조광조(1482∼1519)는 조선 전기의 문신이며 성리학자이다. 김종직의 학통을 이어 사림파의 중심이 되었으며 급진적인 개혁을 실행하였다. 이를 반대하는 훈구세력의 모함으로 유배되어 기묘사화(1519) 때 희생되었다. 최희정은 조광조의 가르침을 받았고 조선 중종 11년(1516) 무과에 급제하였다. 이 때 함경도에 여진족이 침입하자 조광조가 추천하여 적을 크게 물리쳤다. 중종은 그 공로로 현재 서원이 있는 땅을 하사하였다고 한다.","a":"동죽서원","c":"문화유산자료","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661693.jpg"},{"q":"○○○은 전면 3칸 측면 2칸의 소로수장 주두집으로 5량 가구구조의 팔작지붕의 재실용도의 한옥이다. ○○○의 평면은 대청마루가 3칸의 ㄱ자형으로 구성되고 온돌방도 3칸의 ㄴ자형으로 구성되어 서로 마주보는 마루와 온돌방의 구성을 취하고 있어 조형적이면서 기능적으로 영역의 조화로운 안배를 이루고 있는 것으로 파악된다. 방 전면으로는 머름을 구성하지 않아 출입의 용이함을 더 고려하여 많은 사람의 이동이 있는 방으로서의 기능성을 살린 것으로 파악된다 대청마루 상부에는 충량을 걸치고 박공 하부에만 우물천장으로 구성하고, 대부분 연등천정으로 구성하였는데, 선자연은 근대형의 약식…","a":"합천 임강정","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666607.jpg"},{"q":"목조 초가민가로 약 200여년 전 건립된 전형적인 전통가옥이며, 가씨 종중에서 1930년대 가옥을 인수 후 현재까지 거주 및 관리하고 있다. 가옥 형태는 안채(78㎡), 사랑채(32㎡), 문간채(59㎡)등으로, ㅁ자형으로 형태를 이루고 있으며, 기구의 기법도 민간의 간이석 덧붙이기 방식을 따랐으며, 지붕 연목도 평연재로 되어있고 마루난간은 亜자형으로 특이한 구조를 이루고 있다.","a":"태안상옥리가영현가옥","c":"시도민속문화유산","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658268.jpg"},{"q":"이곳에는 ○○ 출신으로 효행이 탁월하여 사림의 모범이 되었던 정운오(1542∼1593), 추담 김우급(1574∼1643), 조영규(1535∼1592), 처사 조정로(1559∼1612)와 그의 아들, 최학령(1512∼?), 아곡 박수량(1491∼1554)을 추모하여 모신 7기의 비(碑)가 있는 곳이다. 이곳에는 원래 고려 고종(재위 1213∼1259) 때 효자로 소문난 절효공 서릉(徐稜)이 학문을 가르치던 모암정사가 있었다. 조선 선조 20년(1587)에 ○○현감 이계와 하곡 정원오 등 지방 사림들이 절효공의 효행과 유덕을 추모하기 위해 사당과 강당을 건립하고 모암서원…","a":"장성 칠현 유적지","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022101213343600.jpg"},{"q":"○○○ 대웅전에 보관되어 있는 ○○○○ 및 ○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. ○○○○는 세마포(細麻布)에 종이를 여러 겹으로 배접한 바탕 위에 중앙의 아미타불을 중심으로 좌우협시보살만을 배치한 아미타삼존도이다. 남색 하늘 바탕에 갈색과 녹색 구름을 그렸고, 부처와 보살상을 홍색과 녹색 위주로 그려 다소 무거운 느낌을 주지만 세련된 필치를 보이고 있다. 그림의 아랫부분에 적힌 화기(畵記)에 따르면 이 ○○○○는 조선 영조 26년(1750)에 화원(畵員) 보총(普摠)·처일(處一) 등에 의해 조성되었다고 한다.…","a":"은해사극락보전후불탱화및삼장탱화","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641090.jpg"},{"q":"김시습(1435∼1493)과 김효종(1414∼1493)의 뜻을 기리기 위해 조선 광해군 13년(1621)에 세운 사당이다. 김시습은 조선 전기 학자이며 우리나라 최초의 한문소설인 『금오신화』를 지은 인물이다. 지금 있는 ○○○는 흥선대원군의 서원 철폐령으로 잠시 폐쇠되었다가 1970년에 다시 세운 것이다.","a":"청일사","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661038.jpg"},{"q":"이 불화는 현재 ○○○ 대웅전의 향좌측(向左側) 벽에 걸려있다. 화면 아래 붉은색 란에 묵서(墨書)로 명기된 화기(畵記)에 의하면 1914년 음력 10월 8일 새로 ○○○ 1축을 조성하여 경성부 고양군 삼각산 안양암에 봉안하였다고 하다. 연응 정순(淵凝 淨旬)스님을 증명으로 하고, 양학 효신(養鶴 孝信)스님이 별좌(別座) 겸 화주(化主)가 되어 조성하였는데, 금어(金魚)로는 금호 약효(錦湖 若效), 향암 성엽(香庵 性曄), 연암 경인(蓮庵 敬仁) 등 3인의 화승이 제작에 참여하였다. 화면은 가로가 약간 긴 직사각형인 데, 화면의 가장자리를 따라 진채 기법(眞彩 技法)…","a":"응선사 산신도","c":"문화유산자료","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313244700.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○ 선생의 행적을 기록하고 있다. ○○ 선생은 학문에 뛰어난 이로, 중종 14년(1519) 대과에 장원급제하여 관직에 나아가 홍문관의 부수찬, 사간원의 사간 등을 지냈고, 생을 마친 후에는 영의정으로 추증되었다. 선조 23년(1590) 당대의 명필인 한석봉의 글씨를 새겨 비를 세웠다.","a":"합천 박소 신도비","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642200.jpg"},{"q":"조선 중기 문신이자 임진왜란 때 의병장으로 활약했던 조헌(1544∼1592) 선생의 위패를 모시고 있는 사당이다. 조헌은 선조 25년(1592) 임진왜란이 일어나자 ○○에서 김경백 등과 의병 1,600여명을 모집하고 승병인 영규대사와 함께 청주성을 수복하는데 공을 세웠다. 그러나 충청도 순찰사인 윤극형의 방해로 의병이 강제 해산되어 700여명으로 금산전투에 참전했으나 모두 전사하였다. 건물 규모는 앞면 3칸·옆면 1칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 솟을대문과 돌로 쌓은 담장이 둘러져 있고, 뜰에는 금산전투에서 그를 대신하여…","a":"옥천 후율당","c":"시도기념물","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649240.jpg"},{"q":"조선 인종 때의 학자인 하서 김인후(1510∼1560) ○○을 새긴 ○○이다. 김인후는 1540년 문과에 급제하여 문원부정자를 시작으로 홍문관의 박사와 부수찬, 옥과현감 등의 벼슬을 지냈다. 시문에 뛰어나 10여 권의 ○○을 남겼으나 도학(道學)에 관해 쓴 책은 많지 않다. 천문, 지리, 의약, 산수에도 정통하였으며, 제자로는 정철, 조희문 등이 있다. 그가 죽은 후 ○○의 ○○○○, 옥과의 영귀서원 등에 모셔졌고, 시호는 ‘문정’이다. 김인후가 죽은 후 8년만인 선조 1년(1568)에 처음 간행되어 숙종 12년(1686) 중간본과 1797∼1802년에 걸쳐 세 번…","a":"장성 필암서원 하서선생 문집 목판","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018112114430400.jpg"},{"q":"○○○○은 신당마을 뒷산의 낮은 구릉지대에 있는 산성으로, 구릉지대의 꼭대기를 빙둘러 쌓았다. 붕괴된 부분이 많지만 전체적인 형태는 남아있다. 성벽의 아랫부분은 돌과 흙을 섞어 쌓은 혼축성이나, 경사가 심한 곳의 아랫부분은 무너지는 것을 막기 위하여 자연석 혹은 다듬은 화강암으로 쌓았다. 이 지역 주민들이 ○○○○을 목마성이라 부르는 것으로 보아, 한 때 말을 키운 듯하나 기록이 없어 확인할 수 없다. 다만 계성면이 옛 현(縣)의 소재지이므로 그럴 가능성을 뒷받침 해줄 따름이다. 성이 만들어진 정확한 연대는 알 수 없다.","a":"창녕 신당산성","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664013.jpg"},{"q":"고려 후기의 무신으로 홍건적을 격퇴하는 데 큰 공을 세운 ○○○ 장군의 무덤이다. 장군은 충목왕이 원나라에 있을 때 모신 공을 인정받아, 왕이 즉위하자 무관의 벼슬인 중랑장에 오르게 되었다. 1359년(공민왕 8)에 4만 여명의 홍건적이 침입해오자 철주·철화·함종 등에서 관군들과 적을 무찌르는 큰 공을 세워 왕명의 출납과 군기를 맡는 추밀원 부사가 되었다. 1361년(공민왕 10)에 20여 만명의 홍건적이 다시 침입하여 개경까지 오자 정세운·최영 등 장군들과 합심하여 적을 완전히 물리치고 개경을 수복하였다. 그러나 그의 공을 시기한 간신 김용(金鏞) 등의 모략으로 1…","a":"이방실장군묘","c":"시도기념물","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646099.jpg"},{"q":"“○○○○○”은 1698년 제작되어 전남 영암 성도암에서 개금(改金), 해남 대흥사에 봉안됐다가 1908년 제주○○○를 재 창건한 안봉여관스님이 1925년 대흥사의 말사인 제주 ○○○로 옮겨온 것으로 기록되어 있다. 전체높이 75cm, 얼굴높이 14cm, 어깨너비 34cm, 무릎높이13cm, 무릎너비 47cm이다. 17세기말의 전형적인 불상 양식을 갖춘 이 불상은 등신대의 단아한 상으로 삼산보관(三山寶冠)을 따로 쓰고 있다. 보관 정면에 커다란 꽃무늬 8송이가 배치돼 있고 좌우로 장식이 있는 전형적인 조선후기 보관이다. 양감 있고 눈, 코, 입의 단아한 얼굴 표현,…","a":"관음사목조관음보살좌상","c":"시도유형문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643290.jpg"},{"q":"○○○○○는 상북면 ○○○ 함박들 맞은편에 위치하며, 상북면 일대에 남아 있는 가장 큰 ○○○ 가운데 하나로, 그 보존 상태가 양호하다. 현재 남아 있는 덮개돌은 길이 310cm, 너비 300cm, 두께 90cm정도이다. 마을 사람들은 조선시대에 정대업 장군이 무예를 닦던 바위라 하여 일명 ‘장군바위’라 부르고 있으며, 덮개돌 위에 7개의 성혈(性穴)이 남아 있어 ‘칠성바위’라고도 한다. 덮개돌에 나타나는 성혈은 여성 성기의 상징으로 풍요와 다산(多産)의 의미로 해석되기도 하고, 태양을 상징하는 것으로 보기도 한다. 아이를 낳지 못하는 부인들이 작은 돌로 성혈을 열심…","a":"향산리지석묘","c":"시도기념물","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645893.jpg"},{"q":"조선 고종 17년(1880)에 청호공이 지은 집이다. 안채와 사랑채가 一자형으로 앞뒤로 나란히 배치되고, 사랑채를 중심으로 헛간과 대문채 등이 ㅁ자형으로 놓인 구조를 이루고 있다. 안채는 앞면 5칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면 5칸 중에서 대청마루가 2칸으로 다른 공간에 비해 유달리 큰 것이 특이하다. 대청 뒷면은 격자무늬 문을 설치하여 제사 도구를 보관하게 하고 제사 의식 때 사용하는 공간으로 넓혔다. 안채 8칸·사랑채 5칸·곳간채 3칸·헛간 6칸·대문채 3칸을 잘 보존하고 있는 전형적인 남부 부농 민가이다…","a":"진주 청원리 이씨고가","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664068.jpg"},{"q":"차나무는 전라도, 경상도에서 많이 재배되는 나무로 원산지는 중국으로부터 미얀마, 인도의 아샘 지방으로 이어지는 산악지대인 것으로 알려지고 있다. 1년생 가지는 흰색으로 잔털이 많고, 2년생 가지는 회갈색이며 잔털이 없다. 잎은 뾰족한 긴 타원형으로 표면은 녹색이고 뒷면은 회녹색이다. 꽃은 10∼11월에 피고 열매는 이듬해의 가을에 익는다. 차에 대한 기록은 삼국사기 흥덕왕 3년(828)에 중국 당나라에 사신으로 갔던 김대렴이 차 씨앗을 가지고 돌아오니 왕이 지리산에 심게 했다는 기록이 있다. 정만우 스님이 쓴 『화엄사적기』에는 544년 인도에서 연기(緣起)스님이 지리…","a":"구례장죽전녹차시배지","c":"시도기념물","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020030518181600.jpg"},{"q":"○○○는 조선 중종 17년(1522)에 신월스님이 지은 절이다. 원래는 고려 광종(재위 949∼975) 때 법인대사가 삼각산 부허동에 보덕암을 짓고 이어져 내려오던 것인데, 신월이 지금의 자리로 옮겨 크게 짓고 ○○○라 이름지었다. 그 후 광해군 10년(1618)의 큰 화재와 오랜 세월로 인해 건물이 퇴락하자, 고종 3년(1866) 흥선대원군의 시주로 다시 지었다. 1933년 조선어학회 주관으로 한글 맞춤법 통일안을 위해 이희승·최현배 등의 국문학자 9명이 기거하며 집필한 곳이기도 하다. 석가모니를 중심으로 양옆에 관세음보살과 대세지보살을 모시고 있는 ○○○○○은 고…","a":"화계사 대웅전","c":"시도유형문화유산","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636215.jpg"},{"q":"수덕사에 있는 거문고로 만공스님께서 고종의 둘째 아들인 의친왕 이강에게 받은 것이다. 이조묵(李祖默)이 새긴 공민왕금(恭愍王琴) 이라는 글씨와 함께 만공 스님의 시가 새겨 있다.","a":"수덕사유물(거문고)","c":"문화유산자료","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661217.jpg"},{"q":"○○○에 보존되어 있는 ○○○인데, ○○○은 칠성(七星)을 불교의 호법선신(護法善神)으로 수용하고 이를 의인화하여 묘사한 그림이다. 이 ○○○은 치성광여래삼존도(熾盛光如來三尊圖), 삼태육성이십팔수도(三台六星二十八宿圖), 칠성도(七星圖) 등이 묘사되어 있다. 치성광여래삼존도는 면 바탕에 채색하여 그려진 것으로, 화면 중앙에 치성광여래좌상이 있고 그 왼쪽에는 일광보살이 오른쪽에는 월광보살이 솟아오른 연꽃 위에 녹청색의 베를 깔고 앉아 있다. 삼태육성이십팔수도는 비단 바탕에 채색하여 그려진 것으로, 화면 하단 중앙에 삼태육성 도상이 이 탁자 위에 얹힌 향로를 중심으로 서…","a":"양산 통도사 함풍11년명 칠성탱","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642369.jpg"},{"q":"전라남도 강진군 강진읍 만덕산에 있는 ○○○ 대웅전 안에 모셔진 삼존불(三尊佛) 가운데 본존불이다. 이 불상은 강진군 대구면 용운리에 있는 정수사에서 1951년에 옮겨 온 것이라고 전해진다. 사각형의 얼굴은 고개를 앞으로 숙이고 있으며, 두툼한 옷을 걸친 어깨는 각을 이루고 있어 다소 경직된 느낌을 주고 있다. 무릎 위에 올린 두 손은, 오른손은 손끝을 땅을 향하게 하고 왼손은 배꼽 부근에서 손바닥을 위로 향하게 하고 있다. 왼손은 별도로 만들어 끼운 것이며, 손목 끝부분에 ‘석가(釋迦)’라고 써서 이 불상이 석가여래를 표현한 것임을 알 수 있다. 불상 속에서 발견된…","a":"강진옥련사목조여래좌상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640122.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다. 경남대학교 박물관은 이중 98종 135책 1축(1,959점)을 1996년 1월 24일에 일본 야마구치현립대학(山口縣立大學)으…","a":"별장첩 Ⅰ","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913485200.jpg"},{"q":"악양 마을 북쪽 절벽에 있는 정자로, 조선 철종 8년(1857)에 세운 것이라 한다. ○○○는 전망이 아주 좋은 곳에 자리잡고 있는데, 정자 아래로는 남강이 흐르고, 앞으로는 넓은 들판과 법수면의 제방이 한눈에 들어온다. 한국전쟁 이후에 복원하였으며, 1963년에 고쳐 지어 오늘에 이르고 있다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 정자의 이름은 중국의 명승지인 ‘악양’의 이름을 따서 지었다고 전한다. 옛날에는 ‘기두헌’이라는 현판이 있었다고 하나, 지금은 청남 오재봉이 쓴 ‘○○○’라는 현판만 남아 있다.","a":"함안 악양루","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664285.jpg"},{"q":"○○○이 생긴 지 100년에 가깝다는 사실만으로도 충분히 기념적 가치 이상의 역사성을 내포하고 있으며, 건축물의 내·외부가 거의 온전히 보존되어 있고, 건축 외관의 형태를 배모양으로 고안하기 위해 수평적 가로줄을 많이 강조했기 때문에 르네상스적 기풍이 보이고 있다. 건물 전체를 콘크리트 거푸집으로 시공한 흔적이 보이며, 전면의 타일은 뒤에 다시 시공한 것으로 짐작된다. 특히 내부 수직창의 기술적 여닫이 처리와 천장 몰딩 문양의 거푸집처리는 이 건물의 돋보이는 특징으로 문화유산으로서의 가치가 있는 건물이다.","a":"부산지방기상청","c":"시도기념물","r":"부산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645226.jpg"},{"q":"전북특별자치도 김제시 황산동 ○○○ 산신각 옆에 새겨져 있는 마애불로, 1.7m 높이의 작은 바위에 선으로 불상을 새겼다. 민머리 위에는 상투 모양의 큼직한 머리묶음이 솟아 있는데, 머리는 마치 모자를 두른 것처럼 두툼하게 묘사되어 있다. 얼굴은 둥글고 원만한 편이며, 눈은 길고 가늘게 표현되어 있다. 눈썹에서 이어진 코는 큼직한 편으로 입 주위를 움푹 들어가게 묘사하여 코부분이 더욱 두드러져 보인다. 연꽃 모양의 대좌(臺座)에 앉아 있는 불상은 무릎 폭이 넓어 안정감 있어 보인다. 오른쪽 무릎은 약간 파손되었는데 원래 바위의 모양 때문인 것으로 보인다. 선으로 조각…","a":"문수사마애여래좌상","c":"시도유형문화유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639656.jpg"},{"q":"성암 권철연(1874∼1951)이 살던 집으로 건너마을 운곡에 살던 그의 아버지가 1880년경 이곳에 지은 건물이다. 선생은 조선 고종 17년(1880)에 사마시에 합격해서 생원이 되었으며, 문인명사와 애국지사들이 자주 찾아왔다고 한다. 건물은 만성봉을 뒤로 하고 동향하고 있으며, 一자형 행랑채 중앙에 있는 솟을대문을 들어서면 넓은 사랑마당이 있다. 왼쪽에는 3칸 서당마당이 있고 행랑채 맞은편에 ㅁ자형 정침이 있다. 정침은 앞면 7칸·옆면 8칸으로 구성되어 있으며, 양쪽 허리 부분에 토담을 쌓아 내외마당으로 공간구분을 하고 있다.","a":"봉화 의양리 권진사댁","c":"시도민속문화유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659007.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다. 경남대학교 박물관은 이중 98종 135책 1축(1,959점)을 1996년 1월 24일에 일본 야마구치현립대학(山口縣立大學)으…","a":"무진조천별장첩 지","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913523000.jpg"},{"q":"○○○는 대한불교 조계종 제24교구 선운사 말사로 일설에는 529년(백제 성왕 7)에 진감국사 혜소(慧昭, 774∼850) 스님이 창건하여 ○○○는 포교를 위해서, 죽림암은 수행을 위해서 지었다고 전해 온다. 1730년 필사본 <운수지(雲水誌)>에 따르면, ○○○는 ‘사자산(獅子山) 아래에 있으며, 신라 진감국사가 점지한 땅에 1595년(만력 을미년)에 최초 창건되었다.’라고 기록하고 있고, ○○○○○ 상량문과 석가여래좌상 좌대에 적힌 글씨에 의하면 1712년(숙종 38)에 창건한 것으로 보인다. 1730년 당시 ○○○에는 법당(法堂), 시왕전(十王殿), 나한전(羅漢…","a":"신흥사대웅전","c":"시도유형문화유산","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639538.jpg"},{"q":"○○○은 마을의 수호신을 모셔 놓은 곳으로, 주로 돌무더기와 나무로 되어있으며, ‘서낭당’이라고도 한다. ○○○ 마을은 나즈막한 야산 솔숲에 3개의 커다란 돌을 쌓은 삼첩석, 2개의 돌로 구성된 이첩석, 자연석 위에 모자형의 돌을 얹은 모관석, 작은 돌로 높이 쌓은 돌무더기 등이 있어 마을의 안녕과 무병장수를 기원하는 공동체신이 있는 성스러운 곳으로 여겨지고 있다. 삼첩석과 이첩석은 청동기시대 유적으로 추정되는데, 후에 풍수지리적으로 마을의 허한 곳을 보완해 주는 기능이 추가되었다. 돌무더기에서는 최근까지도 매년 정월 보름 자시(밤 11∼1시)에 유교식으로 마을제사가…","a":"안동서지리성황당","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658812.jpg"},{"q":"○○○○○으로 보다 잘 알려진 석파(石坡) 이하응(1820∼1898)이 만 71세(1891년) 때에 유모(劉某)의 부탁을 받고 그린 12폭 석란도(石蘭圖)이다. 그림들은 2폭씩 대칭구도를 이루도록 배치되어 있는데, 각 폭에는 다양한 괴석과 난초가 어울려 있다. 난초잎은 뿌리에서 촘촘히 자라나 위로 한껏 기세를 뿜으며 부드럽게 퍼지게 표현되었는데, 전형적인 그의 후기 난초의 모습이 잘 나타나 있다. 바위의 경우 당시의 서화가인 정학교(丁學敎, 1832∼1914)가 그린 괴석의 영향을 반영하여 각진 형태의 바위가 첩첩이 쌓인 모습, 기타 부드러운 바위 등을 폭에 따라 배…","a":"흥선대원군 이하응필 묵란도","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636335.jpg"},{"q":"장도 청해진으로부터 서북쪽으로 약 2㎞ 떨어진 상왕산 아래에 있는 ○○○터이다. ○○○는 주민들에 의해 전해진 구전내용과 문헌기록으로 미루어 보아 통일신라 말 장보고(?∼846)가 지은 절로 그의 해상활동과 긴밀한 관련이 있었던 것으로 추정된다. 당시 이 절은 신라 문화의 해외진출과 함께 입당한 구법승들의 중간휴식처 구실을 했으며, 중국 당나라에서 일본에 파견된 사절단들의 영빈관 구실도 겸했다고 한다. 또 중국의 산동성 적산촌에 있는 법화원과도 서로 교류가 되었던 곳이다. 법화원 역시 통일신라의 절로 장보고가 지었다고 하며, 이곳에 우리나라 승려는 물론 특히 일본승려…","a":"완도법화사지","c":"시도기념물","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102217303400.jpg"},{"q":"경사진 대지에 자리잡고 있는 집으로 앞쪽에 사랑채를 배치하고 뒷쪽에 안채를 두었다. 안채는 조선 후기에 짓고 1924년 경에 고친 것으로 추정한다. 안채는 큰방·작은방·부엌 이외에는 모두 마루를 꾸며 특이한 평면을 이루고 있으며, 평면에 따라 지붕의 형태가 다르다. 사랑채 지붕은 원래 초가지붕이었다고 하며 매우 간소하게 꾸몄다.","a":"나주김효병가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658361.jpg"},{"q":"경은(耕隱) ○○○은 조선개국 공신 조반의 아들로 태종14년(1415) 문과에 급제하여 장령을 지내고 세종13년(1431)에 춘추관 기주관이 되어 태종실록 편찬에 참여하였다. 그 뒤 우관원을 거쳐 경상도 관찰사, 형조참의 등을 역임하고 1441년에 도승지를 지냈으며, 1443년 이조참판이 되었다. 그의 만년에 이조참판을 그만두고 부친 조반의 별업(별장)인 가정(佳亭)에 은거하였다. 그가 은거하자 세종은 궁중화가를 보내 가정의 모습을 그리게 하였고 이후 많은 선비들이 가정을 주제로 시를 지었으며 안평대군은 이를 모아 <석호가정별업도>라는 서화집을 만들기도 하였다. 세종…","a":"조서강 묘","c":"시도기념물","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645516.jpg"},{"q":"임진왜란 때 행주산성에서 왜군을 물리친 권율(權慄 1537∼1599) 장군의 공적을 기념하기 위해 세운 비이다. 임진왜란이 끝난 후 권율의 휘하에 있던 장졸들이 권율 장군의 공적을 기리고자 1602년(선조 35) 행주산성 정상에 건립하였다. 비문은 최립(崔岦)이 짓고 글씨는 한호(韓濩)가 썼으며 전액(篆額 ; 전서체로 비석의 이름을 새긴 부분)은 김상용(金尙容)이 썼다. 뒷면의 비문은 권율 사위인 이항복(李恒福)이 글을 짓고 김현성(金玄成)이 글씨를 썼다. 사각형의 받침돌에 위가 둥근 대리석 비신을 세우고 비문을 새겼는데 마모가 심해지자 1845년(헌종 11)에 원문…","a":"행주대첩비<구비>","c":"시도유형문화유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637455.jpg"},{"q":"○○○는 신라 진평왕 25년(603)에 진나라에서 유학하고 돌아온 대덕 지명법사가 세운 절이다. 이 절의 중심 건물인 ○○○은 지은 시기를 알 수 없고 다만 조선 숙종 3년(1677)에 중건한 것으로 그 후 몇 차례 중수가 더 있었다. 현재의 건물에는 1932년의 대대적인 중수에 의한 양식적 특징이 주로 남아 있다. 이 건물은 조선후기 목조불전으로 정면 3칸·측면 2칸의 다포계 팔작지붕이며, 바닥에는 마루를 깔았다. 천장은 우물 정(井)자 모양으로 꾸며 천장 속을 가리고 있는 형태이다. 가운데칸 뒷부분에는 불단을 마련하여 삼존불상을 모셔 놓았다.","a":"포항 보경사 대웅전","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641271.jpg"},{"q":"○○○는 천개산에 있는 절로 기록에 의하며 통일신라말 애장왕 6년(805)에 도선국사가 세웠다고 한다. 세울 당시에는 계곡을 중심으로 양쪽에 묘덕사와 쌍계사 두 절이 있었는데 후에 쌍계사는 수정사라 이름을 바꾸었다. 한동안 폐허가 되었던 것을 중종 19년(1524)다시 지으면서 ○○○라 이름을 바꾸었고, 이후 여러 차례 다시 짓거나 수리를 하였다. ○○○○○은 절의 중심에 있는 법당으로 석가모니를 모시고 있으며 4번에 걸쳐 수리한 기록이 있다. 앞면 3칸·옆면 2칸의 겹처마로 가장 단순한 맞배집이다. 자연석 기단 위에 기둥을 세웠으며, 지붕 처마를 받치는 공포가 기둥…","a":"정수사대웅전","c":"시도유형문화유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639941.jpg"},{"q":"○○○에 보관된 이 ○○○는 ○○○를 다시 짓기 위한 목재보관소 옆에서 다른 장대석 등과 함께 출토되었는데, 명문을 보면 “이 산은 다만 제단과 옛 절 뿐만 아니라 국내에 있어서 대단히 중요하다. 이 산 전체를 영세토록 금지하여 보호할 일이다. 일영(日營)이 제목을 짓고, 신해(辛亥) 10월에 세운다.”라고 되어 있다. ○○○는 고려 의종 원년(1146)에 각화사 주지인 성원이 암자를 지으면서 개창되었다. 1896년에 불타버린 것을 이후 다시 지어 오늘에 이르고 있다. 높이 131㎝, 가로 45㎝, 세로 17㎝ 규모로 앞면에 34자, 오른쪽 옆면에 9자의 글자가 새겨…","a":"안동용수사금호비","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663290.jpg"},{"q":"○○○에 보존되어 있는 ○○○인데, ○○○은 칠성(七星)을 불교의 호법선신(護法善神)으로 수용하고 이를 의인화하여 묘사한 그림이다. 이 ○○○은 모두 비단 바탕에 채색하여 그려진 것으로, 치성광여래삼존도(熾盛光如來三尊圖), 칠성도(七星圖), 성군도(星君圖) 등이 묘사되어 있다. 치성광여래삼존도는 화면이 상하 2단 구도로, 상단부는 수묵담채풍의 산수화를 담은 10폭 병풍을 배경으로 치성광여래좌상이 중앙에 있고 그 좌우에 일광·월광보살과 권속들이 시립하고 있다. 하단부에는 중국풍의 도복(道服)에 재관집홀상(載冠執笏狀)의 성군(星君) 도상이 있고, 그 좌우에 권속들이 시립…","a":"양산 통도사 동치5년명 칠성탱","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642366.jpg"},{"q":"조선 후기의 무신인 야당(野堂) 유혁연(1616∼1680)의 묘소이다. 충청남도 서산에서 태어난 그는 어려서부터 재주가 뛰어났으며, 대대로 무신의 집안에서 자랐다. 인조 22년(1644) 무과에 급제하여 벼슬길에 올라 삼도 수군통제사, 공조판서, 형조판서 등의 요직을 거치면서 어려운 일들을 잘 처리하였다. 예송(禮訟)으로 당쟁에 연루되어 관직이 삭탈되고, 숙종 16년(1680)에 경상도 영해로 유배되었다. 또한 무예에도 뛰어나 무신의 시험에서 줄곧 수석을 차지하였으며, 전략과 군사행정면에서 뛰어난 재능을 발휘하였다. 화차(火車)의 사용을 권장하고 병서의 연구를 강력하…","a":"류혁연의묘","c":"문화유산자료","r":"대전광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659732.jpg"},{"q":"이것은 1451년 여씨향약을 기본으로 실시된 광주향약을 본받아 1488∼1505년사이에 이루어진 동약(마을의 향약)이다. 특히 광주향약은 이선재에 의해 발의되었으며, 초기의 좌목(座目)에 기축옥사에 연루되어 희생당했던 이선재의 5대손인 이발이 있는 것으로 보아 그와 연관되었음을 짐작할 수 있다. 하지만 이 동약은 임진왜란으로 인해 중단되었다가 선조 37년(1604)에 중수되어 오늘날까지 그 틀을 잃지 않고 전해 내려오고 있다. 중수하게 된 연유에 대해서는 유사경이 쓴『동적입의서』에 잘 나타나 있다. ○○○ 동약은 모두 4권의『좌목』으로 구성되었는데, 여기에는 동계원의…","a":"양과동계고문서","c":"문화유산자료","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659673.jpg"},{"q":"○○○는 조선시대에 군사훈련 지휘소가 있던 곳으로, ○○○도들의 목을 베던 처형장이었다. 당시엔 숲이 칙칙하게 우거져 “숲머리” 혹은 “○○○”라 불렀다. 1801년 ｢신유박해｣ 때, 전라도의 첫 ○○○ 사도 유항검(아우구스티노)의 아내와 제수, 맏며느리 이순이(루갈다) 등이 이곳에서 순교했다. 1839년 ｢기해박해｣ 때는, 신태보(베드로), 이태권(베드로), 이일언(욥), 정태봉(바오로) 등이 순교했다. 1866년 ｢병인박해｣ 때는 경문호(바르톨로메오), 손선지(베드로), 한재권(요셉), 조화서(베드로), 이명서(베드로) 등이 순교했다. 1867년에는 김사집(필립보…","a":"숲정이<천주교순교지>","c":"시도기념물","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653565.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공민왕(재위 1351∼1374) 때 월곡리에 있던 학당사을 옮겨온 것으로, 조선 중종 7년(1512)에 다시 지었다. ○○○은 선조 38년(1605)에 수리하였고, 1974년에 기와를 보수하였다. 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은…","a":"고창향교 대성전","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661707.jpg"},{"q":"이 불화는 ○○○ 대웅전의 향우측벽에 봉안되어 있는 ○○○로, 여러 부분에 오염으로 인한 얼룩이 있으며, 현재는 액자에 끼워 봉안하고 있는데 전체적으로 채색이 변색되어 어두운 편이다. 그림 상단에는 범천(梵天)과 제석천(帝釋天)을 중심으로 천부중(天部衆)을 배치하였으며 하단에는 위태천(韋駄天)을 중심으로 천룡팔부(天龍八部)를 표현하였다. 범천과 제석천은 보살 옷에 보관을 쓰고 두 손을 모아 흰 연꽃을 들고 정면을 향해 서있는데 그 주위로는 일궁천자와 월궁천자를 비롯하여 당(幢)과 번(幡), 부채 등의 장엄구를 든 동자, 동녀들과 주악천 등이 둘러싸고 있다. 하단 중앙…","a":"개운사 신중도","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593257.jpg"},{"q":"3폭의 조선후기 탱화는 화기(畵記)상의 기록으로 보아 안동(安東) 중대사(中臺寺)에 봉안된 것인데 언제 어떠한 연유로 ○○○에 이안(移安)되었는지는 알 수 없다. 한국사찰전서와 한국불교 사학대사전 기록에 의하면 중대사는 경상북도 안동군 풍산읍 서미동 학가산(鶴駕山)에 있는 절이다. 신중탱화(神衆幀畵)는 정방형에 가까운 형태로 상하 2단 구도로 상단에는 범천(梵天)과 제석천(帝釋天)을 위시한 천부(天部)와 주악선신이 배열되어 있고, 하단에는 위태천을 위시한 천룡팔부중이 다시 2단으로 배열되었는데 수인(手印)을 결한 왼손과 오른손으로 삼고저를 들고 서 있는 위태천, 그…","a":"안동대원사소장탱화","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641077.jpg"},{"q":"○○○○○은 정면 4칸, 측면 1.5칸 규모로 전면의 반칸을 퇴칸으로 한 축조한 형식이다. 대청에는 우물마루를 깔았으며 우측방의 전면 툇마루는 한단 올려 대청과 높이가 다르게 시설하였다. 방의 창호는 모두 세살문을 사용하고 있다. 좌측방에는 두짝, 우측방에는 외짝의 세살문을 달았고 대청의 뒷벽에는 판장문을 달아 고급스럽지는 않지만 소박한 형태이다. 3량 가구 형식으로 중앙부에 대들보를 걸고 전면의 퇴칸에는 퇴보를 걸어 연결하였으며 큰 장식은 보이지 않는다. 처마는 홑처마이고 지붕은 박공지붕 형식이다. 건립기록을 찾을 수 없으나 1900년 전후에 건립된 것으로 추정된다…","a":"창녕 관산서당","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665031.jpg"},{"q":"○○○ 종루에 매달려 있는 이 ○○은 높이 127.0cm, 종구(鐘口) 지름 92.5cm인 규모가 제법 큰 범종이다. 천판(天板) 정상부에 쌍룡의 용뉴(龍鈕)가 조형되어 있고, 동체 윤곽선이 아래로 가면서 서서히 배가 부른 원만한 곡선미를 보여 주고 있다. 종신(鐘身)에는 유곽(乳廓), 보살상, 전패(殿牌)가 양각되어 있는 등 조선 후기 ○○ 양식을 보여주고 있다. 또한 종신에는 주성한 시기, 무게, 주종자, 산중질(山中秩), 시주자, 연화질(緣化秩) 등의 명문이 양각으로 새겨져 있는데, 산화로 인해 표면이 푸른색을 띠고 있는 것 외에는 파손된 부분이 없이 보존 상태…","a":"범어사 동종","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636769.jpg"},{"q":"○○○은 고려 개국공신으로 ○○양씨 문중에서 시조로 삼고 있고, ○○는 형태가 팔각형의 죽절형(竹節形) 모서리 기둥을 새긴 호석(護石)을 두른 특이한 양식이다. 일부 풍화되고 결실된 부분을 보수한 흔적이 있으나, 고려시대 분묘 유적으로 그 유례가 희귀하다. ○○○의 15대손 ○○○은 조선시대 초기의 인물로 급제 후 예조정랑까지 오른 효자로 이름난 인물이다. ○○○과 ○○○은 ○○지역의 인물사에 중요한 부분을 차지하고 ○○가 원위치에 원형대로 보존되어 있어 하나로 묶어 보호할 필요가 있다.","a":"충주 양능길·양여공 묘소","c":"시도기념물","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651649.jpg"},{"q":"범어사에 보존되어 있는 1쌍의 ○○○로, 조선 헌종의 아버지인 문조 익황제와 어머니인 신정 익황후의 명복을 비는 내용을 수놓은 것을, 광무 6년(1902) 범어사의 암자인 계명암에서 나라의 편안함과 왕실의 번성을 위해 나라제사를 치를 때 황실에서 하사한 것이다. 각각 남색과 붉은색 바탕의 공단으로 되어있고, 금실과 명주실을 사용하여 여러 가지 방법의 기법으로 수를 놓았다. 문조와 신정황후 조씨의 명복을 비는 내용인 서원문을 가운데에 금실로 수놓았으며, 윗부분은 연꽃잎 모양을, 아래부분에는 연꽃 무늬를 넣어 화려하게 장식하였다. 밑부분에는 양 모서리에 수술을 달아서 장…","a":"황실축원장엄수","c":"시도민속문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658092.jpg"},{"q":"이 영정(○○○○○영정)은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 화면상단엔 금장식이 매달린 풍대를 묘사하였고 선사의 왼손엔 불자를, 오른손에 염주를 쥐고 있다. 화면 향좌측에 주지묵서의 '선교양종대선사○○○○○지진(禪敎兩宗大禪師三星堂暑澄之眞)' 화제가 있으며 '가경이십년...조성(嘉慶二十年...造成)‘이란 배면묵서가 있다. 화면크기는 가로82.2cm, 세로122.5cm이다.","a":"삼성당 서징 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642989.JPG"},{"q":"1919년 3·1 운동이 전국적으로 전개되자 유림측에서도 프랑스의 파리에서 개최되는 강회회의에 한국독립을 호소하는 장문의 서한을 작성하여 보낸 일이 있다. 일명 파리장서 사건이라 하는데, 이곳 ○○○○와 ○○○은 유림들이 모여 서한을 작성하고 총의를 모아 준비한 결집장소로 사용되었다. ○○○○는 앞면 4칸·옆면 1칸 반의 규모이며, 지붕은 옆에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 독특한 조형미를 살리고 있다. ○○○은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. ○○○○는 건축의 짜임새 및 구조 상태가 우…","a":"산청 용강정사,임리정","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664442.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 처음 지어진 연대는 알 수 없으나, 윤탁이 대성전에 은행나무를 심도록 권장하였다는 기록과 현재의 은행나무 나이를 짐작하여 조선 전기인 1400년대로 추정된다. 현재 남아있는 건물은 대성전·동재·서재·명륜당 등이 있다. 앞쪽에 명륜당을 중심으로 배움의 공간을 두고, 뒤쪽에 대성전을 중심으로 제사공간을 두고 있어 전학후묘의 배치형식을 따르고 있다. 조선시대에는 국가로부터 토지, 노비, 책 등을 지급받아 학생들을 가르쳤으나 갑오개혁(1894) 이후에 교육적 기능은 없어지고 봄·가…","a":"강진향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639975.jpg"},{"q":"되재성당은 1895년 한국 천주교회에서 서울 약현성당에 이어 두 번째로 완공된 성당으로 한강 이남에서는 처음 세워진 성당이며, 최초의 한옥성당으로 추정하고 있다. 그러나 한국전쟁 때 성당건물이 전소되었고 그 자리에는 1954년에 다시 세운 공소건물이 자리하고 있다. 이 성당은 서양의 바실리카식 교회건축양식을 한식 목구조로 번안한 한옥성당으로서 새로운 문화의 토착화 과정을 보여주는 최초의 한옥성당으로 추정하고 있다. 1895년에 세워진 되재성당의 본디 보습은 제8대 조선교구장이었던 뮈텔주교(Gustave Charles Marie Mutel)의 일기와 사진자료 등을 통해…","a":"되재성당지","c":"시도기념물","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653828.jpg"},{"q":"이 서당은 문옹汶翁 김석견金石堅, 1546~1614 선생을 봉향하기 위하여 조선 정조正祖 22년1798에 창건된 두산사斗山祠에 기원을 두고 있다. 그 후 고종 9년1872에 훼철毁撤 되었다가 1919년 고쳐 지으면서 ○○○○으로 편액扁額되었다. 서당이면서 제향을 하는 사우祠宇를 갖추고 있으며, 일반적인 배치 형식에서 벗어나 지형 조건에 순응하여 서당과 전사청典祀廳 등을 나란히 배치한 점이 특징이다. 김석견은 임진왜란 당시 세 아들과 함께 의병을 일으켜 ○○성 수복 등에 큰 공을 세웠으며, 선조 38년1605에 선무원종공신宣武原從功臣으로 문서에 기록되었다. 또한 세상을…","a":"경주 두산서당","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663763.jpg"},{"q":"광주광역시 북구 무등산에 있는 성터로, 무등산의 북쪽 지맥인 장원봉을 중심으로 잣고개의 장대봉과 제4수원지 안쪽의 산 능선을 따라 타원형으로 만들어졌다. 성벽은 바닥에 5단 정도를 돌로 쌓아올리고, 그 위의 성벽을 잡석으로 채우는 방식이다. 성벽의 남북 길이는 1000m이고, 동서의 너비는 약 500m, 둘레는 3500m에 달하는 규모가 큰 성이다. 성안에서 ‘관(官)’, ‘국성(國城)’ 등의 글자를 새긴 기와조각들과 새, 귀신의 얼굴을 새긴 막새기와, 그리고 순청자, 상감청자 자기조각들이 발견되었다. 특히 잣고개 남쪽 위층 건물터에서 발견된 새무늬 수막새에는 다른…","a":"무진고성지","c":"시도기념물","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645754.jpg"},{"q":"조선 중기 문신인 노수신(1515∼1590) 선생의 덕을 추모하기 위해 세운 건물이다. 그는 중종 38년(1543) 문과를 급제하고 성균관의 전적(典籍)을 거쳐 사서(司書) 등의 벼슬을 하였으나 을사사화 때 파직되어 19년간 섬(진도)에서 귀향살이를 하였다. 그곳에 있으면서 이황 등과 서신으로 학문을 토론하고 1567년 『숙흥야매잠』, 『대학장구』등의 주해를 달아 사림 사이에서 명성을 쌓았다. 선조가 즉위하면서 기용되어 벼슬이 영의정까지 올랐다. 그는 시, 문, 서예에 뛰어났으며 양명학을 깊이 공부하고 승려인 휴정과도 교분을 나눴다. ○○○ 경내에는 산 기슭 아래쪽에…","a":"옥연사","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662769.jpg"},{"q":"사계 김장생의 아들이며, 신독재 김집의 아우인 사일 ○○ 선생의 묘이다. 사마시에 합격하여 성균관 유생이 되었으나 계축옥사(癸丑獄事)가 일어나자 벼슬길을 단념하고 고향으로 돌아와 10년간 은거하며 학문을 연구하였다. 인조반정 후에 이괄의 난이 일어났을 때 인조를 호위하여 공주(公州)까지 모셨다. 왕이 공주에 있을 때 정시문과에 급제한 후 여러 벼슬을 거쳐 대사간에 이르렀으며, 병자호란이 일어나자 다시 왕을 호위하여 강화도로 모셨다. 그 뒤 대사헌·예조참판·병조참판·이조참판 등을 거쳤으며 세상을 떠나자 영의정으로 벼슬이 높여졌다. ○○의 묘가 있는 대전광역시 유성구 전…","a":"김반·김익겸의묘","c":"문화유산자료","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659698.jpg"},{"q":"요지는 자기나 기와, 그릇 들을 만들어 굽던 가마터를 말한다. 웅천 가마터는 보배산 기슭의 점골에 자리잡고 있으며, 조선시대 분청사기를 생산하던 곳으로 두동요지, 금곡요지 등으로 알려져 있다. 도굴로 파괴된 가마터와 가마터 주변에서는 사발, 대접, 접시류를 비롯하여 귀얄문과 덤벙무늬 분청사기가 출토되고 있다. 이로 보아 이 가마터는 조선시대 분청사기가 백자로 변해가는 마지막 단계인 15∼16세기에 만들어 운영되다가 임진왜란으로 폐요되었을 것으로 추정한다.","a":"창원 웅천도요지","c":"시도기념물","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655940.jpg"},{"q":"○○○○○은 흔히 법화경(法華經)으로 불리며, 화엄경(華嚴經)과 더불어 한국 불교의 근본 경전 중 우리나라에 유포된 불교 경전 가운데 가장 많이 간행된 경전이다. ○○○○에서 소장하고 있는 ○○○○○은 인조 10년(1632) 삭령 용복사(龍腹寺)에서 간행된 7권 3책과 인조 27년(1649) 양산 통도사(通度寺)에서 간행된 7권 3책 등 총 14권 6책의 목판본으로서 간행된 연도와 간행처가 명확하여 수많은 ○○○○○의 간행 내역 등을 밝히는데 표식이 되는 자료이다.","a":"내원정사 묘법연화경","c":"시도유형문화유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636684.jpg"},{"q":"조선 고종 12년(1875)에 봉촌 최상룡이 행정사무를 볼 수 있도록 마을사람들과 의논하여 지은 것이다. 원래 이 자리에는 달성군 공산면 4개 마을(강동·독좌·위남·단산)에서 쓰던 초가 사무소가 있었다. 이 4개 마을을 합쳐 봉무동으로 행정구역이 바뀌자 초가를 헐고 이 건물을 지었다. 강당을 중심으로 동쪽에 덕교재, 서쪽에 예용재가 있다. 강당은 농민들의 계몽과 마을 규약 등을 가르치고, 선비들이 모여 시를 짓고 풍류를 즐기던 곳이다. 덕교재와 예용재는 마을사람들이 모여 의논하던 곳이다. 화강석의 둥근 초석 위에 둥근 기둥을 세운 5칸 규모의 집으로 지붕은 옆면이 사…","a":"봉무정","c":"시도유형문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636852.jpg"},{"q":"아양리에 있는 3층 석탑으로, 1935년 탑골이라 불리는 곳에서 밭을 갈던 중 박학중 씨가 발견하여 세워 놓은 것이다. 발견 당시 기단부(基壇部)와 머리장식이 사라진 상태였으며, 현재 3층을 이루는 탑신(塔身)만이 남아 있는데, 그나마 탑신의 2·3층 몸돌은 탑을 옮겨 세울 때 새로 만들어 놓은 것이다. 탑신의 몸돌에는 모서리마다 기둥 모양을 새겼고, 지붕돌 밑면에는 4단의 받침을 두었다. 탑신의 1층 몸돌과 3층 지붕돌은 원래 탑의 석재가 확실하며, 몸돌의 기둥 모양 조각과 지붕돌의 받침 조각 수법은 우수한 편이다.","a":"거제 아주동 삼층석탑","c":"문화유산자료","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663856.jpg"},{"q":"주촬산 남쪽 기슭에 위치한 위봉사는 처음 지어진 연대는 확실하지 않다. 통일신라말 최용각이라는 사람이 이곳에서 세 마리의 봉황이 절터를 에워싸고 싸우는 모습을 보고 위봉사라 하였다고 전한다. 조선 고종 5년(1868) 포련선사가 60여 칸의 건물을 지을 당시만 해도 큰 규모의 사찰이었으나, 여러 번의 화재로 인해 지금은 그 규모가 매우 축소되었다. 현재는 보광명전과 칠성각·시왕전·요사채 정도의 건물만이 남아있다. 요사는 스님들이 생활하는 공간을 말하는데, 위봉사의 요사채는 앞면은 극락전으로 뒷면은 요사로 사용되는 특이한 구조를 가지고 있다. 위봉사에는 『묘법연화경판』…","a":"위봉사요사","c":"시도유형문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639469.jpg"},{"q":"조선 중기 문신인 오리 ○○○의 묘와 ○○○이다. ○○○은 1569년(선조 2)에 별시문과에 급제한 뒤 여러 관직을 거쳤으며, 임진왜란 때는 평양탈환 작전에 성공하여 우의정을 거쳐 영의정에 올랐다. 1608년(광해군 즉위) 대동법을 건의하여 불합리한 조세제도를 시정하고 백성의 부담을 덜었다. 여섯 차례나 영의정을 지냈지만 오막살이 초가에서 청빈하게 살아 청백리에 선정되었다. 그의 묘는 부인과의 합장묘이며 봉분이 2기인 쌍분이다. 봉분 앞에 묘비·상석·향로석 등이 있고, 좌우에는 멀리서도 무덤이 있음을 알려주는 망주석(望柱石)과 문인석이 각 1쌍씩 서 있다. ○○○○○…","a":"이원익선생묘및신도비","c":"시도기념물","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646261.jpg"},{"q":"영장산 중턱의 ○○○ 암벽에 새겨진 마애불이다. 벽면에 방형의 감을 파고 그 안에 불상을 꽉 차게 돋을새김 하였다. 같은 벽면에는 14개의 방형 구획을 파고 글을 새겼다. 새겨진 글 가운데 하나에 의하면 광무 1년(1897)에 이규승이 관음상을 새기고 절을 세웠다고 한다. 마애불은 보살상이 아닌 것으로 파악되므로 이규승의 관음상과는 무관한 것으로 보이지만 이를 통해 마애불의 조성시기를 유추해볼 수 있다. 불상은 민머리를 하고 있다. 얼굴은 상당히 높게 돋을새김 하였고 어깨는 넓은 편이다. 얼굴 세부는 명확하게 알아보기 어렵지만 얼굴 중앙에 약간 길게 자리한 코가 오똑…","a":"망경암마애여래좌상","c":"시도유형문화유산","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637529.jpg"},{"q":"사찰에서 법회法會나 의식意識이 있을 때는 당幢이라는 깃발을 달았다. 당을 매달았던 긴 장대를 ‘당간幢竿’이라고 하며, 당간을 지탱하기 위해 양쪽에 세운 2개의 돌기둥을 ‘○○○○’ 라고 한다． ○○○에는 나란히 2쌍의 ○○○○가 서 있는데, 높이는 동쪽 ○○○○가 3.6m, 서쪽 ○○○○가 3.45m이다. 각 기둥의 안쪽 면에는 쐐기목을 박아 당간을 고정시켰던 홈과 구멍이 뚫려 있으며, 서쪽 ○○○○ 사이에는 당간을 받쳤던 둥근 받침대가 남아 있다. 동쪽 ○○○○는 통일신라 때 세워진 것이지만, 서쪽 ○○○○는 기둥 크기와 제작 수법에 차이가 있는 것으로 보아 각기…","a":"불국사 당간지주","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110419180100.jpg"},{"q":"충청남도 홍성군 홍성읍 ○○○에 있는 불상으로 광경사지 미륵불이라고도 불린다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았고, 얼굴은 눈·코·입을 낮게 돋을새김하였다. 주먹코와 두툼한 입술, 길다란 눈 등이 매우 익살스러운 표정을 만들고 있다. 신체의 윤곽은 선으로 표현했으며, 앞면에만 조각을 하였다. 양 어깨를 감싼 옷을 걸치고 있으며, 가슴에서 발까지 U자형의 옷주름을 새겼다. 오른손은 가슴에 붙이고 왼손은 손바닥이 보이게 들고 있다. 조각수법이 거칠고 비례감각이 없는 점으로 보아 조선시대에 민간신앙의 대상으로 만들어진 듯하다.","a":"대교리석불입상","c":"문화유산자료","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661155.jpg"},{"q":"조선 전기에 지어 해안 방비를 담당하였던 방답진의 군관청이다. 방답진은 전라좌수영에 속해 있던 것으로 중종 18년(1523)에 설치됐고, 고종 32년(1895)에 폐지되었다. 1896년 돌산군이 설치되면서 건물의 대부분이 돌산군 행정관아로 사용되었다. 관청을 지은 것은 1872년∼1895년 무렵으로 추정되며, 고종 9년(1872)에 쓴 『방답진지도』에는 현재의 위치에 배를 두었던 곳이 있었던 것으로 나타나 이후에 관청이 지어진 것으로 보인다. ㄷ자형 평면구성이며 지붕은 옆면에서 볼 때 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 각 실은 여러 개의 방으로 구…","a":"돌산군관청","c":"시도유형문화유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640056.jpg"},{"q":"고려 후기 판전의사 좌시중을 지낸 창성부원군 ○○○ 선생과 조선 초기 경상도 병마절도사, 초토안무사를 지낸 ○○○ 선생의 묘이다. 봉분 아래에는 둘레석을 두르고 있으며, 비석은 높이 1m 정도이다. 이 묘들은 고려와 조선 초기의 전형적인 양식을 띠고 있어 당시의 묘제 연구에 귀중한 자료가 되고 있다.","a":"창녕 조우희, 조익수 묘","c":"시도기념물","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655046.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398)에 지금 위치 북쪽에 처음 지었다. 호랑이로 인한 피해가 심해지자 숙종 18년(1692)에 향로산 서쪽으로 옮겼으나 지대가 습하여 순조 34년(1834) 이후 지금 있는 자리로 다시 옮겼다. 현재의 향교 건물들은 그 후 몇 차례의 보수를 한 것이다. ○○○은 공자를 비롯하여 중국 유학자의 위패를 모시고 제사를 지내는 곳으로 규모는 앞면 3칸·옆면 2칸이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 조선시대에는…","a":"무주향교 대성전","c":"문화유산자료","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661717.jpg"},{"q":"이 비석은 동래부사 강필리(姜必履)가 온정을 대대적으로 수리한 공로를 기리기 위하여 1766년(영조 42)에 세웠는데, 송광적(宋光迪)이 썼다. 동래온천에 대한 최초의 기록은 신라의 재상 충원공(忠元公)이 이곳에서 목욕을 하고 돌아갔다는 삼국유사의 기록이다. 동래부읍지(東萊府邑誌) 산천조 온정란에 보면, 동래온천은 신라시대부터 알려져 있었음을 알 수 있다. 온천의 물이 계란을 익힐 만큼 뜨거웠으며, 병자가 목욕을 하면 병이 잘 나아 예로부터 많은 사람들이 찾았다고 한다. 비는 높이 144cm, 폭 61cm이다. 비문에 따르면, 1691년(숙종 17)에 고쳐 세운 온정…","a":"온정개건비","c":"시도기념물","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645001.jpg"},{"q":"이광윤은 고려 문절공 이행(李行)의 6대손으로, 호는 중임(仲任)이며 명종2년(1546) 충청남도 청양에서 태어났다. 천성이 인자하고 의리를 존중하며 효로서 부모를 봉양하더니 33세가 되던 해 효행으로 추천을 받아 생원시에 응시하여 문소전참봉이 되었으나 사양하였다. 임진왜란이 일어나 왜적이 부산과 동래를 함락하고 북쪽으로 쳐들어오자 친척과 친구, 동네의 장정들 300여 명을 모아 청주 작전에 참가하였다. 청주성 탈환작전에서 승려인 영규대사와 합세하여 성을 포위하고 격전을 벌여 마침내 청주성을 탈환하였다. 승전의 기세로 금산지역으로 향했으나 이미 주둔하고 있던 왜적의…","a":"이광륜묘","c":"시도기념물","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651898.jpg"},{"q":"조삼(趙參)선생이 후진양성과 남은 여생을 보내기 위해 지금의 자리에 직접 지은 정자로서 자신의 호를 따라 ○○○이라 명명하였다. 무진선생은 1473년(성종 4년)에 태어나 성종 20년(1489) 진사시에 합격하고 중종 2년(1507) 문과에 급제하였다. 함양 · 창원 · 대구 · 성주 · 상주의 부사와 목사를 역임하고, 내직으로 사헌부(司憲府) 집의(執義) 겸 춘추관(春秋館) 편수관(編修官)을 지냈다. 앞면 3칸 · 옆면 2칸의 건물로 지붕은 옆면이 여덟 팔자 모양과 비슷한 팔작지붕이다. 앞면의 가운데 칸에는 온돌방이 아닌 마루방으로 꾸며져 있고, 정자 바닥은 모두…","a":"함안 무진정","c":"시도유형문화유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641753.jpg"},{"q":"1876년에 제작된 이 ○○○○는 원래 무량수전(無量壽殿)에 안치되었던 불화로서, 현재는 ○○○에 모셔져 있다. 화면에는 지장보살좌상을 중심으로 十王과 그 권속이 함께 그려져 있다. 중앙의 지장보살삼존 좌우로 왼쪽에는 홀수의 시왕과 판관, 사자, 옥졸 등을, 오른쪽에는 짝수의 시왕과 판관, 사자, 옥졸 등을 배치한 형태이다. 여기에 화면 상단의 지장보살 주위로 6보살이 좌우 대칭으로 첨가되어 있다. 문양의 생략, 음영이 심한 옷주름 표현, 적색, 녹색, 청색, 황색, 흰색 등의 두드러진 채색 등에서 19세기 말경의 양식적 특징을 잘 나타내고 있다.","a":"문경대승사명부전지장탱화","c":"문화유산자료","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663643.jpg"},{"q":"『○○○○○』은 조선시대 대표적인 여류시인 허○○○이 남긴 210여수의 작품을 모은 시문집으로, 이를 동생인 『홍길동전』의 작가 허균이 목판으로 간행하였다. 허○○○의 본명은 초희(楚姬)이며, ○○○은 호이다. 아버지인 허엽과 형제인 허성, 허봉, 허균은 ‘초당오문장(楚堂五文章)’이라는 이름이 붙을 정도로 문장가의 가문이었다. 선조 22년(1589) 허균이 27세라는 젊은 나이로 숨진 누이 허○○○이 남긴 원고 모아 『○○○고』를 편집하여 오언고시 15수, 칠언고시 8수, 오언율시 8수, 칠언율시 13수, 오언절구 24수, 칠언절구 142수를 싣고 부록으로 「광한전…","a":"난설헌시집목판초간본","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638182.jpg"},{"q":"『○○○○』으로 현재까지 알려진 것 중 가장 오래된 것은 조선 제8대 예종 원년(1469)에 갑인자(甲寅字)로 찍어낸 것이다. 이 갑인자본은 지금 전해지지 않는다. 그 다음으로 오래된 것이 을해자활자본(乙亥字活字本)으로 찍어낸 이 방목이다. 이 책과 동일한 『○○○○○』은 현재 옥산서원(玉山書院)에 소장되어 있는데 보물 제524호로 지정되어 있고, 그 해에 발행한 『○○○○문무잡과방목(正德癸酉文武雜科榜目)』은 강릉의 심교만 씨가 소장하고 있는데 역시 보물 제603호로 지정되어 있다. 현재 우리나라에 전해지고 있는 생원·진사방목은 조선시대 전체 생원 진사시 229회 중…","a":"정덕계유 사마방목","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642414.jpg"},{"q":"조선시대 능주지방에 파견된 지방관이 업무를 보던 건물인 녹의당의 정문이다. 선조 32년(1599)에 문을 수리했다는 기록으로 보아, 능주목사로 부임한 정윤이 녹의당을 지을 때 함께 지은 것으로 보인다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다．지붕 처마를 받치기 위해 장식하여 만든 공포는 간결하게 짜여 있다. 건물에는 당대의 문필가인 정이(1568∼1625)가 쓴 현판이 걸려 있다. ○○○○○은 전라남도에서 보기 드문 구조를 가진 간결하고 아름다운 건물이다.","a":"죽수절제아문","c":"문화유산자료","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661993.jpg"},{"q":"○○○○○은 17세기 후반에서 18세기 초반의 잔존 예가 드문 산신도로서 고승 영정 구도와 비슷하면서 호랑이 뒤의 단아한 두 동자의 배치가 돋보인다.","a":"하동 금정사 산신탱","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643199.jpg"},{"q":"이 범종은 고려시대의 ○○범종(靑銅梵鐘)으로, 종신(鐘身)에 새겨진 명문으로 볼 때 13세기경에 조성된 것으로 추정된다. 전체 높이가 25cm, 종구(鐘口)의 넓이가 15cm로 고려후기에 유행한, 선종사찰에서 사용 하던 범종으로 추정된다. 용뉴(龍鈕)는 한 발을 앞으로 내밀고, 한 발은 뒤로 짚고 있는 단룡(單龍)의 형상을 취하고 있다. 입을 벌리고 앞을 향해 나아가는 듯한 자세를 취하고 있으며, 용의 몸뒤쪽에는 아무 장식 없이 간략화 된 음통(音筒)이 붙어있다. 천판(天板)에는 두 군데에 주조공(鑄造孔)이 남아있으며 가장자리에 죽 돌아가며 입상화문대(立狀花紋帶)가…","a":"청동 종","c":"시도유형문화유산","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636406.jpg"},{"q":"○○○는 대문채, 재실, 사당, 비각, 장판각, 관리사, 화장실 각 1동씩과 협문 2동으로 구성되어 있다. 전체 배치는 북향하고 있는 언덕 기슭에 전면에 좁은 집입로를 두고 방형의 담장으로 둘러쳐진 영역을 이루었다. ○○○의 공간구성은 전면 5칸, 측면 2칸의 팔작집 구성이다. 서쪽에 2칸 폭에 1.5칸의 깊이를 가진 큰 방을 두었는데, 전면은 퇴를 두었고 두 방은 미서기문으로 구획하였다. 동쪽 끝 한 칸의 전면은 누마루를, 후면에는 온돌방을 두었다. 중앙의 대청마루는 4칸의 넓은 공간으로 구성하였고, 후면에 바라지문을 두고 퇴를 달았다. 방의 후면은 모두 벽장을 두…","a":"합천 저존재","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666640.jpg"},{"q":"예천 양씨의 건의로 지은 건물이다. 순조 10년(1810)에 금수서당으로 세웠다가 ‘금수서숙’으로 이름이 바뀐 후 1928년에 이 마을의 임씨 시조인 임억숙(1546∼1605)의 묘소를 수호하고 제사를 지내는 곳으로 기능을 바꾸었다. 이 건물은 대들보에 적힌 기록으로 보아 헌종 15년(1849)에 새롭게 고친 것으로 19세기 서당 건물의 특징을 잘 간직하고 있다. 관리자가 거주하던 왼쪽 건물은 안동지역에서는 보기드문 ㄷ자형 평면구성을 하고 있다. 이곳에서는 해마다 음력 10월 3일에 제사를 지낸다.","a":"금곡재","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663014.jpg"},{"q":"조선 전기의 문신으로 사육신의 한 사람인 매죽헌(梅竹軒) 성삼문(1418∼1456) 선생의 묘소이다. 아기를 낳으려 할 때 하늘에서 ‘낳았느냐?’하고 3번 묻는 소리가 들려 이름을 ‘삼문(三問)’으로 지었다고 한다. 세종 20년(1438) 식년문과에 급제하고, 1447년에는 문과 중시에 장원으로 급제하였다. 집현전 학사로 뽑혀 세종의 지극한 총애를 받았으며『예기대문언독』을 펴내기도 했다. 세종이 훈민정음을 만들 때 정인지·최항·박팽년·신숙주 등과 함께 이를 도왔으며, 요동에 유배되어 있던 중국 명나라의 음운학자 황찬에게 13번이나 다녀오기도 해 한글 반포에 공로가 많…","a":"성삼문의묘","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661019.jpg"},{"q":"이 목판은 이의조 선생이 관혼상제의 예법을 전국적으로 통일시키기 위해 영조 34년(1758)에 『주자가례』에 우리나라의 여러 설을 열거, 증보, 해석하고, 자기의 설을 첨가하여 영조 47년(1771) 완성한 『○○○○초본』이다. 이 판목은 정조 16년(1792) 직지사에서 느티나무를 이용하여 김풍해 등이 3년의 작업에 걸쳐 정조 18년(1794)에 완성하였다. 이것은 총 475매의 목판으로 새긴 기술이 우수하고 보존이 잘 되어 가례연구의 귀중한 자료로 평가된다.","a":"가례증해판목","c":"시도유형문화유산","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640361.jpg"},{"q":"조선시대의 대학자인 한훤당(寒喧堂) 김굉필(金宏弼, 1454~1504)과 일두(一蠹) 정여창(鄭汝昌, 1450~1504)이 서로 교류하며 시를 읊고 풍류를 즐기며 후학에게 학문을 가르쳤던 곳이다. 건물 이름인 ‘이노’(二老)는 한훤당과 일두를 가리켜 부르는 것이다. ○○○을 ‘제일강정’(第一江亭) 또는 ‘제일강산’(第一江山)이라고도 하는데, 이름에 걸맞게 풍광이 아름다운 곳에 자리하고 있다. 건물이 처음 지어진 시기는 일두가 함양의 안음현감으로 부임한 1495년부터 무오사화 때 화를 입어 두 사람이 유배된 1498년 사이일 것으로 짐작된다. 그 후 1885년에 영남…","a":"이노정","c":"문화유산자료","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659491.jpg"},{"q":"○○면 진입로의 금호강변에 우뚝 서있는 2층 누각이다. 조선 태종 12년(1412)에 처음 짓고 선화루라 이름 지었던 것을 세종 7년(1425)에 지금의 자리에 옮겨지었다. 그 후 성종 25년(1494)에 정여창이 다시 짓고 ○○○라고 이름을 바꾸었다. 정유재란(1597)으로 불탄 것을 선조 34년(1601)에 복원하였고, 숙종 9년(1683)에 다시 지었다. 오랜 세월동안 많이 퇴락한 것을 1980년에 정비하였다. 앞면 5칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. ○○○는 조선시대의 대표적인 양식을 간직하고 있는 우람한 건물이다.","a":"함양 안의 광풍루","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641556.jpg"},{"q":"○○○○이 채색하여 그린 8폭의 병풍그림으로, 각 폭마다 각기 다른 풀과 벌레를 그려 놓아 ‘○○○’라고 부르고 있다. 병풍은 율곡 이이 선생을 모시는 송담서원에 있었는데, 순조 4년(1804) 강릉에 산불이 나면서 이 서원까지 불이 번지게 되어 분실되었다. 후에 강릉의 민가에 보관되어 오던 것을 후손인 이장희가 입수하여 율곡 기념관이 건립되자 1965년 기념관에 기증한 것이다. 그림은 자연의 풀과 벌레를 소재로 하여 각 폭마다 꽃과 관련된 풀벌레를 중점으로 그렸으며, 그 종류가 20여 가지나 된다. 오이나 가지는 풍요한 느낌을 갖게 하고, 벌레나 잠자리 등은 사실적…","a":"신사임당초충도병","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637868.jpg"},{"q":"○○○는『삼국유사, 三國遺事』 등의 기록에 나오는 자추사(刺楸寺)일 것이라 한다. 자추사가 맞다면 신라 법흥왕(法興王) 14년(527)에 불교를 나라의 종교로 삼도록 순교(殉敎)한 이차돈(異次頓)을 기리기 위한 절이다. 이 건물은 임진왜란 때 불타고 그 후 다시 지었다. 단층의 목조 기와집으로 옆에서 보면 ‘사람 인(人)’자 모양을 한 맞배지붕이다. 정면 3칸, 측면 3칸의 다포(多包)집으로 좌우 협칸에 쌍여닫이문을 두었다. 기단부는 일부 신라시대 양식을 지니고 있다. ○○○에 모셨던 금동약사여래입상(金銅藥師如來立像)은 불국사(佛國寺) 금동아미타여래좌상(金銅阿彌陀如來…","a":"백률사대웅전","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662351.jpg"},{"q":"이 비는 ○○○○를 지낸 적이 있는 ○○○의 공적을 기리기 위하여 세운 것이다. 이 비석은 조선 명종 14년(1559)에 세워진 것으로, 비문을 지은 이는 남명 조식(1501∼1572)이고, 글씨는 고산 황기로(1521∼1567)가 썼다. 가로 87cm, 세로 202cm, 폭 17cm 의 형식을 지녔으며 비문은 전체 13행, 각 행 평균 25자로 새겨져 있다. 비문에는 1554년에서 1558년까지 ○○○○를 지냈던 ○○○이 1554년의 극심한 흉년에 백성을 자식처럼 사랑하여 구휼하고, 청렴하게 관직생활을 했던 내용이 기록되어 있다. 이 비석의 주인공 ○○○은 황기로와…","a":"합천군수 이증영 유애비","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642341.jpg"},{"q":"무계정사지는 조선 세종(재위 1418∼1450)의 셋째 아들인 ○○○○이 사용하던 정자인 ‘무계정사’가 있던 터이다. ○○○○은 무계정사에 1만 권의 책을 갖추고 용산 강가에는 담담정(淡淡亭)을 지어 선비들과 함께 시를 즐겼다고 한다. 그러나 대군이 역모로 몰려서 사약을 받고 죽은 단종 1년(1453) 이후에는 이곳도 폐허가 되어 지금은 터만 남아 있다. 한편 이곳에는 커다란 바위면에 ○○○○이 쓴 것으로 전해지고 있는 ‘무계동(武溪洞)’이란 글씨가 큰 현판 모양으로 새겨져 있어 이곳이 ‘무계정사’가 있던 곳임을 알려주고 있다. ※ 2003년 12월 5일 서울시유형문…","a":"안평대군 이용 집터","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636099.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 세워진 시기는 정확히 알 수 없으나 조선 영조12년(1736)에 부사 민진기가 횡천으로부터 옮겨지었다. 그 뒤 헌종13년(1847)과 1920년에 고쳐지었고, 근래에도 보수하였다. 출입문이자 휴식공간이었던 풍화루를 들어가면 유생들이 공부하는 명륜당이 있고 그 앞쪽에는 유생들의 거처인 동·서재가 비대칭으로 위치하고 있다. 명륜당 뒤로는 내삼문이 있고, 그 안에 사당인 대성전과 동·서무가 있어서 공자를 비롯한 여러 성현들을 모시고 있다. 전체적으로 공부하는 곳이 앞쪽에, 제사지내…","a":"하동향교","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641946.jpg"},{"q":"사당과 안사당, 그리고 가옥 한채와 2층 건물로 구분된 구조이다. 사당은 조선 고종 2년(1865)에 세워 허씨 4대 선조의 위패를 모신 곳이다. 가옥은 1912년에 지은 집으로 손님 접대나 서재로 사용하고 있다. 2층 건물은 1912년에 지어 현재 집무실로 사용 중인데 가옥과 구름다리로 연결되어 있다. 안사당은 고종 22년(1885)에 지은 것으로 솟을대문 형식이며 대문 양쪽에 방이 있다. 예전에는 손님을 접대하였으나 지금은 사용하지 않는다.","a":"고성장산리허씨고가","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664078.jpg"},{"q":"본 작품은 약사전 후불탱으로 1775년 ○○○ 불화제작의 주요인물인 화사 포관(抱冠) 등이 제작한 작품이다. 본존의 신광을 중심으로 보살과 신중들이 지니고 있는 지물과 의문에 금분을 적절하게 사용하여 화면에 생기를 더하고 있으며, 신장상의 다양한 복식 또한 귀중한 자료적 가치가 있다.","a":"양산 통도사 건륭40년명 약사여래후불탱","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642471.jpg"},{"q":"이 가옥은 선무원종공신 3등으로 책록된 문월당問月堂 오극성吳克成이 낙향하여 건립한 가옥이다. 오극성은 함양인으로 자는 성보誠甫이고 호는 문월당問月堂인데, 34세가 되던 1592년에 임진왜란이 발발하자 왜적을 섬멸하기 위해 벽에 보왜구報倭寇라 써 두고 본격적으로 병법과 무예를 익힌 후 1594년에 병과에 급제하였다. 그 후 임진왜란과 병자호란을 거치면서 많은 전공을 세워 국란 극복에 기여하였고 전쟁이 끝난 뒤에는 선무원종공신 3등에 책록되었다. 고택은 정면 7칸, 측면 4칸 규모의 口자형 건물이다. 평면은 중문칸을 중심으로 좌측에는 사랑방 2칸과 사랑마루로 이루어진 사…","a":"오극성고택","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663561.jpg"},{"q":"단성 ○○○은 제단의 위치, 제단의 축조 방식이나 제도적 규식 등을 보아 조선왕조 초기에 건립된 지방 ○○○의 형태를 나타내고 있다. 동, 서, 남 세방향은 제단의 형태가 완연히 남아있고 각각의 방향으로는 중간에 3층으로 이루어진 섬돌의 모습이 남아 있다. 조선왕조 초기에 조성될 당시의 원형을 잘 유지하고 있을 뿐만 아니라, 도내에서 거의 유일하게 남아있는 ○○○이며 봉안하고 있는 사직 신위패 2점 또한 그 유래가 오래되었다.","a":"산청단성사직단","c":"시도기념물","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657277.jpg"},{"q":"지리산 남쪽 기슭에 위치한 ○○○는 통일신라 경덕왕(재위 742∼765) 때 승려 연기가 처음 지은 절이다. 그 후 신라말 도선에 의해 크게 확장되었으나, 임진왜란(1592) 때 불타 없어졌다. 조선 인조 8년(1630)에 승려 각성이 다시 짓기 시작하여 7년 만인 인조 14년(1636)에 대웅전을 비롯한 약간의 건물을 완성하였고, 그 다음해 선종대가람으로 승격되었다. 현재의 건물들은 각성이 다시 지은 17세기 이후의 것이다. ○○○○○는 법요식 때 승려나 불교신도들의 집회를 목적으로 지어진 강당건물이다. 앞면 7칸·옆면 4칸 규모로, 지붕 옆면이 사람 인(人)자 모…","a":"화엄사보제루","c":"시도유형문화유산","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639884.jpg"},{"q":"관음보살상을 그린 그림으로, 가로 4㎝, 세로 75㎝ 의 작은 규모이다. 관음보살이란 여러 가지 모습으로 나타나 중생들을 제도하고 고난에서 구제하여 주며 안락의 세계로 이끌어 주는 보살을 이른다. 이 그림은 현세의 이익을 추구하는 성격을 지닌 보살상을 그린 것인데 확실한 제작연대는 알 수 없다.","a":"봉곡사불화","c":"문화유산자료","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661300.jpg"},{"q":"암행어사 ○○○의 공적을 기리고 있는 비와 이를 보호하고 있는 비각이다. ○○○는 조선시대의 문신으로, 순조 29년(1829) 통정대부 승지로서 암행어사가 되었다. 그해 10월 회덕지방의 가난과 질병에 허덕이던 서민들을 구제하고 민정을 살폈는데, 그의 어진 다스림을 잊지 못한 이 지역 사람들이 이 비와 비각을 세웠다. 비각은 네 기둥 위로 웅장한 모습의 지붕을 얹었다. 기둥은 굵은 팔각기둥 모양의 주춧돌 위에 서 있으며, 그 위로 처마의 무게를 받기 위한 공포가 설치되어 있다. 기둥머리에 짜맞춰진 공포는 연꽃과 연꽃봉오리들로 장식하여 매우 화려하다. 순조 31년(18…","a":"어사홍원모영세불망비","c":"문화유산자료","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659731.jpg"},{"q":"송도(宋滔)는 연안 송씨로, 조선 초기 울산에 살았던 효자였다. 선생은 울산지역 최초의 생원(生員)으로 병든 부모를 10여 년 동안이나 정성껏 간호하였다. 모친이 병이 깊어 물고기회를 구하고자 하였으나, 가난하여 마련할 수가 없어 얼음판을 두드리며 울었다. 그러자 붕어가 뛰어나왔다고 한다. 또한 제사를 지내려고 제수를 구하니 산의 꿩이 날아들어 왔다고 한다. 1년 사이에 부모가 잇달아 돌아가시자 몸소 흙과 돌을 져다 무덤을 만들고, 유교식 예법에 따라 사당을 세워 신주를 모시고 새벽마다 배알하고, 때에 맞추어 제사지냈다. 당시까지 불교식 장례가 일반화된 상황에서 송도…","a":"효자송도선생정려비","c":"시도유형문화유산","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637269.jpg"},{"q":"정문은 국가에서 풍속을 권장하기 위해 충신·효자·열녀가 사는 마을 입구나 집 문 앞에 세우는 붉은 문을 일컫는다. ○○○○○은 임진왜란 당시 순국한 김여물(1548∼1592)과, 병자호란 때 청군에게 패하고 죽음으로써 열녀정신을 지킨 이 집안 여인들을 기리기 위해 나라에서 지은 정문이다. 지금 있는 건물은 1971년 고쳐 지은 것이고 그 후 1983년 보수공사를 했다. 김여물은 임진왜란이 일어나자 신립과 함께 충주에서 배수진을 치고 왜군과 싸웠으나 당하지 못하여 강에 투신·순국한 인물이다. 열녀는 김여물의 후실인 평산 신씨, 아들 김류의 처인 진주 유씨, 손자 김경징…","a":"사세충렬문","c":"문화유산자료","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659845.jpg"},{"q":"담양 전씨 문원공 전조생과 그의 후손 전자수를 추모하기 위해 유림과 후손들이 세운 서원이다. 전조생은 고려시대의 문신이자 학자로 학문과 문장에 뛰어났던 분이다. 고려가 망하고 이성계가 조선을 개국하였을 때 두 임금을 섬기지 않는다는 신하의 도리를 지키고자 산 속에서 은거하였다. 정조 13년(1789)에 세운 이 서원은 고종 5년(1868) 흥선대원군의 서원철폐령으로 해체되었다가 다시 세운 것이다. 경내의 건물로는 별묘와 강당 등이 있다. 별묘는 영정을 모신 곳으로 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 강당…","a":"의령 태암서원","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664488.jpg"},{"q":"1910년대에 형성된 순천 선교촌에 남아 있는 2층 석조건물로, 1913년 건립되었고 코잇(Coit, Robert Thronwell, 한국명 고라복, ?-1932) ○○○와 관련이 있음. 이 가옥은 한국근대사회에서 전개된 기독교 선교활동의 한 모습을 보여주는 유구임. 특히 목포와 광주에 이어 순천에서 이루어진 선교활동을 위한 ○○○ 가옥으로서 그 형태와 내용면에서 의미가 크다. 코잇 ○○○○○은 옛 순천 선교촌내 건물로 원상에서 다소의 변화가 있으나 가장 보존이 잘 된 것으로 기독교 전래사, 한국근대 초기역사에 있어서 중요한 건물 중 하나이며 건축학적인 측면에서도 가…","a":"순천코잇선교사가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025103117011690.jpg"},{"q":"조선 영조(재위 1724∼1776)의 후궁이자 사도세자의 어머니인 영빈 이씨의 신주를 모시고 제사지내던 왕실의 사묘인 ○○○이 있던 자리이다. 후궁에게서 태어난 임금이 모친의 신위를 모신 사당을 사묘라고 한다. 처음에는 의열묘라 불렀으나 영빈의 손자인 정조가 왕위에 오른 뒤 대우를 높여서 ○○○이라 이름을 고쳤다. 현재 영빈의 신주는 육상궁에 모시고 있는데, 융희 2년(1908)에 옮긴 것이다. 앞면 3칸·옆면 2칸 규모의 1층 건물로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이고 벽은 벽돌로 쌓았다. 제사를 지내는 공간으로 엄숙한 인상을 풍기고 있으나 많이 훼…","a":"선희궁 터","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636114.jpg"},{"q":"○○○○○은 북송(北宋)시대 소주(蘇州)의 경덕사(景德寺)에서 승려로 있던 법운(法雲,1188-1158)이 한역(漢譯)된 불경의 용어를 범어(梵語)로 정리․해설한 일종의 사전이다. 처음 7권이었으나 뒤에 14권으로 편찬되었다. ‘십종통호(十種通號)’로부터 ‘사탑단당(寺塔壇幢)’까지 64편으로 나누어 약 2천여 단어를 수록했다. ○○○○○ 은 현재 14권(卷) 8책(冊)이 보물 제 1369호로 지정되어 있는데 이는 조선 초기에 원(元)의 대장경(大藏經)을 저본(底本)으로 삼은 판본이다. 본(本) 서울역사박물관 소장 활자본 ○○○○○ 권1～3(飜譯名義集 卷一~三)은 전(…","a":"번역명의집 권1~3","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590478.png"},{"q":"○○○에 보존되어 있는 그림으로, ○○○은 원래 인도의 방위신(方位神)이었으나, 불교에 흡수되면서 천부세계의 도상으로 수미산에 거주하면서 사방을 수호하는 호법신의 이미지가 강화된 것으로 전한다. ○○○은 동방은 지국천왕, 남방은 증장천왕, 서방은 광목천왕, 북방은 다문천왕이라 일컬으며, 이들은 수미산의 동서남북에 각각 거주하면서 사방을 지킨다. ○○○○○는 세로 350㎝가 넘는 두루마리형의 비단 4폭에 천왕상 1구씩을 그렸다. 동방 지국천왕은 칼을 쥐고 있고, 남방 증장천왕은 용·보주를 쥐고 있고, 서방 광목천왕은 탑과 당(幢)을 들고 있으며, 북방 다문천왕은 비파를…","a":"범어사 사천왕도","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636691.jpg"},{"q":"제주시 애월읍 애월리에서 태어난 ○○○은 1770년 12월 25일 과거 시험을 보기 위해 서울로 가다가 풍랑을 만나 류쿠제도(琉球諸島, 오키나와)에 표착을 한다. 『○○○』은 ○○○이 류큐제도에 표착한 뒤 일본으로 가는 상선을 만나 구조된 뒤, 우여곡절 끝에 한양에 가서 과거에 응시하고 낙방한 뒤 귀향하여 쓴 책이다. 당시의 해로와 해류(海流), 계절풍 등에 관한 해양 지리서로서 문헌적 가치가 높고, 제주도의 삼성(三姓) 신화와 관련한 이야기, 백록담과 설문대 할망의 전설, 유구 태자에 관한 전설 등 당시 제주도의 전설이 풍부하게 기록되어 있어 설화집으로서의 가치도…","a":"장한철의 표해록","c":"시도유형문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643345.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배계층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 인천시 서구 ○○○ 가현산에서 동서방향으로 뻗어 있는 야트막한 구릉지에 분포되어 있는 이 ○○○○은 모두 10기로, 탁자식과 바둑판식이 섞여 있다. 10기 중 탁자식 ○○○ 2기를 제외하고는 대부분의 ○○○이 매몰되거나 주위에 흩어져 파…","a":"대곡동 고인돌군","c":"시도기념물","r":"인천광역시","s":"검단구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645618.jpg"},{"q":"○○○○○은 본관이 청주(淸州)다. 남이(南怡)의 역모를 잘 다스린 공으로 수충보사병기 정난익대공신(輸忠保社炳幾定難翊戴功臣)에 책훈(策勳)되고, 청평군(淸平君)에 봉해졌다. 이 ‘○○○ 묘역’은 조부 한상경, 부친 한혜 등 청주한씨 묘산(墓山)이다. ○○○은 초취(初娶) 성산이씨(星山李氏), 재취(再娶) 안동권씨(安東權氏), 삼취(三娶) 남원황씨(南原黃氏) 세 부인을 두었으며, 권씨 부인과 상하분(上下墳)으로 안장되어 있다. 각 봉분 앞에는 하엽수(荷葉首; 연잎 형태의 비석 머리) 형태의 묘표(墓表)와 문인석 한 쌍이 건립되어 있다. ○○○ 묘 앞에는 장명등이 건립되…","a":"양평공한계순묘역","c":"문화유산자료","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660173.jpg"},{"q":"○○는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 처음 세워진 시기는 알 수 없으나 중종(재위 1506∼1544) 때 다시 지은 것이 현재에 이르고 있다. 건물은 출입문인 풍화문, 공부하는 곳인 명륜당과 동·서재, 사당인 대성전 등이 있는데, 명륜당이 앞에 있고 대성전이 뒤에 있는 전형적인 전학후묘의 형태를 하고 있다. 그러나 특이하게 명륜당과 대성전이 얼마간의 사이를 두고 위치하고 있으며, 대성전에는 동·서무가 없다. 조선시대에는 국가로부터 토지와 전적·노비 등을 받아 학생들을 가르쳤으나 갑오개혁(1894) 이후 제사만 지…","a":"영산 향교","c":"시도유형문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641866.jpg"},{"q":"경상남도 ○○군 하북면에서 출토된 청동으로 된 불상과 사리탑이다. 불상은 불꽃무늬가 새겨진 광배(光背)를 배경으로 앉아 있는데, 투박하게 만들어진 데다가 표면의 부식이 심해서 확실한 특징을 살피기 어렵다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 머리묶음이 솟아 있다. 얼굴은 코와 입이 작게 표현되어 균형미를 잃고 있다. 옷은 양 어깨에 걸치고 있으며 왼쪽 어깨와 허리 아래 부분에 옷주름이 새겨져 있다. 오른손은 어깨 높이에서 손끝을 위로 향하여 손바닥을 보이고 있으며, 왼손은 배꼽 부위에서 들고 있다. 다리 부분은 상체에 비해 너무…","a":"양산 통도사 청동여래좌상 및 청동사리탑","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641578.jpg"},{"q":"○○○에 자리하고 있는 비로, 이 절의 중창(重創:원래의 절을 고쳐 새롭게 함)에 관한 내용을 담고 있다. ○○○는 비문의 내용을 미루어 신라 문무왕 이전에 창건되었고, 이후 여러 번의 보수를 거쳤다 한다. 비는 넓다란 사각받침 위로 비몸을 세운 모습으로, 비문이 많이 닳아 있어 읽기가 힘들다. 비문의 내용을 보면, 조선 태종 17년(1417) 평안도 관찰사로 부임했던 성달생이 절을 하나 짓고자 터를 찾아다니던 중, ○○○의 자리가 좋다는 이야기를 들었다. 결국 그의 뜻에 따라 세종 7년(1425)에 주지 해총이 절을 중창하였다. 이외에 원효대사와 의상대사가 이곳에…","a":"화암사중창비","c":"시도유형문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639507.jpg"},{"q":"○○○○○은 충청북도 ○○시 상당구 ○○에 위치한 근대건축물로 ○○ 최초의 서양식건물이다. 구한말 개화기에 충청북도 기독교 문화의 요람이었던 ○○○○○은 1906년부터 1932년 사이에 건립된 여섯 동의 서구식 건물로서, 미국 북장로교회 소속 선교사들에 의해 ○○지방에서는 맨 처음으로 건립된 양옥 건물이다. 미국 북장로교회 소속 선교사였던 민노아(閔老雅, F.S. Miller) 목사가 1900년경 ○○시 ○○ 일대에 선교부지를 마련하여 부인과 함께 정착함으로써 건립의 기틀이 마련되었고 1906년 ○○○○○ 4호관을 건립하게 되었다. 그 뒤에 계균(Edwin-Kagin…","a":"청주 탑동 양관","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638599.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659184.jpg"},{"q":"‘○○○○○’은 이 서첩의 표지에 기록된 제목이며, ‘계해년에 궤장을 하사받은 후에 열린 잔치의 시첩’으로 풀이된다. 1623년(인조 1년) 9월 6일에 영의정 이원익(李元翼, 1547∼1634)이 국왕으로부터 궤장(几杖; 안석과 지팡이)을 하사 받은 후에 열린 연회에서 참석한 빈객들이 축시를 모아 시첩으로 만든 것을 바탕으로 다시 옮겨 쓴 시첩이다. 표지를 넘기면 본문 첫 장에 진원부원군 유근(晉原府院君 柳根, 1549~1627)의 시 서문, 이어서 오언배율(五言排律) 십운시(十韻詩)가 있고, 여기에 차운(次韻)한 참석자들의 시 21편과 연회 후에 보내온 시 11편…","a":"계해사궤장연첩","c":"시도유형문화유산","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637799.jpg"},{"q":"임진왜란 때 공이 컸던 충무공 이순신과 정운, 송희립을 모시기 위해 세운 사당이다. 충무공 이순신(1545∼1598)은 조선 선조 12년(1579) 무과에 급제하였다. 임진왜란이 일어나자 옥포·강포·한산도 등지에서 승리를 거두었다. 정유재란 때 명량에서 대승을 거두었으며 노량진에서 순절하였다. 충장 정운(1543∼1592)은 조선 중기의 무신으로 선조 3년(1570)에 과거에 급제하였다. 임진왜란이 일어나자 이순신 장군의 휘하에서 옥포·당포·한산도 등 여러 해전에서 큰 공을 세웠다. 9월 부산포 해전에서 우부장으로 선봉에서 싸우다가 전사하였다. 송희립 장군은 조선 중…","a":"충무사","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661979.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○시 ○○○의 마을 안과 주변 논밭에 모두 15기의 고인돌이 있다. 형태상 모두 바둑판식으로 덮개돌의 크기는 길이 2.2m, 너비 1.4m이며, 받침돌의 크기는 너비 40㎝, 높이 20㎝이다. 땅 속에 마련된 하부구조는 정확히 알 수 없…","a":"사천 덕곡리 지석묘군","c":"시도기념물","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654976.jpg"},{"q":"춘천 ○○○가옥은 나지막한 산 아래에 세운 집으로 ㄱ자형 안채에 사랑채가 딸려 있어 전체적으로 ㄷ자형 평면을 이루고 있다. 안채는 대청마루를 중심으로 왼쪽에는 건넌방을 두고 오른쪽으로는 웃방·안방·부엌을 배치하였는데 부엌 천장에는 다락을 만들었다. 대청 뒤쪽 벽에는 2짝 문을 달고, 웃방과 안방 사이에도 문을 달아 공간을 구분하였다. 안채 대청 앞쪽으로는 햇빛을 막고 비가 들지 않게 높은 기둥을 세워 지붕을 덧댄 차양시설을 두었다. 사랑채는 대문을 중심으로 왼쪽에는 부엌과 사랑방을 두었고 오른쪽에는 광과 그 뒤편으로 방을 놓았다.","a":"춘천김정은가옥","c":"문화유산자료","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660458.jpg"},{"q":"○○○는 산왕(山王)으로 신앙되던 호랑이가 의인화(擬人化)된 산신(山神)을 표현한 불화이다. 호랑이는 예로부터 산의 신령으로 믿어져 왔는데 차츰 신앙의 대상으로까지 신격화되었으며, 이를 불교에서도 받아들여 신앙의 대상으로 삼았다. 우리나라에서는 고려시대까지는 산신에 대한 신앙이 없었던 것으로 보인다. 조선시대에 들어와 불교가 민간신앙과 결합하면서 토착화하는 과정에서 산신에 대한 신앙이 유행하게 되었고, 조선시대의 사찰에는 대개 산신각(山神閣)을 세워 상과 불화를 봉안하고 있다. 대개 ○○○는 깊은 산과 골짜기를 배경으로 기암괴석 위에 백발이 성성한 노인 모습의 산신이…","a":"수원 청련암 산신도","c":"문화유산자료","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660287.jpg"},{"q":"○○○○은 선조 30년(1597) 정유재란 때 선진리성에 주둔하고 있던 왜적을 몰아내기 위해 결전을 벌이다 희생된 조선과 명나라 연합군의 무덤이다. 정유재란을 일으켜 북진하려던 왜군은 조선과 명나라 연합군의 저항을 받자 경상도 남해안지방으로 퇴각하여 남해안 곳곳에 성을 쌓고 머물고 있었다. 사천지방에는 왜장 시마즈의 군사가 주둔하고 있었는데, 명나라 장군 동일원과 경상도 우병마사 정기룡이 진주를 거쳐 이곳의 적을 몰아내고자 하였다. 그러나 아군진영에서 발생한 불의의 화재로 인해 적의 역습을 받게되어 수천 명의 희생자를 내었다. 왜군은 그들의 승리를 본국에 알리기 위해…","a":"사천조명군총","c":"시도기념물","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655219.jpg"},{"q":"○○○는 계룡산 기슭에 있는 절로 백제 의자왕 11년(651)에 보덕이 처음 지었다고 전한다. 고려와 조선을 거치면서 여러 번 다시 지어졌고, 지금의 ○○○ 건물은 조선 고종 13년(1876)에 보연이 지은 것이라고 한다. 앞면 3칸·옆면 3칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 처마의 끝을 살짝 올려 우아한 멋을 나타내었다. 지붕을 받치면서 장식을 겸하는 공포가 기둥 위와 기둥 사이에도 있는 다포양식 건물이며, 연꽃을 조각하여 장식하였고 매우 간략한 양식으로 되어있다. 내부에는 아미타여래를 주존으로 하여 관음보살과 대세지보살을 모…","a":"신원사대웅전","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639127.jpg"},{"q":"옛날 고을 수령들의 연회장으로 쓰였던 건물이라고 하며, 언제 지어졌는지는 알지 못한다. ‘도계문루’라고도 불렸다고 하며 동쪽에 동헌터가 남아있는 점으로 보아, ○○현 관아의 문루였던 것으로 보인다. 앞면 3칸·옆면 2칸의 2층 누각으로, 여덟 팔(八)자 모양의 화려한 팔작지붕집이다. 2층 툇마루 밖으로 난간을 둘렀다. ○○○○○는 ○○군에서는 가장 오래된 누각 건물이다.","a":"합천 삼가 기양루","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641559.jpg"},{"q":"조선 중기의 문신인 ○○○ 선생의 비이다. ○○○은 광해군 5년(1613) 생원이 되었으며, 이이첨의 사주를 받은 정조, 윤인, 이위경 등이 인목대비를 해치려고 할 때 이들의 목을 벨 것을 상소하다 길주에 유배당하고 뒤에 진도로 옮겨 유배생활을 하였다. 인조반정으로 관직을 되찾아 의금부도사를 지냈으며 청안현감이 되었고, 이후 남원, 죽산의 부사와 공주, 청주의 목사 등을 두루 지냈다. 오랜 외직생활동안 백성들에게 선정을 베풀었으며, 청렴하고 강직한 목민관으로 이름을 떨쳤다.","a":"목사김효성의비","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660999.jpg"},{"q":"일명 ‘부처골’이라 불리는 경상남도 삼양군 함양읍 ○○○ 메아리골 바위면에 조각된 불상이다. 주변 환경으로 미루어 보아 옛 절터로 추정되나 기록은 남아 있지 않다. 전체적인 윤곽을 가는 선으로 표현하였다. 민머리 위에 상투 모양의 머리묶음이 뚜렷하고 둥근 얼굴은 부드러운 인상을 느끼게 한다. 목에는 3줄의 삼도가 새겨져 있고, 양 어깨를 감싼 옷은 가슴 아래로 U자모양의 옷주름을 만들고 있다. 양 손은 엄지와 검지를 맞댄 아미타여래의 손모양을 하고 있으며, 대좌(臺座)에는 소박하면서도 생동감 있는 연꽃잎을 표현해 놓았다.","a":"함양대덕리마애여래입상","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642238.jpg"},{"q":"○○○○○은 ○○○ 나한전 옆에 건립되어 있는 목조와즙 건물로 여러 번 보수가 이루어졌으나 창건 당시의 원형을 비교적 잘 유지하고 있다. 건물은 외벌대 기단을 마련하여 건립한 정면 3칸, 측면 1칸의 소규모 건물이다. 초석 위에 사각형 기둥을 올린 민도리 형식으로 창호 앞에는 디딤돌을 마련하여 문지방을 쉽게 오르내리도록 했다. 지붕은 맞배지붕이며, 정면 처마부는 겹처마이고, 후면 처마부는 홑처마로 구성되었다. 건물 양측면에는 화방벽(火防壁)이 설치되어 있다. 건물 내부는 안쪽 벽에 불단을 마련하여 칠성도와 석불좌상, 명호스님의 영정을 봉안하였다. 천정은 우물천정이고…","a":"진관사 칠성각","c":"문화유산자료","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314434100.jpg"},{"q":"이 삼응○○은 육십갑자 중 십이간지를 네 묶음으로 분류하여, 한 묶음의 띠에 해당하는 나이가 삼재에 해당하는 해가 되면 이 삼재 소멸을 위해 기도하며, 그 비보용으로 이 삼응판을 인출 탁삼재라는 제호를 낙관하여 액자를 만들어 출입문 위에 걸었던 것이다. 흔하지 않은 자료라 보존가치가 높다.","a":"남해 화방사 삼재부 목판","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666695.jpg"},{"q":"○○○○○는 망호리 마을 안쪽에 서향하고 있으며, 나즈막한 마을의 지붕속에 큰 기와집의 형태가 큰 도로에서도 볼 수 있어 마을의 운취를 돋우고 있다. 이 종가는 대산 이상정(李象靖, 1711∼1781) 선생이 이 집 사랑채에서 태어났을 때는 큰 집이 있었으나 일제 때 집을 3년 정도 비워두었기 때문에 너무 퇴락하여 더 이상 유지가 곤란하였다. 그 후 대산의 8대손인 이용원(李龍遠, 1915∼1959)이 17세 때 결혼하고 3∼4년 뒤에 전보다 규모를 조금 줄여 새로 건립하였다고 한다. 이 종가는 넓은 마당을 앞에 두고 뒤쪽에 안채를 배치하였으며, 안채 우측에 방형의…","a":"한산이씨대산종가","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663301.jpg"},{"q":"○○○은 광평대군 이여(李璵 : 세종과 소헌왕후 사이에서 태어난 5번째 아들)의 7대손이다. 인조반정 때 공을 세워 정사공신 3등으로 책록되고, 정묘호란 때는 총융사 종사관으로서 큰 역할을 하였으며, 병자호란 때는 척화파(斥和派)로 청(淸)에 결사 항전할 것을 주장하였다. 효종의 북벌계획이 추진될 때는 전함 200척을 준비하는 등 북벌계획에 주도적으로 참여했다. 스스로도 학문이 높았지만 1657년(효종 8) 우의정이 된 뒤에는 조선 후기 대표적 성리학자로 후에 노론(老論)의 영수(領袖)로 성장한 송시열(宋時烈 : 1607~1689)과 송준길(宋浚吉 : 1606~167…","a":"완남부원군 이후원 묘역","c":"시도기념물","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644887.jpg"},{"q":"조선 중기의 선비인 김선(1568∼1642) 선생의 초상화이다. 김선의 호는 시서거사로, 선조 38년(1605) 사마시에 급제하였으나 광해군의 어지러운 정치를 한탄하며 관료로 진출하지 않고, 초가집을 지어 은거생활을 하였다. 초상화는 오른쪽을 바라보며 의자에 앉아 있는 전신상으로, 원본을 후대에 그대로 옮겨 그린 것으로 추정된다. 오른손은 무릎에 올려놓고 왼손에는 부채를 들고 있으며, 머리에는 대나무로 만든 두건을 쓰고 있다. 얼굴은 마마를 앓은 자국까지 세밀하게 표현하였으며, 옷은 유학자의 기품을 느끼게 하는 학창의를 입고 있다. 얼굴의 모습에서는 시골 선비다운 강…","a":"시서영정","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662107.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 무덤가에 세워두는 것으로, 이 비는 조선 중기의 문신인 정황(1512∼1560)의 공적을 기리고 있다. 정황은 조선 중종 31년(1536) 친시(親試)에 합격하여 문원부정자(文院副正字)라는 관직에 올랐고 사간원정언(司諫院正言), 사헌부지평(司憲府持平), 병조형조정랑(兵曹刑曹正郞), 춘추관기주관(春秋館記注官)이 되었으며, 1560년 타계 후 숙종 34년(1708) 이조판서에 추증되었다. 비의 지대석은 4매를 맞춰 놓았으며, 귀부받침은 1매석인데 전면에는 2칸으로 구획하고, 측면은 3칸으로 구획하여 그 안에 연화 등의 꽃문양을…","a":"정황선생신도비","c":"시도유형문화유산","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639751.jpg"},{"q":"고려 후기에 기와를 굽던 터이다. 조사 결과 3개의 터를 발견했는데 구조는 터널식으로 파서 만든 굴가마로 되어있다. 기와 조각 외에 다른 유물은 발견되지 않았고 조각의 대부분은 빗살무늬와 생선뼈무늬를 띠고 있다. 1호 요지는 전체 길이가 약 9m로 천장부분에 약간 손상이 있을 뿐 그 외는 완전하다. 2호 요지는 가장 먼저 발견된 곳으로 1호 요지 사이에 3호 요지를 두고 남동쪽에 있다. 전체 길이는 5.6m로 천장 일부분에 손상이 있을 뿐 상태가 좋은 편이다. 3호 요지는 1호와 2호 요지 사이에 있다. 기와를 굽던 방의 반 정도와 연소실이 없어져 현재 길이는 3.2…","a":"영주용혈리와요지","c":"시도유형문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640998.jpg"},{"q":"이 책은 박기현(1864∼1913)이 기록한 필사본으로, 1891년부터 1903년까지 강진, 장흥일대에서 향촌사회의 동향과 박기현과 그의 문인과의 교류를 기록한 것이다. 그 중에서도 특히 1895년 동학농민운동이 발발했을 당시의 동학농민군측과 관군측의 동향 및 전투상황 등을 상세히 기록하고 있다. 이 책은 동학농민운동사에 있어서 매우 중요한 자료이며, 특히 전라남도 서해지역에서의 동학농민운동의 일례를 보여주는 것으로 향토사연구에도 매우 귀중한 가치가 있다고 평가된다.","a":"강진강재일사","c":"시도유형문화유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640133.jpg"},{"q":"통일신라시대 학자인 고운 최치원(857∼?) 선생의 초상화이다. 최치원은 통일신라 경문왕 9년(869) 당나라에 유학 가서 그곳에서 과거에 급제하여 활약하였는데, 879년 황소의 난을 진압하고자 쓴『토황소격문』은 특히 유명하다. 초상화는 중국풍의 문인상 형식을 취하고 있으며, 가로 105㎝, 세로 74㎝의 크기이다. 선생의 초상화는 여러 곳에 보존되어 있는데 그 대부분이 승려의 모습인데 반하여, 이 그림은 각이 진 사방모를 쓰고 평상복을 입고서 편안한 자세로 부채를 손에 쥐고 앉아 있는 모습이어서 특별하다. 양 옆에는 석류가 담긴 청자 그릇을 받쳐든 동자와 파초선을…","a":"고운영정","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640609.jpg"},{"q":"○○읍 ○○○ 냇가에 방치된 것을 이곳으로 옮겨 놓았는데, 불상 주위 약 300m 지점에 망가사라는 절이 있었다는 것으로 미루어 보아 이 절의 유물로 추정된다. 광배(光背)와 대좌(臺座)를 모두 갖춘 이 불상은 현재 두 손이 떨어져 나갔고, 가슴 아래는 시멘트로 보수하였다. 민머리 위에는 상투 모양의 머리묶음이 낮게 나타나 있으며, 원만한 얼굴에서는 다소 토속적인 표정이 엿보인다. 두 귀는 길고 굵은 목에는 3개의 주름이 뚜렷하며, 두 어깨는 얼굴에 비하여 빈약한 편이다. 양 어깨를 감싸고 있는 옷에는 U자형의 평행한 옷주름이 두텁게 묘사되었는데, 충청북도 충주지방…","a":"함양 이은리 석불","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641396.jpg"},{"q":"현 소유자의 6대조인 남정기가 세웠다고 전하는 가옥이다. 1800년경 지었으며 안채, 사랑채, 문간채로 구성된다. 대문을 들어서면 넓은 사랑마당에 一자형 사랑채를 남향으로 배치하였고 그 뒤로 ㄷ자형 안채가 있어 전체적으로 트인 ㅁ자형 구조를 보인다.","a":"의성소계당","c":"문화유산자료","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663238.jpg"},{"q":"○○○○○은 대웅전 법당에 봉안되어 있는 ○○○○상으로 높이 35cm, 어깨너비 16cm, 머리높이 17cm(보관 포함), 무릎너비 23cm이며, 표면에 개금이 되어 있는 상태로 전체적으로 보존 상태가 양호하며 눈썹, 눈의 표현, 콧수염, 턱수염과 입술에 채색하여 세부표현을 하였다. ○○○○은 고개를 약간 숙이고 등을 곧게 편 상태로 양손을 무릎 위에 얹고 결가부좌하고 있으며, 옷은 편삼위에 대의를 살짝 걸친 형식이다. ○○○○은 방형의 얼굴에 눈을 가늘게 뜨고 아래로 내려다 보고 있다. 코는 오똑한 편이며, 인중과 윗입술을 도드라지게 표현한 것이 주목할 만하다. 삼…","a":"울산인성암석조보살좌상","c":"문화유산자료","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659807.jpg"},{"q":"크기는 가로 212.5㎝, 세로 151㎝로, 지장보살이 중앙의 높은 대좌 위에 반가좌로 있으며, 발은 분홍색의 연화 봉오리가 받쳐 들고 있다. 이중원형광배를 두르고 오른손을 어깨 높이만큼 들었으며, 왼손은 무릎까지 내려 옷자락을 잡고 있다. 지장보살 무릎아래 좌우에 도명존자, 무독귀왕을 중심으로 각각 오존씩 시왕을 배치하고 시왕의 우측에는 판관, 우두, 마두, 선악동자 등의 권속들이 배치되었다. 무독귀왕은 합장을, 도명존자는 석장을 잡고 있다. 원래 극락전의 아미타회상도 좌우에 신중도와 함께 걸렸던 것으로 현재 지장전 청동지장보살좌상 뒤에 봉안되어 있다. 화기(畵記)…","a":"가평현등사지장십왕도","c":"문화유산자료","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660247.jpg"},{"q":"○○○ 상촌 마을의 북쪽에 동서로 뻗어 마을을 감싸고 있는 구릉에 있는 무덤들로, 남해포로 가는 옛도로 양쪽에 분포한다. 모두 28기인데 4기의 독무덤(옹관묘)과 후대의 무덤 2기, 그리고 1개의 구덩이가 발견되었다. 봉분의 형태는 긴 타원형이고, 영산강 유역 독무덤의 일반적인 양식으로, 봉분 자락에 도랑이 둘러져 있다. 14호 무덤은 흙을 파고 하나의 독무덤을 안치한 후, 봉토를 쌓은 단독장으로 소형 무덤의 특징을 잘 보여주고 있다. 영암 ○○○ 무덤들은 3세기 후반에서 4세기 후반에 걸쳐 형성된 것으로 추정된다.","a":"영암옥야리고분군","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662095.jpg"},{"q":"불암산(해발 509m) 남쪽 능선의 해발 420m 봉우리에 있다. ○○○○ 서쪽으로 3번 국도와 중랑천 수계, 동쪽으로 왕숙천 수계를 통제할 수 있는 군사적 요충지에 있다. ○○○○은 봉우리 주변의 자연지형을 따라 쌓은 석축산성이다. 평면 형태는 장방형에 가까운 다각형이며 둘레는 220m다. 전략적인 요충지에 쌓은 보루성은 요즈음의 초소와 같은 감시기능을 했을 것으로 보인다. ○○○○ 성벽은 화강암을 장방형으로 가공하여 정교하게 쌓았다. 원래 성벽의 높이는 5m 이상이었을 것으로 보인다. 성을 쌓기 전 원지형을 계단식으로 정리하고 내벽과 외벽 속채움을 모두 돌로 쌓은…","a":"불암산성","c":"시도기념물","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052014554400.jpg"},{"q":"조선 중기의 문신인 정탁(1526∼1605)을 기리고 제사지내는 곳이다. 정탁은 명종에서 선조 때까지의 사람으로 임진왜란 때 큰 공을 세웠으며 옥중에 있는 이순신 장군의 목숨을 구한 유명한 일화를 가지고 있다. 죽은 후 예천의 도정서원에 모셔졌다가 후손들이 지은 지금의 건물로 옮겨졌다. 재실과 대문으로 되어있다. 재실은 앞면 5칸·옆면 3칸의 ㄷ자형으로 되어있다. 대문채는 옆면 1칸짜리로 一자형이며, 마구간·고방·방앗간 등이 있다. 재실의 대청 뒷벽에 있는 영쌍창은 이 건물이 17세기에 지어졌다는 것을 보여주고 있다.","a":"예천청주정씨재실","c":"시도유형문화유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641016.jpg"},{"q":"이 그림은 지공·나옹·무학 ○○○의 모습을 한 폭에 그린 ○○○영정이다. 화면중앙에는 지공화상이 좌안7분면으로 결가부좌를 한 채 왼손에 염주를 들고 있으며 나옹화상 역시 좌안7분면에 결가부좌를 하고 있으며 지물은 없다. 반면 무학화상은 우안7분면에 결좌부좌자세로 오른손에 주장자를 잡고 지공방향으로 앉아 있다. 지공은 흰색 깃이 달린 내의 위에 녹색의 옷을 입고 그 위에 원권문이 그려진 붉은 색 대의를 걸쳤다. 나옹과 무학은 옅은 잿빛의 장삼위에 홍가사를 걸쳤는데 나옹은 매듭으로 무학은 금구장식으로 가사를 연결하고 있다. 특히 나옹과 무학의 장삼에는 선염에 의한 음영법…","a":"남해 용문사 삼화상 진영","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001666196.jpg"},{"q":"1603년(선조 36년) 3월에 세워진 이 비의 석질은 자갈이 듬성듬성 박힌 사암이며, 이후 어느 시기에 깨어져 세 부분으로 분리되었다가 접착제를 이용하여 다시 붙였다. 비의 전면에는 평해군 북쪽 10리 월송변에 하나의 사천이 바닷물과 서로 통해 사시로 물이 넘쳐 민들의 일상생활과 상인들의 통행이 어려워 당시 주민들이 생활의 불편함을 없도록 하기 위해 평해군수 조인징의 허락을 얻어 돌다리를 만들고 이를 기념하기 위해 비석을 세웠다.","a":"평해북천교비","c":"시도유형문화유산","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641125.jpg"},{"q":"반남 박씨의 가옥 중에 하나로 증언에 따르면 1923년경 지었다고 한다. 이 집은 원래 기와와 초가가 섞여 있는 ○○○의 주택 구성 중에 초가 까치구멍집이었으나 1975년 지붕개량사업 당시 기와집으로 바꾸었다. 앞면 3칸·옆면 2칸 규모의 까치구멍집으로 비교적 작은 집이다. 집 구성은 앞쪽에 사랑방·봉당·부엌이 있으며, 뒤쪽에는 윗방·마루·안방을 배치하였다. 이 집의 특징은 일반적으로 마구간이 있어야 할 자리에 사랑방이 있고, 사랑방 앞면과 옆면, 상방 옆면에 외부로 통하는 문을 설치하여 개방성을 주고 있다는 점이다.","a":"영주수도리박천립가옥","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663215.jpg"},{"q":"○○○은 조선 중기 문신인 추천 손영제가 지은 정자이다. 손영제는 이황의 제자로 학문과 정치에 대해 가르침을 받았으며, 조선 명종(재위 1545∼1567) 때 정랑을 거쳐 예안, 김재, 울산 군수 등을 지냈다. 지금 있는 건물은 1936년에 후손들이 다시 세운 것이다.","a":"밀양 오연정","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664352.jpg"},{"q":"김포시 대곶면의 해발 147m ○○○에 있다. 이곳은 김포의 서북부지역이며 산 정상부에서는 인천, 강화, 서울지역이 넓게 조망된다. ○○○○의 평면 형태는 남북으로 긴 타원형이다. 현존하는 성벽의 둘레는 685m인데, 군사시설이 설치되면서 훼손이 심한 상태다. 성벽은 석축이며 방형이나 장방형으로 가공된 성돌을 바른층쌓기하여 정교하게 쌓아 올렸다. 도로 개설로 인하여 절단된 구간에서 확인되는 성벽 단면을 보면 내벽과 외벽, 적심부를 모두 돌로 쌓은 편축공법으로 구축되었음이 확인된다. 축성법이나 성내에서 출토된 유물을 고려할 때 ○○○○은 6세기 후반 신라에 의하여 축성…","a":"김포수안산성","c":"시도기념물","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646852.jpg"},{"q":"불규칙한 모양의 자연석을 쌓아 만든 고려시대의 석탑이다. 탑에 대한 기록은 물론 주변에 관한 기록도 전하지 않는다. 탑은 건물터 만큼 넓게 낮은 단을 마련하여 그 위에 계단모양의 층단을 만들었다. 1, 2단에 걸쳐 네 면에 목탑에서처럼 감실(龕室)을 파서 불상을 모셔두었다. 현재 윗부분이 무너져 원래 몇층이었는지 알 수 없고, 기단과 탑신의 구분도 애매한 독특한 형식의 탑이다.","a":"의성석탑리방단형적석탑","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640974.jpg"},{"q":"이 ○○○은 구름무늬를 가득 채운 주황빛의 비단 한 폭을 통째로 사용했다. 비단의 앞쪽 가장자리에는 ‘소주직조신서문(蘇州織造臣舒文)’이라는 그루기가 있어 오늘날의 중국 쑤저우에서 수입한 사실을 알 수 있다. ○○○을 짓고 쓴 이는 정조의 최측근이자 남인의 영수로 이름난 번암(樊巖) 채제공(蔡濟恭, 1720-1799)이다. 당시 채제공의 나이는 70세였는데, 고령에도 불구하고 미끄러운 비단 위에 진한 먹을 능숙히 사용해냈다. 또한, 행서(行書)로 쓴 필치에서는 원숙하면서도 넘치는 기운과 속도감이 느껴진다. ○○○의 사명(寺名) 유래, 현륭원(顯隆園)의 재궁(齋宮)으로서…","a":"용주사상량문","c":"시도유형문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637359.jpg"},{"q":"법화사는 12세기∼15세기에 제주도에서 번창했던 절이다. 18세기 전기에 제주목사 이형상이 제주도의 절 3곳을 불태워 없앨때 완전히 불타버렸으며, 지금의 건물들은 1987년 다시 세운 것이다. 현재의 법당 자리에서 금당지로 보이는 건물터가 발견되었는데, 앞면 5칸·옆면 4칸에 면적이 약 100평인 대규모 건물이었음을 알 수 있다. 법화사는 건물 기단의 바닥돌이 2단으로 되어있고, 면석의 기법이 특이하며, 출토된 도자기와 기와조각 등으로 보아 10세기∼12세기 경 지어진 것으로 추측된다. 당시 규모가 매우 큰 절로 제주도 3대 사찰 중 하나인 중요한 유적이다.","a":"법화사지","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657761.jpg"},{"q":"조선후기 선사 진영을 대표하는 작품으로 상호가 자상하고 사실적이며 전체 색조 또한 안정되어 있다. 보조국사 진영에 비해 격이 떨어지지만 한 시대를 대표할 만한 작품이다. 이 진영은 조선말기의 작품이지만 당시 시대적 특징을 잘 간직한 수작이다.","a":"동화사죽암당대선사선찰진영","c":"문화유산자료","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659500.jpg"},{"q":"이 부도는 1903년 군산에 농장을 개설한 일본인 시마따니 야소야라는 사람이 위치를 알 수 없는 절터에서 가져온 것으로 전하며, 현재 ○○○오층석탑(보물) 및 석등과 함께 자리하고 있다. 육각의 지대석 위에 2단의 하대석이 있는데 하단은 안상이 새겨져 있고 상단은 복련과 함께 중대받침이 높게 각출되어 있다. 육각의 중대석에는 우주를 모각하고 있으며 앙련의 상대석 위에는 낮은 탑신받침이 있다. 육각의 탑신석은 2개소에 문비를 모각하였으며, 4면에는 희미하여 확실하지는 않지만 사천왕상이 각출된 것으로 보이며, 옥개석 아래에는 3단의 옥개받침과 함께 연자와 부연을 모각하였…","a":"발산리육각부도","c":"문화유산자료","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661885.jpg"},{"q":"고려말 두문동 72현 중의 한 분인 농은 민안부 8대손인 이요당 민신국의 서당이다. 이요당은 선조 농은 선생의 ‘재물이 많고 사회적 지위가 높은 것은 뜬구름과 같이 인생의 덧없음으로 경계하라.’는 뜻의 ‘부귀부운계(富貴浮雲戒)’에 따라 노은마을에 은거하면서 조선 고종 11년(1874)에 지은 것이다. 건물은 앞면 5칸·옆면 1칸 반 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면에는 마루를 두었는데 앞면 기둥은 둥근기둥을 사용하였고, 건물 앞면에 ‘○○○’이라는 대원군의 친필 현판이 걸려 있다.","a":"산청 이요정","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663933.jpg"},{"q":"이 정자는 조선시대에 한량들이 활쏘기 연습을 위해 활터에 세운 것이다. ○○○은 숙종 38년(1712)에 다가천 서쪽 냇가에 세웠으나 얼마 후 홍수로 떠내려 가버렸다. 그 뒤 경종 2년(1722)에 다가산 밑에 다가정(多佳亭)이란 정자를 짓고 활터로 사용했다. 순조 30년(1830)에는 이곳에 또 다른 정자를 세우고 옛 이름을 따서 ○○○이라 했다. 이후 북향인 다가정은 젊은 한량들 전용으로, 아늑한 골짜기에 남향으로 자리잡은 ○○○은 주로 노인층이 사용하게 되었다. 다가정․○○○의 활쏘기 모임은 군자정의 모임과 함께, 일제식민지 때 강압에 의해 하나로 통폐합되었다.…","a":"천양정","c":"문화유산자료","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661612.jpg"},{"q":"현재 경기여고 교정에 소재한 ○○○○과 “○○○○○” ○○은 원래 덕수궁(경운궁) 선원전터에 있었던 것으로 경기여고의 정동 교지가 확장되면서 학교에 편입되었다가 1988년 경기여고가 강남으로 이전하면서 옮겨진 것이다. 이 석물들의 원 소재지인 덕수궁(경운궁) 선원전터에는 1910년대에 불교중앙포교소(해인사 末寺)가 세워졌고 1923년에는 ○○○○○이 설치되었다. ○○○○○은 당시로서는 현대적 의료기관으로서 내과, 외과, 조산과 등을 두었다고 하는데 1925년 재정적인 문제로 폐사되었다. ○○○○○이 비록 친일 승려인 이회광(李晦光 1862-1933)에 의해 설립되었다…","a":"불교제중원 오층석탑 및 표석, 석등","c":"문화유산자료","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659320.jpg"},{"q":"고려 충렬왕 7년(1281)에 중국 원나라 세조가 2차례의 일본 정벌에 실패한 뒤, 그해 10월에 환주산(지금의 ○○시 마산합포구 추산공원 일대)에 군사를 배치하고, 진(鎭)을 설치하였다. ○○○은 이곳에 주둔한 군사들에게 마실 물을 공급하기 위해 만든 우물로 추정되고 있다. 우물 앞에 ○○○이라고 쓰인 비석은 1932년 일본인 고적단체에서 세운 것으로, 그 전에는 고려정이라 불렀다고 한다.","a":"창원 몽고정","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664009.jpg"},{"q":"○○○○○은 조선 중기의 사림을 대표하는 성리학자인 ○○○을 중심으로, 그의 조부인 이세좌, 부친인 이수원, 아들 이호약, 손자 이광악의 묘가 위아래 5대에 걸친 ○○ 조성의 전통을 잘 보여준다. 여러 가지 석물들이 당시의 형태를 그대로 유지하고 있어 조선시대 15세기 말에서 17세기 전반에 걸친 시기의 문인석 조각 수법의 변화상을 한 곳에서 엿보고 학습할 수 있는 귀중한 자료이다.","a":"괴산 이연경 묘역","c":"시도기념물","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651641.jpg"},{"q":"1913년경 세운 집으로 안채와 사랑채가 ㅁ자형을 이루고 있다. 안채는 앞면 4칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 앞·뒤 2열로 공간이 나뉜 겹집이며 각각 3칸씩 방을 두었다. 사랑채는 안채로 통하는 대문 옆에 물품을 보관하던 마루방을 두었다. 마루방 뒤쪽에도 방을 조성하고, 건물의 바깥쪽으로는 툇마루를 설치하여 각 방으로 출입이 쉽도록 연결해 주고 있다.","a":"강릉 운파고택","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018122714133500.jpg"},{"q":"○○도 전통가옥의 형태를 간직하고 있는 집으로 1940년대에 지은 것이다. ○○○이라고도 불리는 귀틀집은 통나무를 井자형으로 귀를 맞추어 쌓아 올려 벽을 만들고, 그 위에 너와·굴피·화피 따위로 지붕을 이은 집을 가리킨다. 3칸 규모의 一자형 집으로 귀틀로 벽을 짠 머릿방과 큰방, 수숫대로 만든 부엌이 각각 1칸씩 구성되어 있다. 통나무 사이에는 흙을 채우지 않아 바람이 잘 통하게 하였으며 부엌은 바닥을 낮게 하여 부뚜막을 설치하고 구들을 놓았다.","a":"울릉 나리동 투막집","c":"시도민속문화유산","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659011.jpg"},{"q":"우암 ○○○의 ○○으로 현재 선산곽씨 종중에서 보관하고 있다. 숙종 정축년(1697)에 영당을 세우고 서당을 齋舍로 하였다는 崇禎五癸未年(1943)에 宋近洙가 쓴 <龍門書堂禊座目>의 기록과 庚申年(1920?)에 龍門書堂을 중수하고 쓴 郭守煥의 <龍門書堂重修記>에 원래의 서당 동쪽에 祠宇를 건립하여 眞像을 봉안하고 서당을 齋室로 하였다는 기록으로 보아 1697년경에 제작된 ○○이 있었음이 분명하나 원래의 ○○인지는 알 수 없다. <龍門書堂禊座目>에는 또 \"堂中舊蹟, 有創設以後名案一冊, 而祠中所傳御筆大老祠碑帖及影堂扁額, 藏奉於此\"라 하였을 뿐 이전의 眞像에 대한 언급이…","a":"송시열 초상","c":"문화유산자료","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660829.jpg"},{"q":"이 정자는 조선 중기의 무신인 이윤서(李胤緖, 1574~1624)의 후손인 이봉서(李鳳瑞)가 18세기 말엽에 세운 정자이다. 황강변의 깎아지른 절벽 위에 자리 잡고 있어 경관이 뛰어나며, 정자 바로 위에는 조선 중기의 학자 황강 이희안(黃江 李希顔)을 추모·제향하기 위해 세운 황강정(黃江亭)이 있다. ○○○은 정면 2칸, 측면 2칸 규모의 홑처마 팔작지붕 건물이며, 앞에 마루를 두고 뒤에 방을 배치하였다. ○○○이 자리 잡은 이곳 성산리 내촌(內村) 마을은 ○○ 이씨 전서공파의 집성촌으로서 기묘명현(己卯名賢)인 이윤검(李允儉, 1451~1520)의 후손들이 500여…","a":"합천 관수정","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664364.jpg"},{"q":"의성 김씨 문중의 재실로 사용하던 곳이며 서당 구실도 하여 백운서당이라고도 한다. 조선 정조 2년(1778)에 처음 세웠고 1915년에 다시 고쳤다. 건물은 중앙에 마루를 두고 양쪽에 온돌방을 두었다. 재실 앞에는 옛 모습을 간직한 대문이 있고 주위는 전통 기법으로 담을 쌓았다.","a":"괴산 봉서재","c":"문화유산자료","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660750.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 비석에 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비에는 조선시대 중기의 무신인 ○○○의 공적을 적고 있다. ○○○는 선조 32년(1599) 무과에 급제하여 선전관이 되었으며 곧 감찰에 임명되었다. 광해군 때에는 벼슬에 나아가지 않다가 인조반정 후 통정으로 승진하여 명천부사가 되었다. 이괄의 난 후에는 전라좌수사가 되었고, 이후 여러 관직을 거치다가 인조 13년(1635) 공청병마절도사로 다시 부임하여 이곳에서 병자호란을 맞았다. 적이 쳐들어왔다는 소식을 듣고 병사들을 모아 남한산성으로 향하던 중 광주 부근인 죽산산성에서 적…","a":"이의배신도비","c":"문화유산자료","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661206.jpg"},{"q":"척화비란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국의 중요 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 비는 널찍한 사각받침돌 위에 비몸을 세운 모습으로, 원래는 순흥초등학교 내에 있었으나, 1990년에 이곳으로 옮겨 왔다. 고종 8년(1871) 전국에 동시에 세워진 비로, 대원군이 러시아 공사관으로 납치되고 세계 각국들과의 교류가 이루어지면서 대부분의 척화비는 철거되었으나, 이처럼 몇 기의 비들이 곳곳에 남아 옛 우리민족의 자주의식을 다시금 일깨워주고 있다.","a":"순흥척화비","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662940.jpg"},{"q":"表忠寺 아미타삼존탱은 ○○○ 大光殿 내부 향우측 불단 위에 絹本彩色의 액자형태로 봉안되어 있는 탱화이다. 화면 중앙에 입상의 아미타불을 본존으로 하여 그 좌우에 관음보살과 대세지보살을 협시로 묘사한 이 아미타삼존탱은 일종의 아미타내영도와 같은 성격에 괘불탱과 유사한 구도를 지니고 있다.","a":"밀양 표충사 아미타삼존도","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643077.jpg"},{"q":"이 책판은 범어사의 창건에 관한 기록을 새긴 목판으로 모두 3종으로 되어있다. 이 3종류의 문화유산은 모두가 범어사의 창건과 유래, 중창의 과정, 그리고 가람의 위치에 관한 내용을 담고 있다.『○○○○○』은 동계라는 사람의 기록으로 쓰여있지만, 나머지 두 종류는 그 저자가 확실하지 않다. 오래된 목판으로, 절의 창건과 관련된 귀중한 역사자료로 평가된다.","a":"범어사기·범어사창건사적·범어사고적판","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636661.jpg"},{"q":"미산 김이도의 덕을 추모하고 후진을 양성하기 위해 세운 사설 학원이다. 김이도는 경당 장흥효의 문인으로 학문이 뛰어나 사림들의 존경을 받았다. 선생은 ‘학사가 없으면 뜻을 펼 수 없다.’는 홍학 이념으로 후진을 양성하였다. ○○○○는 현종 11년(1670)에 세웠다. 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 화려한 팔작지붕이다. 건물은 평범한 평면구성이나 앞쪽 큰마루는 난간을 돌려 다락집으로 꾸며 매우 단아한 모양을 지니고 있다. 큰마루 위에는 ‘○○○○’와 ‘삼경당’이라고 쓴 현판이 걸려 있다.","a":"미산학사","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662674.jpg"},{"q":"창주 하증(1563~1624)이 지은 글을 모아 책으로 간행하기 위해 만든 책판은 1897년 12월에 ○○의 오방재에서 목활자로 \"창주선생유사(滄洲先生遺事)\"로 간행되었다가 1939년에 \"창주선생문집\"이란 제목으로 ○○을 제작하여 간행하였다. 전체 63판 107면이 남아 있으며 간재(艮齋) 전우(田愚 : 1841~1922)의 서문과 송종오(宋鍾五 : 1828~1904)의 발문이 새겨져 있다. ○○을 사용하여 만든 책은 많지만 현전하는 ○○은 많지 않아 전통출판문화를 알 수 있는 좋은 자료이다.","a":"진주 담산고택 창주집 목판","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665120.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. ○○초등학교 내에 있는 이 부도는 전체가 마치 연꽃봉오리 모양을 하고 있다. 원래는 ○○○의 옛 절터에 있던 것을 이곳으로 옮겨 놓은 것이다. 부도의 형태는 안상(眼象)을 새긴 네모난 바닥돌 위에 연꽃 받침과 연꽃 봉오리 모양의 탑신(塔身)을 올린 간결한 형태이다. 탑신은 모양 자체도 연꽃봉오리 모양일 뿐만 아니라 표면 전체에도 연꽃잎을 가득 새겨 놓았다. 바닥돌에 새긴 안상무늬와 탑신의 연꽃무늬조각 등으로 보아 고려 전기의 작품으로 추정된다.","a":"영동 심원리 승탑","c":"시도유형문화유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638583.jpg"},{"q":"부여군 백마강가 암벽에 새긴 글씨로, 조선 후기의 문신인 이경여(1585∼1657 ) 선생의 의지를 후손에 알리고자 쓴 것이다. 조선 효종 때 영의정을 지내던 백강 이경여 선생은 효종 8년(1657) 병자호란의 치욕을 씻고자 이완·송시열과 함께 청나라를 쳐야한다는 상소를 올렸다. 왕은 ‘경의 뜻이 타당하고 마땅하지만 진실로 마음이 아프나 뜻을 실현하기에는 너무 늦다’라는 답장을 내렸는데, 청나라에서 그를 벼슬에서 물러나게 하도록 간섭하여, 결국 그는 부여로 낙향하였다. 그 후 우암 송시열이 이 내용을 여덟 자로 써서 후손에게 전하였고, 숙종 26년(1700) 그의 손…","a":"부산각서석","c":"시도유형문화유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639083.jpg"},{"q":"○○○터에 남아 있던 비로, 1990년 10월 11일 광주역사민속박물관으로 옮겨 세웠다. 비는 거북받침돌 위로 비몸을 세우고 지붕돌을 얹은 형태이다. 거북받침은 거의 사각형에 가까우며 등에는 벌집모양의 육각형 안에 ‘王’자를 새겨 놓았다. 길쭉한 비몸 위에는 목조 건축을 모방한 지붕돌이 약간 파손된 채 놓여 있다. 비몸에는 앞면 윗부분에 ‘범자(梵字:불교문자)’자를 새긴 후 그 아래에 세로로 비문을 새겼는데, 이 때문에 ‘범자비’라고 부르기도 한다. 비문에는 질병을 막고 장수를 기원하는 내용이 담겨 있다. 거북의 등에 새겨진 ‘王’자는 고려적인 요소로 보이나, 목조건…","a":"광주십신사지석비","c":"시도유형문화유산","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637138.jpg"},{"q":"봉선에는 1791년 하진태의 어머님이 병이 위독해지자 하진태를 비롯한 가족들이 간병하는 상황 을 10월 16일에서 11월 16일까지 기록하고 있는데 \"조모주병록일기(祖母主病錄日記)\"라하여 하진태(河秦兌)의 아들 익범(益範)이 기록한 것이다. 이러한 ○○ 뒤에 ○○추천 수본(手本) 서목(書目) 상서문(上書文)은 전부 30점으로 그 ○○을 표창해 줄 것을 요로에 요청하는 인근 사림들의 움직임을 살펴볼 수 있는 자료이다. 시기상으로는 1791년에서 19세기 후반에 걸쳐 작성되었다. 특히 봉선(奉先)에 실린 병록일기와 같이 실제 간병○○의 상황을 일기식으로 상세하게 기록하여…","a":"진주 담산고택 효행 관련 문헌","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642419.jpg"},{"q":"봉석주(1418∼1465)의 위패를 모신 사당으로 일명 강성사 또는 하음사라고 한다. 봉석주는 조선 단종 1년(1453)에 세조를 도와 김종서 등 단종추대 세력을 타도하기 위한 계유정란에서 공을 세워 정난 2등 공신이 된 인물이다. 이 사당은 숙종 20년(1694)에 지었고 1926년에 고쳐 지었으며 1970년에 보수한 것이다. 앞면 3칸·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 사당 밖에는 ‘○○○’라고 쓴 현판이 달려 있고 안에는 1926년 승정원 우승지를 지낸 이상각이 짓고 안방준이 쓴 ‘○○○우기(慕忠祠宇記)’와…","a":"청주 모충사","c":"문화유산자료","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660726.jpg"},{"q":"조선 후기의 문신인 ○○○ 선생의 초상화이다. ○○○은 조선 경종 3년(1723)에 병과에 급제하고 병조판서를 거쳐 우의정까지 올랐으며 특히 글씨를 잘 썼다. 초상화는 살색의 대나무 발을 배경으로 두고 호랑이 가죽으로 만든 의자에 앉아 있는 전신상이다. 얼굴은 측면을 향하고 있으나 전체적으로 좌우가 대칭을 이룬다. 머리에는 사모를 쓰고 짙은 청색의 관복을 갖춰 입었으며, 가슴에는 문관을 상징하는 학과 구름을 수놓았다. 수용성 물감을 아교액과 혼합하여 진한 색채로 만들어 사실적으로 표현하고 있다. 현재 개인소유로 관리되고 있으며, 관람할 수 없다.","a":"정우량 영정","c":"시도유형문화유산","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2015122811344400.jpg"},{"q":"이 ○○○은 15세기 초반~19세기 초반에 걸쳐 ○○○ 및 ○○○의 고승들을 모신 묘원(墓園)의 성격을 띠고 있다. 경북 동해안 지역에서 이와 같이 10기(基)가 넘는 부도가 한 장소에 보존되어 있는 경우는 없을 뿐 아니라 완형(完型)이고, 양식적으로 볼 때 영남지역의 부도양식을 대변하고 있는 것으로 파악된다.","a":"포항 보경사 서운암 부도군","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641326.jpg"},{"q":"운곡 ○○○ 선생의 묘이다. ○○○ 선생은 어릴 때부터 학문에 밝아 목은 이색 등과 함께 성리학의 보급에 큰 역할을 했으며 조선 태종의 어릴적 스승이기도 하였다. 고려말에 정치가 문란해지자 이를 개탄하면서 치악산에 들어가 숨어 버렸다. 조선왕조가 들어서 선생에게 벼슬이 주어지자 고려에 대한 충절을 끝까지 지켜 나아가지 않았다. 선생의 묘역 내에는 봉분 앞에 묘비와 제사음식을 차려 놓을 수 있는 상석(床石)이 있고, 조금 떨어진 곳에 신도비가 있는 소박한 형태이다.","a":"원주운곡원천석묘역","c":"시도기념물","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648526.jpg"},{"q":"조선 선조 2년(1569) 송암 권호문 선생이 세워 학문을 가르치던 곳이다. 송암 권호문 선생은 퇴계 선생의 제자로 강호고사(江湖高士)로 알려져 있다. 이곳은 지상 1m 높이의 기단 위에 자연석 주춧돌을 사용한 검소한 건물로 평면은 一자형이고 지붕은 T자형을 이루고 있다. 왼쪽 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이며, 오른쪽은 옆면 지붕선이 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"안동 관물당","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658946.jpg"},{"q":"임경당 김열의 덕을 기리고자 후손들이 지은 별당건축으로, 임경당(강원특별자치도 유형문화유산)보다는 높은 산세를 배경으로 위치하고 있다. 임경당보다 규모가 조금 작은 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 1칸 규모의 대청과 1칸의 온돌방으로 되어있다. 앞면 가운데의 2기둥은 원기둥이고, 양 옆의 기둥은 4각기둥으로 이루어졌다. 건물 안에는 친하게 지내던 율곡 이이가 김열에게 선물로 지어준 ‘호송설(護松說)’을 새긴 현판과 유당 김노경이 쓴 ‘임경당(臨鏡堂)’현판이 걸려있다.","a":"상임경당","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637992.jpg"},{"q":"원적산 능선 위에 있는 조선시대의 암자로 내원사 계곡에 있었다는 89암자 중의 하나이다. 선덕여왕 15년(646)에 원효대사가 지었으며, 인조 24년(1646)에 영훈대사가 다시 지었다. 그 후 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 법당의 현판은 ○○○으로 되어있으며, 앞면 6칸·옆면 3칸 규모이다. 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이며, 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위에만 있는 주심포 양식의 건물이다. 조선 후기 건축양식을 잘 갖추고 있으며, 비교적 변형없이 잘 보존되어 있어 불교건축사에 중요한 연구자료로 이용되고 있다.","a":"양산 안적암 대웅전","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641617.jpg"},{"q":"이 비는 조선 성종 때의 공신인 ○○○ 장군의 ○○○이다. ○○○는 임금이나 공신의 생애를 기록하여 그의 묘 앞에 세운 비석이다. 조선시대에는 정2품 이상의 관직을 지낸 사람에게 세워주어 그 생애를 기리도록 했다. ○○○은 세조비 정희왕후의 언니의 아들이였고 세조에서 연산군 사이에 의금부사, 오위도청 부총관, 호조판서, 경상도 관찰사, 한성판윤 등을 지냈으며 이시애의 난을 평정하는데도 공을 세웠다. 비석의 받침돌은 화강석이고, 비석의 몸 돌과 비석의 머리돌은 하나의 대리석으로 되어 있다. 머릿돌은 지붕모양으로 조선전기 ○○○의 전형적인 양식을 보여주는 좋은 금석 자료…","a":"이철견신도비","c":"시도유형문화유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636914.jpg"},{"q":"병자호란(1636) 때 활약한 양훤의 애국심을 기리기 위해 후손들이 세운 서당이다. 양훤은 남한산성을 포위한 청나라 군사를 무찌르기 위해 ○○ 일대의 의병을 모아 싸웠다. ○○○○은 기록에 따르면 1935년에 세운 것으로 전한다. 이곳은 후학을 가르치기도 했으며, 책을 보관하는 서고(書庫)까지 갖추고 있다.","a":"창녕 광산서당","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663966.jpg"},{"q":"임진왜란 때 의병장으로 활약한 최경회(1532∼1593)와 문홍헌, 을묘왜변 때 순국한 조현 등 3분의 충신을 추모하기 위해 세운 누각이다. 최경회는 선조 원년(1567)에 문과에 급제하고 영해군수를 지냈는데, 상(喪)을 당해 고향인 전라남도 화순에 내려와 있을 때 임진왜란이 일어났다. 그는 형들과 고을 사람들을 규합하여 의병을 모집하였고, 탁월한 용병술과 용장으로 진주 1차 싸움을 승리로 이끌었으며 공로가 인정되어 경상우병사로 임명되었다. 그러나 선조 26년(1593) 왜군이 다시 공격해오자 이를 막지 못하고 9일만에 진주성이 함락되자 문홍헌과 함께 남강에 투신하였…","a":"화순능주삼충각","c":"시도기념물","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654209.jpg"},{"q":"충청남도 아산시 영인면 ○○○의 인적이 드문 산기슭에 있는 ○○○로, 넓고 판판한 화강암에 불상을 조각하였다. 높이 215㎝, 어깨 너비 106㎝이다. 머리에는 둥글고 큰 관(冠)을 쓰고 있는데, 일반적인 갓을 모방한 것 같다. 눈과 눈썹은 귀가 있는 부분까지 길게 조각되어 있으나 입은 이에 비해 작게 표현하여 엄숙한 인상을 풍긴다. 목에는 3줄의 삼도(三道)가 뚜렷하고, 옷은 양 어깨에 다 걸치고 있다. 목에 길게 걸려 있는 목걸이를 오른손이 가볍게 잡고 있다. 불상이라기보다는 스님의 형태에 가까우며, 민간 신앙의 측면에서 미륵정토를 기원하며 만든 것으로 보인다.…","a":"영인신현리미륵불","c":"문화유산자료","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661289.jpg"},{"q":"조선 중기의 고승인 ○○○○의 초상화이다. ○○○○의 자는 현응(玄應)이며, 호는 청허이고, 다른 이름은 서산대사(西山大師)이다. 조선 선조 25년(1592) 임진왜란이 일어나자 왕의 특명을 받아 노령으로 전국에 격문을 돌려 승병 1,500여명을 모아 활약하는 등 전쟁에 공을 세웠다. 초상화는 비단 바탕에 채색하여 그려진 것으로, 향좌측을 바라보며 의자에 앉아 있는 전신교의좌상(全身交椅坐像)으로서 족좌대(足座臺)를 하고 있다. 왼손에는 짙은 갈색의 염주를 쥐고 있고, 오른손은 의자의 손잡이를 살짝 쥐고 있다. 얼굴색은 황백토를 바르고, 가는 먹선으로 육신선을 표현하고…","a":"함양 용추사 청허대사 영정","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023102312352700.jpg"},{"q":"대문간채, 안채, 사랑채, 고간채에 의해 □자 배치형식을 하고 있으며 종가집으로써의 품위를 갖추고 있다. 일제시대 대정 7년(1918)과 8년에 건축되어졌으며 근대 전통한옥으로 분류된다. 안채는 전면 6칸 측면 2칸의 규모로서 측면은 안대청이 만들어지고 대청안에 안상방이 있다. 각방들은 사이의 장지문을 없애고 생활의 편리를 위하여 한칸으로 크게 사용하고 있으며 부엌도 현대식으로 개량하였다. 전면에 툇마루를 두었고 기단은 자연석 초벌쌓기 위에 장대석 기단을 놓았고 굴도리 5량가 팔작 한식기와지붕형식이다. 사랑채는 사랑대청과 사랑방+사랑방으로 구성되며 대청 옆의 사랑방에…","a":"강릉최씨동원군종택","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660632.jpg"},{"q":"○○○은 류덕용(1563～1644)선생을 모신 재실로 고종 10년(1873) 문중에서 뜻을 모아 건립하였다. 건물은 정면 4칸, 측면 1칸 반의 규모로 전면 반 칸에 퇴를 둔 전퇴집 형식으로 실의 배열은 가운데 둔 2칸의 대청을 중심으로 좌, 우에 각 1칸씩의 방을 들인 구성이다. 마루는 모두 우물마루로 구성하였으며 전퇴칸도 툇마루로 구성하여 마루의 면적을 넓혔고 양측방의 뒤쪽에는 벽장을 시설하였다. 자연석을 3～4단 정도 쌓아 조성한 기단위에 초석을 놓고 기둥을 세웠는데 기둥은 전면에만 원기둥을 사용하였다. 가구는 3량구조로 툇간에서 보낸 퇴보와 연결한 대들보 위에…","a":"합천 북산정","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665512.jpg"},{"q":"○○○는 옛 선현의 자취를 살피어 후세에 전하고 이를 계기로 그를 추모하기 위해 세워두는 비로, 이 비는 고려 후기의 문신이면서, 일직(一直) 손씨의 시조이기도 한 ○○○ 선생의 공적을 기리고 있다. ○○○은 원래 순씨였으나 현종의 이름과 같다하여 성을 손씨로 고치었다. 충선왕 대에 과거에 급제하여 벼슬길에 올라, 도첨의찬성사를 거쳐 판삼사사에까지 이르렀으며, 그 이듬해에는 복천부원군에 봉하여졌다. 공민왕 11년(1362) 홍건적의 난이 일어났을 때 난을 평정하자, 왕은 그에게 지팡이와 초상화 등을 내려주며 공을 치하하였다. 비각안에 모셔둔 비는 낮은 받침돌 위로 비…","a":"손홍량유허비","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662481.jpg"},{"q":"○○○라는 절터에 있는 다층의 목탑 유구이다. ○○○지는 월출산 사자봉에 있는데 그동안 천황사라고 불리어 오다가 발굴 조사에서 ‘○○○’라는 명문이 출토됨으로써 절이름이 밝혀졌다. ○○○에서 통일신라 후기에 조성된 기와들이 발견되어 이때 ○○○가 창건된 것으로 보인다. ○○○의 기단은 한변의 길이가 10.5∼10.8m로 거의 정사각형을 이루고 있다. 남쪽과 서쪽은 장대석과 할석들로 단면 장방형으로 쌓아 만들었다. 기초를 이루는 초석은 양면 각각 4개가 아주 정연하게 노출되었는데 남서쪽 모서리 1개만 유실되고 없다. 각 초석 간의 거리는 약170㎝이며, 양 모서리 초석…","a":"영암사자사목탑지","c":"시도기념물","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654353.jpg"},{"q":"시종면 ○○○ 본촌마을 북쪽에 있는 구릉의 능선을 따라 분포되어 있는 3기의 고분으로, 각각 말무덤, 장수무덤, 마부무덤으로 불리고 있는데 일제강점기에 모두 도굴되었다. 1호분은 말무덤으로 불리는 것으로, 본촌마을에서 북쪽으로 250m 정도 떨어진 구릉의 정상부에 있다. 분구는 비교적 양호한 상태로 남아있지만 서남쪽에 풍산홍씨(豊山洪氏) 선산이 만들어지면서 다소 변형되었다. 분구의 평면형태는 원형이며 규모는 직경 15m, 높이 1.8m 이다. 2호분은 1호분에서 남쪽으로 150m 정도 떨어져 있는 것으로, 장수무덤으로 불리는 것이다. 고분은 비교적 잘 남아있지만 서쪽…","a":"영암금지리본촌고분군","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662258.jpg"},{"q":"○○○○○의 ○○은 인조 때 한성부 좌우윤을 지냈으며 백성을 위해 교화를 베풀고 청렴했던 ○○○이라는 인물의 ○○으로 서울과의 관련성이 크고, ○○과 ○○ 내 석물들은 조선 후기 묘제 및 석물 제작 양상을 알 수 있게 한다는 점에서 보존가치가 크다. 특히 신도비(神道碑)는 조경(趙絅)의 문장과 이정영(李正英)·조위명(趙威明) 등 당대 명문장가와 명필들의 글씨를 확인할 수 있게 하는 자료로 정사(正史)인 실록 등을 보완하는 사료적 가치를 가진다.","a":"충정공 목서흠 묘역","c":"시도기념물","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644867.jpg"},{"q":"조선 인조(재위 1623∼1649) 때의 충신 박신용 장군의 위패를 모신 사당이다. 지금도 그의 충의 정신을 길이 빛내기 위하여 관복을 소장하고 봄·가을로 제사를 지내고 있다. 박신용 장군은 선전관이 되어 군사들을 이끌고, 몸을 던져 싸우다 죽었다. 이 때 조정에서 내린 관복이 있어 후손이 보호 관리하여 오다가 조선 후기에 이르러 관복을 보관할 건물을 짓고 ○○○이라 부르고 제사를 드렸는데, 그 내용을 석비로 만들어 새겨 놓았다. 건물은 사당 형식으로 만들었고, 문은 가운데 칸을 높여 세운 삼문(三門)형식으로 주변은 담장을 둘렀다.","a":"유의각","c":"문화유산자료","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661148.jpg"},{"q":"고려 후기의 문신인 ○○ 이제현(1287∼1367) 선생의 초상화이다. 선생은 원나라의 만권당에서 조맹부 등과의 교류를 통해 고려에 신학문과 사상 등을 소개하고 성리학의 전파와 발전에도 중요한 역할을 했다. 조맹부 글씨를 도입했으며『국사』,『역옹패설』등을 저술하였다. 선생의 초상화는 모두 4점이 전하는데 그 중 1점으로, 고려 충숙왕 6년(1319) 선생이 왕을 따라 중국에 갔을 때 진감여가 그렸던 원본(국립중앙박물관 ○○)을 18세기 후반에 옮겨 그린 것이다. 왼쪽을 바라보며 의자에 앉은 전신상으로, 두 손은 소매 안에서 마주잡고 있다. 의자 뒤로 책과 향로, 가야…","a":"장성 가산사 소장 익재 영정","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662147.jpg"},{"q":"우암 송시열(1607∼1689) 이 학문을 연구하며 지내던 집이다. 후에 우암의 제사를 모시는 한천서원을 세웠었는데, 고종 5년(1868)에 서원을 철거하였고 후에 후학들이 다시 지은 것이다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 중앙에 대청마루가 있고 양쪽 끝에 온돌방을 두었다. 주변에 담장을 두르고 앞면에 문을 두었는데 앞면 양측에 은행나무가 있다.","a":"영동 한천정사","c":"문화유산자료","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660767.jpg"},{"q":"○○○○○는 1498년(연산군 4) 무오사화로 인해 순천 지역으로 유배된 조위(曺偉)[1454~1503]와 김굉필(金宏弼)[1454~1504]이 돌을 쌓아 대(臺)를 만들어 교유(交遊)하던 곳으로 조위가 ‘항상 마음을 깨끗이 가지라’라는 뜻으로 ‘임청대’라 이름 지었다. 조위는 1498년 순천에 유배 왔고 김굉필은 평안도 희천으로 갔다가 1499년 순천 지역으로 이배(移配)되었다. 1565년(명종 20) 순천부사로 부임한 이정(李禎)[1512~1571]이 그들의 덕을 기리기 위해 임청대비를 세우고 옥천서원(玉川書院)도 건립하였다. 현재 옥천서원 경현문 오른편에 위치하…","a":"순천임청대","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639921.jpg"},{"q":"○○○○○은 조선 명종(재위 1545∼1567) 때 공조좌랑을 지낸 김경우가 관직에서 물러나 은거하기 위해 지었다는 ○○○이라는 정자 주위의 숲을 가리킨다. ○○○에 올라서면 옥녀봉이 눈에 뜨이고, 황룡강과 탁 트인 들판이 보인다. 정자 주위를 60여 그루의 배롱나무가 둘러싸고 있으며, 소나무가 숲을 이루고 있어 여름이면 경치가 더 아름답다. 정자에는 하서 김인후, 고봉 기대승 등 명현들의 시가 현판에 새겨있다. 그 중에서 후손 김경찬이 이 곳의 경치를 찬양하여 ‘조선 제일의 황룡이다’라고 현판에 새겼더니, 나라에서 불러 “황룡이 조선 제일이면 한양은 어떠하냐”라고…","a":"장성 요월정 원림","c":"시도기념물","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654193.jpg"},{"q":"○○○은 백양사에 소속된 암자로 고려 충정왕 2년(1350)에 각엄왕사가 세웠다. 이곳 ○○○은 마음을 청청한 맑은 물에 비유하여 맑고 깨끗한 심성으로 선(禪)에 든다고 하여 ○○○이라 하였다고 한다. 백양사 경내에 들어서 왼쪽 계곡을 건너 가파른 산길을 2㎞가량 오르면 ○○○에 이른다. ○○○ 안에는 ○○○과 요사채가 있다. ○○○은 기단 위에 커다란 주춧돌을 놓고 두툼한 원형기둥을 세웠다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짠 익공 양식으로 꾸몄다, 공포의 뻗쳐 나온 부재 끝부분에는 연꽃봉오리를 얹었다.","a":"장성 청류암 관음전","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662172.jpg"},{"q":"임진왜란 때 많은 공을 세운 농포 정문부(1565∼1624)가 가족들의 피난처로 사용하던 곳이다. 전쟁 후 고향인 진주로 돌아가면서 손녀 사위인 사위당 이강에게 주었는데, 현 소유주의 6대조가 사들여 오늘에 이르고 있다. 거북 모양의 땅 위에 거북 모양으로 건물을 배치하였다. 거북의 앞발에 해당하는 곳에 별당과 방앗간을 두었고, 머리 부분에 속하는 앞면에는 누에를 치던 잠실을 두었다. 꼬리 부분에는 화장실을 배치하였다.","a":"포항 오덕리 애은당 고택","c":"시도민속문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658771.jpg"},{"q":"선지당은 경주 김씨를 중흥시킨 시조이며, 고려 후기에 충청도 관찰사를 지낸 ○○○ 선생과 손자 김영년이 살던 곳이다. ○○○ 선생은 고려 공민왕 23년(1374) 문과에 급제한 후 여러 관직에 올랐으나 벼슬을 그만두고 고향인 안동에서 숨어지냈다. 그 후 조선이 개국된 후 태종이 형조판서에 오르게 하였으나 사양하였고, 자손에게 결코 무덤을 만들지 말라는 유언을 남기고 자결하였다. 선생의 손자 김영년은 문종(재위 1450∼1452) 때 강릉판관을 지내다가 관직에서 물러난 후 선지당에서 많은 인재를 배출하며 후학 양성에 몸바쳤다. 선지당의 구조는 앞면 5칸·옆면 2칸의 옆…","a":"영동 김자수 고가","c":"시도기념물","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649707.jpg"},{"q":"조선 효종의 사위인 ○○○과 숙경공주(淑敬公主)의 묘역이다. ○○○은 1659년(효종 10)에 효종의 여섯 번째 공주인 숙경공주와 혼인하여 흥평위(興平尉)가 되었고, 후에 흥평군(興平君)에 봉해졌다. 묘역은 숙경공주와 합장한 하나의 봉분 형태이다. 묘역 주변에는 곡장(曲墻; 봉분이 있는 구역을 보호하기 위해 주위에 두르는 담)이 둘러져 있으며, 봉분 하단에는 둘레석을 조성하여 공주의 묘격을 반영하였다. 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)는 비교적 큰 규모인데, 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이다. 제작 연대가 새겨져 있지…","a":"죽서원몽린묘역","c":"문화유산자료","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660259.jpg"},{"q":"○○○○는 1920년대에 상량한 건물로 근대한옥의 건축적 특성을 잘 나타내고 있으며, 유학자 계제 정제용(1865~1907)의 아들 정덕영과 장손 정정화가 남사로 이전한 후 선친을 추모하기 위하여 지은 재실이다. 건물의 규모는 정면 7칸, 측면 2칸이다. 지붕은 팔작지붕 형태이며, 기둥의 형태는 외진주가 원기둥이고 내진주는 네모난 기둥이다. 양쪽 끝으로는 각각 1칸의 마루가 있으며, 계자난간을 두었다. 두 칸의 대청을 사이에 두고, 방이 오른편에 2칸, 왼편에 1칸이 있다","a":"산청 사양정사","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666463.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 비래골 마을회관 앞 논에 ○○○ 2기가 있고, 맞은편 구릉 정상부에 1기의 ○○○이 있다. 1호 ○○○은 덮개돌의 절반이 마치 입석처럼 세워져 있는데, 1963년 새마을 운동 당시 동네 주민들이 덮개돌을 쪼개 표면에 새마을기를 그려…","a":"비래동고인돌","c":"시도기념물","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645829.jpg"},{"q":"이 영정은 ○○○ 우민선사의 좌안7분면 바닥가부좌상이다. 화면은 운보문이 가득한 녹색 상단벽면과 돗자리의 이단구도이며, 돗자리위에 방석을 깔고 왼손엔 불자의 병부를 쥐고 오른손으로는 불자의 술을 가볍게 쥔 채 앉아 있으며, 옆으로는 서안과 서책이 보인다. 화면 향좌측엔 ‘선교양종대선사○○○○○지진(禪敎兩宗大禪師日逢堂遇旻之眞)’의 화제가 있으며, 화면 크기는 가로 66.3cm, 세로 98.0cm이다.","a":"일봉당우민 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643032.JPG"},{"q":"○○○○○은 경상북도에서 가장 오래된 성당이다. 1895년 초대 주임 신부로 부임한 가밀로 파이아스(한국이름 하경조) 신부가 다섯 칸 규모의 기와집을 본당으로 사용한 것이 시초였다. 수로를 이용하여 내륙으로 천주교를 전파하고자 낙동강 선착장 가까이에 위치하였으며 이후 신자가 늘어 본당이 비좁아지자 1923년 당시 주임 신부였던 투르뇌(한국이름 여동선) 신부가 현재의 자리에 성당을 새로 지었다. 설계는 명동성당 등을 설계한 빅토르 루이 푸아넬(한국이름 박도행)* 신부가 맡았다. ○○○○은 지하 1층, 지상 1층의 신로마네스크 양식 건축물로 정면 중앙에 종탑이 있다. 내…","a":"칠곡 가실성당","c":"시도유형문화유산","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2022041516231100.JPG"},{"q":"전북특별자치도 남원 선원사 대웅전 안에 있는 높이 66cm, 입 지름 47cm의 조선시대 범종이다. 종의 맨 위, 매다는 고리 역할을 하는 용뉴는 한 마리 용이 웅크리고 있는 모습인데, 세부적인 표현은 따로 만들어 붙여서 완성하였다. 종의 몸체는 먼저 4줄의 가로선을 그어 5구역으로 나누었다. 맨 위에는 작은 원 11개를 나열하고, 원 안에 범자를 1자씩 새겨 넣었다. 그 아래로는 보살상을 4곳에 두었고, 보살상 사이에 꽃과 덮개, 관(冠)을 불규칙하게 나열하였다. 가운데 가장 넓은 곳에는 4개의 사각형 모양의 유곽을 만들어 둘레를 파도무늬로 장식하였다. 아래 남은…","a":"선원사동종","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639392.jpg"},{"q":"매천 황현(1855~1910) 선생의 위패를 모신 사당이다. 황현 선생은 한말의 순국지사이자 시인이며 문장가이다. 전라남도 광양에서 태어났으며 어려서부터 시를 잘 짓고 재질이 뛰어났다. 1894년 동학농민운동·갑오경장·청일전쟁이 연이어 일어나자 위기감을 느끼고, 경험과 견문한 바를 기록한 『매천야록(梅泉野錄)』·『오하기문(梧下記聞)』을 지어 후손들에게 남겨 주었다. 1905년 11월 일제가 강제로 을사조약을 체결하여 국권을 박탈하자 김택영과 국권회복 운동을 시도하였으나 실패하였다. 1910년 8월 일제에게 강제로 나라를 빼앗기자, 절명시 4편과 유서를 남기고 아편을…","a":"매천사","c":"문화유산자료","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661961.jpg"},{"q":"임진왜란 때 의병장으로 활동했던 곽재우(1552∼1617)의 충절을 추모하기 위해 세운 서원이다. 곽재우는 임진왜란이 일어나자 의병을 조직하여 경상도 일대에서 활약하여 큰 공을 세운 인물로 붉은 옷을 입은 장군이라는 뜻의 ‘홍의장군’으로도 널리 알려져 있다. 광해군 10년(1618)에 ‘충현사’로 처음 세웠고 현종 15년(1674)에 규모를 확장하여 서원의 모습을 갖추었다. 숙종 3년(1677) 나라에서 인정한 사액서원으로 ‘예연’이라는 이름을 받았다. 흥선대원군의 서원철폐령으로 고종 5년(1868)에 폐쇄되었고 한국전쟁으로 완전히 소실된 것을 1977년과 1984년…","a":"예연서원","c":"시도기념물","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645376.jpg"},{"q":"○○○○○은 파평 윤씨의 집성촌이었던 윤촌마을(○○○) 초입에 남수산을 뒤로하여 남동향으로 자리 잡고 있다. 1750년(조선 영조 26)경 건립되었다고 하며, 1960년경 중수하였다. 이 집은 정면 4칸× 측면 4칸 규모의 뜰집으로 사랑채와 안채가 연이어져 □자형을 이루고 있다. 구조는 자연석 기단위에 막돌초석을 놓고 그 위에 네모기둥을 세웠다. 상부구조는 사랑채와 안채 모두 삼량가로 대량위에 동자주를 얹어 종도리를 받게 한 간략한 구성이다. 이 ○○은 몇 차례 중수를 거치면서 부분적으로 개조·변용되기는 하였으나 안채와 사랑채 사이에 쪽마루를 부설한 뜰집형으로 생활의…","a":"울진 매화리 윤광수 가옥","c":"문화유산자료","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663555.jpg"},{"q":"경남 진해시 현동 고산에 있는 이 산성은 고려말 우왕 10년(1384)에 만든 것이다. 완향성, 비봉산성, 현동산성으로 불렸으며 왜구의 잦은 침입을 방어하고 백성을 보호하기 위하여 만든 것이다. 그러나 ○○○이 웅천현에 합쳐지면서 행정적인 기능을 상실한 것으로 추정한다. 북벽과 동벽이 만나는 산 정상에 고산 봉수대가 있으며, 절벽 위에 세운 남벽을 제외한 동·서·북에는 문터를 두었는데, 서벽은 2곳에 문터를 두었다. 안쪽 벽은 3∼5단의 계단식으로 만들었으며 동벽과 남벽 성 안에는 일정한 간격으로 언덕을 두었다. 이곳의 성벽 모서리에는 관측과 지휘에 용이하도록 각루(…","a":"창원 완포현 고산성","c":"시도기념물","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656362.jpg"},{"q":"○○○○에 모셔져 있는 불화로, 석가의 생애를 여덟 장면으로 나누어 묘사한 ○○○이다. ○○○의 여덟 장면은 석가모니가 도솔천에서 코끼리를 타고 사바세계로 내려오는 장면인 도솔래의상, 석가모니가 룸비니공원에서 마야부인의 옆구리를 통해 출생하는 모습을 그린 비람강생상, 태자가 성문 밖의 중생들의 고통을 관찰하고 인생무상을 느끼는 장면의 사문유관상, 부모의 반대를 무릎쓰고 출가하는 장면을 묘사한 유성출가상, 설산(雪山)에서 신선들과 수행하는 모습을 그린 설산수도상, 태자가 수행 중 온갖 유혹과 위협을 물리치는 수하항마상, 부처가 녹야원에서 최초로 설법하는 모습을 나타낸…","a":"혜원정사 팔상도","c":"문화유산자료","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042510134700.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 익산 ○○○○ 가마터는 미륵산 동편에 있으며, 2기의 가마터가 발굴되었다. 가마터의 구조는 반지하식으로 반원형의 천장이 위로 향하면서 경사를 이루는 굴가마(등요)로 밝혀졌다. 아가리큰항아리(광구호), 세발토기(삼족토기), 항아리가 출토되었다. 이 가마터는 백제 후기의 토기 모양을 파악할 수 있는 유적이며, 일본 오사카에 있는 6세기경 가마터의 구조와 비슷한 면이 많아 일본의 토기 제작기술이 백제로부터 비롯되었음을 말해 주는 중요한 유적이다.","a":"익산백제토기도요지","c":"시도기념물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653336.jpg"},{"q":"광덕사 뒷편의 작은 봉우리에 자리하고 있는 사리탑으로, 진산화상의 사리를 모시고 있다. 진산화상은 통일신라시대의 승려로, 흥덕왕 대에 이 절을 새로이 고쳐지었다. 탑은 종 모양을 이루고 있는 형태로, 낮은 바닥돌 위로 4각 기단(基壇)을 마련하여 종 모양의 탑신(塔身)을 올려놓았다. 탑신에는 ‘진산화상(珍山和尙)’이라는 글귀를 새겨 주인공을 밝히고 있다. 꼭대기에는 탑신과 한돌로 이루어진 꽃봉오리 모양의 머리장식이 솟아나 있다. 각 부분에 특별한 꾸밈을 두지 않은 통일신라 후기의 작품이다.","a":"광덕사부도","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661310.jpg"},{"q":"대지 내에 안채와 사랑채, 문간채가 주축선상에서 안마당과 사랑마당을 가운데 두고 전후 3열의 三자형으로 배치되었으며, 안마당 우측에 곳간채가 모로 자리 잡고 있다. 안마당을 중심으로 경리시설을 집약 배치한 근대기 남부지방 부농주택의 일반적인 배치방식을 따르고 있는데 전반적인 배치 및 외부공간 구성면에서 볼 때 남여 생활공간의 구분이 미약하고 마당구성 및 동선처리에 두드러지는 특징은 없다. 사랑채 마루의 충량에 ‘歲在丙辰...’이란 쓴 묵서명으로 보아 1916년 4월에 상량한 건물임을 알 수 있다.","a":"의령 안범준 고택","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666385.jpg"},{"q":"조선 후기의 문신인 이계(耳溪) 홍양호(1724∼1802)의 묘소이다. 영조 23년(1747)에 진사시에 합격하고, 1752년 정시문과에 급제하여 사헌부 지평·홍문관 수찬·홍문관 교리 등을 거쳤다. 뒤에 사간원 대사간·사헌부 대사헌·홍문관 대제학·예문관 대제학 등의 높은 벼슬에 올라 최고의 영예를 누렸다.『영조실록』·『국조보감』·『동문휘고』등을 비롯한 여러 편찬사업을 주관하기도 하였으며, 지방관의 지침서인『목민대방』을 지었다. 그 밖의 저서로는『육서경집』·『고려대사기』·『동국명장전』등이 전한다. 2차례에 걸쳐 중국을 다녀오면서 석학들과 교류하여 이름을 날렸으며 고증학…","a":"홍양호묘","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660883.jpg"},{"q":"○○○는 조선시대의 유명한 유학자인 주세붕(1495∼1544) 선생의 영정과 유품을 모신 곳이다. 선생은 중종 38년(1543)에 백운동 서원을 세워 우리나라 서원의 시초를 이루었으며, 이를 기리기 위하여 숙종 24년(1698)에 선생의 후손이 세웠다. 고종(재위 1863∼1907) 때 흥선대원군에 의해 철폐되었다가 유림들이 다시 세웠으나 한국전쟁으로 불탔다. 현재의 무산서당은 그 후에 세운 것이다. ○○○ 내에 있는 무산서당은 앞면 5칸·옆면 2칸의 1층 건물이다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다. 중앙 2칸의 대청을 사이에 두고 양 옆에 각각…","a":"함안 무산사","c":"시도유형문화유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641713.jpg"},{"q":"이 서원은 조선중기 인물인 이사룡(李士龍)을 제향하기 위해 건립한 것이다. 서원은 숙종 18년(1692) ○○목사와 관내의 사민(士民)들에 의해 그가 살았던 곳인 월항면 인촌리 작촌에 충렬사(忠烈祠)로 처음 건립된 것에서 연유하며, 정조 20년(1796) 사액되었다. 그 후 충렬사는 옥천충렬사(玉川忠烈祠) 또는 ○○○○으로 불려지다가 고종 8년(1872)서원훼철령에 의해 철폐되었으며, 1919년 직계후손들의 집성촌이 있는 현 위치에 중건되었다. 이사룡(李士龍, 1595∼1641)은 본관이 성산(星山), 자는 사중(士中)으로 조선 중기의 무인이다. 그는 인조 18년(1…","a":"성주 옥천서원","c":"시도기념물","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654685.jpg"},{"q":"○○○○는 고려 태조 왕건을 도와 후 삼국 통일에 지대한 공을 세운 삼태사의 한사람인 ○○ 장씨(安東張氏) 장길(張吉)의 제단을 수호하고 제사를 준비하기 위한 집이다. 1806년에 건립하고 1853년에 중건하였으며, 1966년에 누문인 영휘루(永輝樓)를 건축하였다.","a":"안동 장태사공 성곡재사","c":"시도기념물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654670.jpg"},{"q":"조선 전기 무신인 ○○○ 장군의 충절을 기리기 위해 세운 것이다. 장군은 무과를 거쳐 평안도 용천현감을 비롯한 8개 고을에서 청렴한 목민관으로 이름을 떨쳤다. 선조 25년(1592) 양산군수 재임시 임진왜란이 일어나자 동래성으로 가 이미 적군에게 포위되어 있는 싸움터에서 도망하지 않고 끝까지 싸우다 전사하였다. 현종 10년(1669) 그의 효행과 충절이 알려져 충신으로 ○○되고 호조참판으로 추대되었으며, 현재 동래의 ‘안락서원’, 양산의 ‘충렬사’ 등에서 배향되고 있다.","a":"장성 조영규 정려","c":"시도기념물","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654211.jpg"},{"q":"선운사의 산내암자인 도솔암에 있는 법당이다. 정면3칸 측면1칸에 맞배지붕으로 되어 있으며, 현존하는 건물은 건축수법으로 보아 조선 말기에 세워진 것으로 보인다. ○○○ 내부에는 흙으로 빚은 석가모니불을 중심으로 가섭과 아난이 협시하였고, 1910년 용문암에서 옮겨온 16나한상을 모시고 있다. 도솔암은 선운사의 산내암자로서 대웅전 서쪽 150m정도 떨어진 곳에 있으며, 원래는 여섯 도솔암이 있었으나 현재는 상하 2개의 도솔암만 남아 있다. 전하는 바에 따르면 조선시대 도솔암 용문굴에 이무기가 살면서 주민들을 괴롭혔는데, 이를 쫓아내기 위해 인도에서 나한상(羅漢像)을 모…","a":"나한전","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661737.jpg"},{"q":"조선 중기 진무성 장군의 위패를 모신 사당으로 봄, 가을에 제사를 지내고 있다. 송계 진무성 장군은 조선 중기 무신으로 선조 25년(1592) 임진왜란이 일어나자 이순신 장군 휘하의 군관으로 공을 세우고 용명을 날렸다. 인조 5년(1627) 정묘호란이 있은 뒤에는 공로가 인정되어 북방요지 구성군수에 임명되기도 하였다. 순조 26년(1826)에 고흥군 대서면 상남리에 용강사를 지어 진무성 장군 및 3분의 위패를 모셨으나, 고종 5년(1868)에 서원철폐령으로 해체되었다가 고종 19년(1882)에 이곳에 복원하여 무열사라 하였다. 2번에 거쳐 고쳐 지었으며, 진무성 장군…","a":"고흥무열사","c":"시도기념물","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654151.jpg"},{"q":"○○○는 백제 성왕 24년(546)에 고봉과 발용 두 스님이 세웠다. 고려 태조 25년(942)에 은장이라는 사람이 고쳐 세웠고, 최근에는 1947년까지 고쳐 지어 오늘에 이르고 있다. ○○○은 조선 영조(재위 1724∼1776) 때를 전후한 시기에 지은 것으로 보인다. 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 석가모니불, 아미타불, 약사불 및 후불탱화, 지장탱화, 신중탱화를 모시고 있다.","a":"상원사대웅전","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661756.jpg"},{"q":"이 집은 정방형에 가까운 대지의 안쪽으로 안채를 배치하고 안채의 좌측 아래로 아래채를 두었으며, 안채의 좌측 위쪽으로는 곳간채를 두었다. 안채는 정면 7칸, 측면 2칸 반 규모의 전퇴집이고, 아래채는 정면 4칸, 측면 2칸의 'ㅡ'자형이며, 곳간채는 아래채에 못지않은 큰 규모의 흙벽으로 되어 있다. 이 집은 1924년 지어져 조선후기 건축의 특징인 측면간의 확장을 볼 수 있으며 겹지붕 형식이라는 특징도 가지고 있어 학술적 가치가 있다.","a":"산청 박인현 고택","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666408.jpg"},{"q":"정려란 충신·효자·열녀 등 모범이 되는 사람을 표창하고자 집 앞에 정문(旌門)을 세워 기리던 것으로, 이 비는 조선시대 사람인 박구의 효행을 기리고 있다. 박구(?∼1425)는 효성이 지극한 자로, 그의 어머니가 돌아가시자 3년간 묘곁을 지키면서 한번도 집에 돌아가지 않았다고 한다. ○○○는 높이 110㎝, 폭 43㎝, 두께 16㎝의 비석으로 앞면에 비문을 새겼다. 비를 보호하기 위한 비각은 앞면 1칸·옆면 1칸의 규모로, 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕을 올리고 있다. 비각의 앞면 윗부분에는 현판이 걸려 있고, 그 밑으로는 비의 내력…","a":"박구효자정려비","c":"시도민속문화유산","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658846.jpg"},{"q":"중앙에 앉아 있는 본존불을 중심으로 오른쪽에 지장보살, 왼쪽에 관음보살이 서 있는 삼존불(三尊佛)이다. 모두 머리와 손, 발 등이 없어진 채로 흩어져 있던 것을 석고로 복원해 놓은 것이다. 본존불은 왼쪽 어깨에 옷을 걸치고 있으며 옷주름을 부드럽게 새겼고, 두 팔은 모두 내려 무릎 부근에 대고 있다. 수염의 표현과 꼭 다문 작은 입이 인상적이며 귀는 길지 않다. 지장보살은 민머리에 본존불과 같은 얼굴이며, 옷은 양 어깨를 감싸고 입었다. 관음보살은 주먹을 쥔 오른손을 가슴에 대고 있으며 머리에는 관을 썼다. 팔·다리 등의 근육, 옷을 입는 법, 건장한 신체 등으로 보…","a":"고성 교사리 삼존석불","c":"시도유형문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641623.jpg"},{"q":"지장보살상은 목조도금, 명부 시왕등의 권속상은 석조 채색으로 조성연대는 복장유물에서 발견된 묘법연화경의 말미에 戊午라는 간지로 미루어 1858년으로 추정되며, 23구의 동시 조성된 작품이다.","a":"밀양 표충사 목조지장상및석조시왕상","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643064.jpg"},{"q":"○○○○의 업적을 기리기 위해 조성한 이 비석은 ○○○ 입구로 들어서서 오른쪽 숲 속의 부도 밭에 세워져 있다. 조선 철종 9년(1858)에 건립한 것으로 비명(碑銘)은 조선시대의 대명필가인 추사(秋史) 김정희(金正喜)의 필적이다. 조선조의 억불정책에도 불구하고 오랜 침체기를 헤치며 조선후기 불교의 참신한 종풍(宗風)을 일으킨 화엄종주(華嚴宗主) ○○○○의 업적이 적혀 있는 이 비석은, 네모난 받침 위에 몸통을 세우고 지붕돌을 씌운 모습으로 되어 있다.","a":"선운사백파율사비","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639549.jpg"},{"q":"○○○는 신라 진평왕 5년(583)에 무염선사가 창건한 것으로 알려져 있으나 확실하지 않다. ○○○라는 절의 이름은 신라 마지막 왕인 경순왕이 \"주위 산수의 경치가 아름답고 조용하여 몸과 마음이 아울러 편안하다\"고 한데서 비롯되었다고 한다. 원래 ○○○에는 대광전·○○○·진향각·요묵당 등이 있었으나, 현재는 대광전·○○○만 남아 있다. ○○○의 정확한 건립연대는 알 수 없으나 영조 14년(1756)과 헌종 11년(1845)에 각각 중수하였다는 상량문이 발견되어 17세기 후반에 지어진 것으로 추정하고 있다. ○○○○○은 정면 3칸, 측면 3칸 규모의 겹처마 맞배지붕 건…","a":"신안사 극락전","c":"시도유형문화유산","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639203.jpg"},{"q":"조선시대의 정자로 광해군 2년(1610)에 오명립이 벼슬을 단념하고 낙향하여 지은 정자이다. 자신의 호를 따서 ‘○○○’이라 하였으며, 이곳에서 강의하고 제자를 길렀다. 숙종 30년(1704)에 다시 짓고, 영조 14년(1738)과 순조 2년(1802)에 수리하였다. 그 뒤 고종(재위 1863∼1907) 때 담장과 중문을 지었다. 앞면 3칸·옆면 2칸 규모로 옆면이 여덟 팔(八)자 모양으로 화려한 팔작집이다. 현재 이곳에는 우암 송시열이 쓴 현판과 권상하가 쓴 ‘○○○’현판이 있다. ○○○ 주변에는 같은 시대에 오유립이 세운 월송정이 있다.","a":"청주 지선정","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638569.jpg"},{"q":"전형적인 조선 후기의 상류주택이다. 원래는 안채와 사당 등이 모두 갖추어져 있었으나 지금은 사랑채와 행랑채만이 남아 있다. 행랑채는 一자형으로 중간에 대문을 냈으며, 사랑채 역시 一자형으로 고종 8년(1871)에 세웠다. 가운데 대청을 중심으로 양쪽에 온돌방을 두었다.","a":"해남정명식가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658355.jpg"},{"q":"동강 김우옹 선생을 추모하기 위해 세운 서원이다. 김우옹(1540∼1603)은 조선 명종과 선조 양대에 이조판서와 대제학, 경영관을 지냈으며, 20권의 문집과 속강목 36권을 펴내기도 하였다. 이 서당은 1902년에 지었으며, 1922년에는 ‘굉정각’이란 서고를 만들어 청주서원에서 보관하고 있던 선생의 문집 판각 600매를 옮겨 왔다. 서당의 전체적인 구조는 배우는 공간인 서당이 앞쪽에 있고 그 뒤로 사당과 판각을 보관하는 전각이 나란히 옆으로 배치되어 있다. 서당은 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.…","a":"진주 용강서당","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663957.jpg"},{"q":"1703년(숙종 29) 계미년(癸未年)에 태어난 7명의 동갑들이 만든 동경계첩(同庚契帖)이다. 화첩을 펼치면 오른쪽 면은 비어 있고 왼쪽 면에 참판 이익진(李翼鎭, 1703~?), 판서 조영진(趙榮鎭, 1703~1775), 참판 이규채(李奎采, 1703~?), 영의정 한익모(韓翼謨, 1703~?), 부사 송진흠(宋晉欽, 1703~?), 영의정 신만(申晩, 1703~1765), 유언술(兪彦述, 1703~1773) 일곱 명의 반신 초상화가 차례로 각각 그려져 있다. 이어서 이들이 69세이던 1771년(영조 47) 10월 상순에 유언술이 쓴 서문이 4면에 걸쳐 있다. 화면…","a":"계미동경소진첩","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636539.jpg"},{"q":"형태는 저지(楮紙)에 목판본(木版本) 선장(線裝)으로 영락 8년, 즉 조선 태종 10년(1410)에 간행된 것이다. 제3권에서 제6권까지의 4권 1책으로, 반곽의 크기는 25.1cm×16.7cm이다. 내용은 두보의 시를 청강(淸江) 범덕기(范德機)가 선별하여 비평을 가한 책이다. 비록 낙질이긴 하지만 말책(末冊)이어서, 해주목사(海州牧使) 유은지(柳隱之)의 지원 하에 간행되었고 영락 8년 경인년 11월에 연안부(延安府)의 유학교수관(儒學敎授官) 송석견(宋石堅)이 발문을 썼다는 간기가 뚜렷한 데다, 기존의 여러 도서 목록에도 보이지 않는 책이므로 문화유산으로서의 가치가…","a":"양산 대성암 두공부시범덕기비선","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642397.jpg"},{"q":"‘○○○○○택’은 선조~인조 때에 영의정을 지내고 청백리로 이름 높던 오리 ○○○ 선생이 인조(仁祖)에게서 하사받은 집이다. 인조는 오랫동안 재상을 지낸 ○○○의 집이 초가인데다 비가 샌다는 사실을 알게 되었다. 이를 안타깝게 여긴 인조가 1630년(인조 8)에 새 집을 하사하면서 가옥의 이름을 ‘○○○’이라 이름 붙여 주었다. ‘○○○’은 ○○○의 청렴하고 소박한 삶을 ‘보고 느끼게 하고자 한다’는 뜻이다. ○○○은 높은 석축 위에 정면 5칸, 측면 1칸 반 규모로 건립되었다. 중앙에 2칸 대청이 있고 그 왼쪽으로 2칸의 온돌방과 오른쪽에 한 칸의 온돌방이 위치한다…","a":"오리이원익종택및관감당","c":"문화유산자료","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660142.jpg"},{"q":"○○○ 마을에 흩어져 있는 비와 부도들로, 모두 11기에 이른다. 비는 낮은 사각받침돌 위로 길쭉한 비몸을 세운 모습이며, 비의 윗변이 둥글게 다듬어져 있다. 승려의 사리를 모시고 있는 부도는 낮은 받침 위로 종모양의 탑몸돌을 올리고 있는데, 꼭대기에 꽃봉오리 모양의 머리장식을 얹은 것도 있고, 지붕돌을 올려 놓은 것들도 있다. 이 곳에는 봉암대사의 ○○도 함께 자리하고 있는데, 이 비만이 원래의 자리를 그대로 지키고 있었고, 나머지 유물들은 이 일대의 부도밭을 허물어 논밭으로 만들 때 곳곳에 흩어져 있던 것을 이곳에 옮겨놓은 것이라 한다.","a":"합천 중촌리 승탑 및 탑비","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663994.jpg"},{"q":"척화비란 조선 고종 때 병인양요, 신미양요를 승리로 이끈 흥선대원군이 서양세력을 배척하고, 이를 모든 백성에게 일깨워 주고자 전국의 중요한 곳에 세워두도록 한 것으로, 이 비도 그 중 하나이다. 비는 낮은 사각받침돌 위로 길쭉한 비몸돌을 세운 모습이다. 비문에는 ‘서양 오랑캐가 침범하는데 싸우지 아니하고 화친하자고 주장하는 것은 나라를 팔아먹는 것이니, 우리 만년자손에게 경계한다’는 강한 어투의 경고문을 적고 있다. 원래는 대변항 방파제 안쪽의 동해바다가 굽어보이는 곳에 세워두었으나, 일제시대에 항을 넓히면서 일본인에 의해 뽑혀 바다 속에 버려졌던 것을, 해방 후 다…","a":"기장척화비","c":"시도기념물","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645165.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 6년(1397)에 지은 ○○○○는 임진왜란(1592) 때까지의 내력은 자세히 알 수 없다.『산양지』에 의하면 언제인지 확실하지 않지만 구계동에서 현 위치로 옮겼다가 양청산으로 옮겼다고 전한다. 정유재란(1597) 때 불타 없어지자 선조 35년(1602)에 다시 지금의 위치로 옮겼다고 한다. 순조 32년(1832)에 고쳤으며, 그 이후에 여러 차례 수리가 있었다. 현재 남아있는 건물은 대성전·동무·서무·명륜당·동재·서재 등이 있다. 앞쪽에는 학생들이 공부하던 명륜당을 중…","a":"보성향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639952.jpg"},{"q":"가야 말로왕의 왕궁터로 전해지고 있는 고성성지는 현재 거의 남아있지 않고, ○○○○과 고성 왜성터의 일부가 남아있다. ○○○○은 『동국여지승람』의 기록을 보면 둘레 3,524척, 높이 15척이며, 우물이 14개 연못이 1곳 있다고 전하나, 성벽은 대부분 훼손되었다. 고성왜성은 정유재란 때 왜군이 남해안에 주둔하기 위해, 남해안 일대 요충지에 쌓은 성의 하나로 현재 거의 남아있지 않다. 전체적인 구조나 규모를 알기 어렵지만, 주변에 있는 송학동고분군(사적 제119호)이나 고성 동외리 조개더미, 만년사 토성과 관련있는 것으로 생각되며, 이곳에 가야 때부터 성이 있었을 가…","a":"고성읍성","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664024.jpg"},{"q":"이 불화는 ○○○○○가 단독으로 봉안된 드문 형식의 작품으로, 각 존상의 균형잡힌 신체와 단아한 얼굴, 자그마한 이목구비, 유려한 필선, 짙은 적색과 녹색의 색조 등 18세기 후반 불화의 전형적인 특징을 잘 보여주며, 화기에 의해 정확한 제작 연대와 작가를 알 수 있어 당시의 불화를 이해하는데 기준작으로서의 가치가 있다. 이 불화는 원주시 판부면 금대리 ○○○에 봉안되어 있던 것인데, 현재 월정사 성보박물관에 소장되어 있다. 그림 하단의 중앙에 화기(畵記)가 있어 1759년(乾隆 24년)에 오관(悟寬), 화운(華雲), 묘심(妙心) 등에 의해 제작되어 원주 치악산 ○○…","a":"영원사비로자나불후불탱화","c":"시도유형문화유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638241.jpg"},{"q":"충열공 이대원(1566∼1587)과 충장공 정운(1543∼1592)을 모신 사당이다. 이대원은 선조 20년(1587) 녹도만호가 되어 남해안에 출몰하는 왜구를 대파하였고, 다시 흥양에 왜구가 침입하자 맞써 싸우다가 손죽도 해상에서 순절하였다. 이에 선조는 사당을 지어 모시게 했는데 이것이 쌍충사의 전신이다. 정운은 선조 24년(1591) 녹도만호로 부임하여 임진왜란이 일어나자 이순신 장군과 함께 목포·당포·한산해전 등에서 용감히 싸우다 부산 몰운대에서 순절하였다. 선조 25년(1592) 이순신 장군의 청으로 이대원과 함께 사당에 모시게 되었다. 정유재란으로 불타 버린…","a":"고흥쌍충사","c":"시도기념물","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654288.jpg"},{"q":"○○대학교 안에 있던 ○○○ 야외에 안치되어 있던 불상으로, 광배는 없고 대좌(臺座)와 불신만이 남아있는 통일신라 후기의 전형적인 비로자나불상이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 큼직하게 표현되었다. 활모양의 눈썹, 큼직한 코, 굳게 다문 입 등은 양감있는 얼굴과 알맞게 조화되어 원만한 인상을 보여주고 있다. 두 귀는 거의 어깨까지 내려왔으며 목에는 부드러운 곡선의 3주름이 표현되었다. 옷은 양 어깨를 감싸고 있으며 옷주름은 좌우대칭의 평행선으로 약간 도식화되었다. 단정하나 활력이 없고 약간 위축된 듯한 신체의 표…","a":"청주 용암사 석조비로자나불좌상","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638431.jpg"},{"q":"1700년대에 지은 이 집은 영조 4년(1728) 이인좌의 난을 평정하는데 공을 세운 국담 주재성 이래 주씨 가문의 종가(宗家)이다. 정문인 대문과 중문, 사랑채인 감은재, 안채, 사당인 부조묘를 갖추고 있어서 종가의 면모를 보여줄 뿐 아니라 하환정, 풍욕루, 국담 등의 화려한 별당과 연못을 갖춘 대규모 주택이다. 사랑채는 국담의 장남 주도복의 서재로 문집과 책판이 보관되어 있고 대청 북쪽벽에는 초상화를 모셔 두었던 영정각이 남아 있다. 정문은 국담의 충성심에 대한 공훈과 아들 주도복의 효행에 대한 포상으로 철종 10년(1859)에 내려진 것으로 ‘충신정려’와 ‘효자…","a":"함안 무기리 주씨고가","c":"시도민속문화유산","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659047.jpg"},{"q":"경상남도 ○○시 호계동의 큰 바위에 새겨진 마애불로, 바위 밑의 동굴에는 온돌을 설치했던 흔적이 있다. 이 동굴은 원효대사가 수도했던 ‘반고굴(磻高窟)’이라고 전해지지만 아직 확실한 근거는 없다. 머리에는 마애불로는 드물게 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 작은 머리묶음이 있다. 몸에 비해 큰 얼굴, 길게 감은 눈, 큰 코, 다문 입 등은 투박한 인상을 준다. 신체는 풍화가 심해 뚜렷하지 않은데, 양 어깨에 걸친 옷이 두툼하게 선각되었고, 손·발 역시 투박하게 표현되었다. 대좌(臺座)는 연꽃이 활짝 핀 모양의 평면형을 선으로 새겼고,…","a":"양산 호계리 마애여래좌상","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641565.jpg"},{"q":"○○○의 본관은 상주(尙州)이고, 자는 형부(炯夫)이다. 1623년에 덕원부사로 있을 때 이귀(李貴)의 별장(別將)으로 인조반정에 참여하여 정사공신(靖社功臣) 3등에 녹훈되고 상원군(商原君)으로 봉해졌다. 이 초상화는 원본인 <○○○ 정사공신도상>을 옮겨 그린 이모본(移模本)이다. 초상화의 이모본을 그리는 것은 원본이 훼손되어 보존상의 문제가 생겼을 때, 새로운 봉안처가 생겨 봉안본이 필요할 경우, 그리고 만약을 대비하여 한 본을 더 그려놓는 등의 세 가지 이유 때문이다. 이 이모본은 원본에 못지않게 원본의 형태와 특색을 충실히 베껴 그렸다. ○○○은 사모에 단령을…","a":"박유명초상모본","c":"문화유산자료","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660281.jpg"},{"q":"○○○○은 전형적인 삼랑식(三廊式) 성당 건축이며 외관의 전체 구성은 단순하나, 처마돌림 띠, 창둘레 아치 장식 등의 비례가 뛰어난 근대 성당 건축물로서 1933년에 착공하여 1934년에 준공하였다. 한국인 신부에 의해 건립된 건축물로서 원형을 잘 보존하고 있어 보존가치가 매우 높으며, 일본의 건축문화를 수용·혼재하지 않고 서양의 건축문화를 직접 수용하여 토착화한 건축양식으로서 근대건축사 연구의 중요자료이다.","a":"예산성당","c":"시도기념물","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653161.jpg"},{"q":"진주 류씨 안간공파 18대손인 희택과 그 아들 전, 손자 경종의 무덤에서 출토된 일괄 유물이다. 1959년 후손이 안양에서 은산면 가곡리로 이장할 당시 나온 것을 후손이 보관하고 있다가, 1985년 3월에 부여박물관에 위탁 보관하게 되었다. 부장된 유물에는 더 많은 것이 있었을 것이나 남은 것은 명기 3벌 88점, 관복 1벌, 도포 2벌, 골제 빗 1점, 백자제기 13점만 남아 있다.","a":"유경종묘내의유물","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661093.jpg"},{"q":"조피골(조피)로 불리는 곳에 자를 덕원(德원). 호를 둔재라고도 하고. 종6품인 충무위부사과 (충무위부사과)를 역임하였고 중직으로는 정2품인 통훈대부 사복시정(通訓大夫 司僕시正)에 제수된 바 있는 취수당 오연 (오연 1598~1669) 선생이 1650년경에 건립한 정면 3칸 측면2칸 규모에 팔작지붕의 중층루각형 정자이다. 취수당 오연 선생은 임진왜란 때의 공훈으로 임진선무원종공신 (壬辰宣武原從功臣)에 선정된 문월당(問月堂)오극성(吳克成 1559~1617)의 셋째 아들로 태어나 병자호란 때에는 쌍령전투(雙嶺戰鬪)에 참전하여 전공을 세웠고 조선 인주가 청나라 태종에게 남…","a":"영양취수당","c":"시도유형문화유산","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641085.jpg"},{"q":"○○○은 중종반정(中宗反正)때 정국공신(靖國功臣)인 성산군 이식(星山君 李軾)의 유업이 깃든 정자이다. 이식은 벽진인(碧珍人)으로 자(字)는 자담(子膽), 호는 동파(東坡)인데, 무과에 급제하여 사복시부정(司僕시副正), 만도첨사 등을 역임하였으나 반정이후 권신(權臣)들이 중종의 비(妃) 신씨(愼氏)를 폐출하자 정쟁(政爭)을 피해 사패지(賜牌地)인 이곳으로 내려와 주변의 절경과 풍치를 벗삼으며 유유자적하는 삶을 누렸다. 이식의 아들인 판관공 이덕창(判官公 李德昌)이 선고(先考)의 뜻을 기리고자 1545년에 정자를 창건하였으며, 수차례의 보수를 거쳐 1806년에 중건하고…","a":"밀양 곡강정","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666477.jpg"},{"q":"○○○○ 수은공파의 족보를 간행하기 위한 목판이다. 1711년에 발간한 『신묘보(辛卯譜)』의 목판을 비롯하여 모두 314판이 남아 있다. 남아있는 보판은 『신묘보』 79판, 『무인보(戊寅譜)』45판, 『정사보(丁巳譜)』 142판, 『수은실기(樹隱實記)』 30판, 『신묘보』 서(序) 8판, 『무인보(戊寅譜)』 서(序) 10판 등이다.","a":"경주김씨보판각","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639640.jpg"},{"q":"○○○는 청동기 시대 사람들이 만든 무덤으로 고인돌이라고도 한다. 무덤으로 보지 않고 제사를 지내는 제단으로 보는 견해도 있다. ○○○는 생김새에 따라 땅 위에 책상처럼 세우는 탁자식과 큰 돌을 조그만 받침돌로 고이거나 받침돌 없이 평평한 돌을 얹는 바둑판식으로 나뉜다. 우리나라는 세계에서 ○○○가 가장 많이 남아 있어 2000년에 인천광역시 강화군의 ○○○, 전북특별자치도 고창의 ○○○, 전라남도 화순의 ○○○ 등 3개 지역의 ○○○군이 함께 유네스코 세계 문화유산으로 등재되었다. 연천 ○○○○○는 고포리마을 동쪽 끝자락의 낮은 구릉사면에 위치한다. 탁자식에 해당하…","a":"연천통현리지석묘","c":"문화유산자료","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660013.jpg"},{"q":"지금까지 전국에서 발견된 ○○은 일시적인 것만 남아 있는데 ○○○○○은 임란 직후부터 일제시대나 해방 이후까지 수백 년○○네 걸쳐 많은 양의 ○○이 잘 보존되어 있다. 이러한 점은 우리나라에서도 사례가 많지 않은 경우에 속한다. 이에 ○○○○○을 통해서 조선시대 중기이후 ○○지역의 자율적인 향약시행의 전통이 어느 곳보다 강했다고 할 수 있는 소중한 자료이므로 문화유산으로 지정하여 보존할 가치가 있다.","a":"의령 화양리 동안","c":"시도유형문화유산","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642458.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659188.jpg"},{"q":"1938년경 세운 2층 양옥 형태의 집이다. 개화기 때 상류층 ○○으로서 질 좋은 부재를 사용하였다. 벽체는 돌을 벽돌식으로 모양을 내어 쌓았고 지붕은 프랑스 기와를 이용한 것이라고 하는데 뾰족지붕이다. 출입문은 윗부분을 무지개 모양의 아치형으로 꾸몄고, 건물 여러 군데에 격자무늬 창을 냈다. 60여년의 세월이 지났어도 현대 건축물에 뒤지지 않는 세련미를 보이고 있다.","a":"가회동 이준구 가옥","c":"문화유산자료","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659296.jpg"},{"q":"○○는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○ 가마는 조선시대의 기와가마로 남북 12m, 폭 1.8m의 작은 굴가마이다. 1582년 설립된 팔봉서원에 소속된 기와가마로서 서원의 건립과 낡거나 부서진 곳을 고치기 위하여 생겨난 것으로 보인다. 이곳에서는 조선시대에 가장 흔하게 나타나는 파도무늬가 찍히고 두께가 비교적 두꺼운 기와가 출토되었다. 이는 수화(水火)사상에서 연유한 것으로 나무로 만들어진 건물은 불에 약하므로 파도무늬를 찍어 불기운을 물기운으로 누른다는 생각에서 였던 것으로 보인다.","a":"충주 문주리 요지","c":"시도기념물","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650086.jpg"},{"q":"조선시대 홍성지방 관리들이 업무를 처리하던 곳이다. 행정업무를 처리하던 동헌과 치안업무를 처리하던 형방청, 책과 문서를 보관하면서 관리의 자제가 지내던 책실로 구성되어 있다. 동헌은 고려말에 결성면 금곡리 분우터에 있다가 정종 2년(1400)에 결성읍 산성 정상으로 옮겼다．현종 6년(1665) 현재의 위치인 읍내리에 다시 지었고, 이후 여러 차례 고쳐 지었다. 동헌은 앞면 5칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 형방청은 ㄱ자 모양을 하고 있으며, 책실은 앞면 2칸·옆면 1칸 반 크기로, 지붕은 앞에서 볼 때 사다리꼴인…","a":"결성동헌","c":"문화유산자료","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661387.jpg"},{"q":"조선 초기 왕실(王室)에서 간행한 책으로 부모의 은혜가 한없이 크고 중요하다는 것을 설파한 불교경전으로, 『○○○○○』이라고도 한다. 유교의『효경(孝經)』과 달리 특히 어머니의 은혜가 얼마나 큰가를 구체적으로 설명하고 있는 이 책은 산스크리트원본이 발견되지 않았으며, 그 내용도 중국의 전통적인 효사상(孝思想)을 그대로 이어받아 강조하고 있는 점으로 미루어볼 때 중국에서 지은 위경(僞經)으로 보인다. 그렇지만 오히려 이러한 점에서 효를 중요시하는 한국·중국·일본에서 매우 널리 유통되었으며, 다수의 변상도(變相圖)가 제작되기도 했다. 이 책의 간행기록에 의하면 명종17년…","a":"불설대보부모은중경","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638892.jpg"},{"q":"최치원이 임금에게 글을 올리던 장소이다. 최치원은 통일신라 후기의 학자로, 12세 되던 경문왕 8년(868)에 당나라로 유학하여 18세에 과거급제 한 후 벼슬길에 올랐다. 헌강왕 11년(885)에 귀국하여 진성여왕에게 시무10조(時務十條)를 올리는 등, 어지러운 국정을 바로잡기 위해 노력하였으며, 노년에는 가야산, 지리산 등 명산에 은둔하며 지내다가 가야산 해인사에서 생을 마쳤다. 뛰어난 문장가이기도 한 그는 많은 저서와 비문을 남겼는데, 특히 난랑비서문(鸞郞碑序文)은 신라화랑도를 설명해 주는 귀중한 자료가 되고 있다. 이곳에는 영정각, ○○○, 추모문 등이 건립되어…","a":"상서장","c":"시도기념물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654466.jpg"},{"q":"김유신·최치원의 영정과 홍유후·설총·문창후의 위패를 모시고 있는 서원이다. 680년경에 지었고 1919년 지방유림들이 다시 지었으며, 경주 서○○○의 이름을 본따 ○○○○이라고 이름지었다. 경내에는 사당, 서원 2동의 재, 솟을대문이 있다. 사당은 앞면 3칸·옆면 1칸의 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 서원은 앞면 4칸·옆면 2칸 규모에 지붕은 팔작지붕이고, 대청이 없이 툇마루가 확장되어 대청의 기능을 한다. 서원 좌우에 마주보고 있는 재는 각각 앞면 4칸·옆면 2칸 규모이다.","a":"진주 남악서원","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663802.jpg"},{"q":"정충각은 임진왜란 때 풍천(豊川) 구담(九潭)에서 의병 700여명을 이끌고 왜군을 방어하다가 전사한 농은(農隱) 이홍인(李洪仁, 1525­1594)에게 내려진 정려(旌閭)를 게시한 건물로 1811년(순조 11)에 건립되었다. ○○○은 이홍인의 8대손인 용눌재(?訥齋) 이한오(李漢伍, 1719­1793)의 효행에대해 내려진 정려를 게시한 건물로 1812년(순조 12)에 건립되었다. 이한오는 전통적인 유가의 후예로서 충과 효가 생활의 기본임을 깨닫고, 오직 효성으로 부모님을 봉양하여 주변의 칭송이 자자하였던 분이다. 각 정면 1칸, 측면 1칸의 겹처마 맞배지붕의 건물로…","a":"예안이씨정충·정효각","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663478.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리, 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 별도 ○○○○은 화북동 ○○○○ 1지점에서 동남쪽으로 약 40m 떨어진 곳에 자리잡고 있다. 안벽과 바깥벽을 갖춘 2중성으로, 주변의 크고 작은 돌을 이용하여 벽을 쌓았다. 현재 남아있는 성벽의 길이는 약 640m 정도이다.","a":"별도환해장성","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657906.jpg"},{"q":"○○○는 신라 법흥왕(재위 514∼540) 때 유일이 세운 절로 지었을 당시의 설화에 의하면 현재의 칠성면 근처에 자리를 잡고 공사를 시작했는데, 갑자기 까마귀 떼가 나타나서 대패밥과 나무 부스러기를 물고 날아가 작은 연못에 떨어뜨렸다고 한다. 유일이 물 속을 들여다보니 불상 하나가 있었음으로 깨달음을 얻어 못을 메우고 절을 지어서 ○○○라 하였다 한다. 고려 전기에 통일이 다시 지었으며, 혜종(재위 943∼945) 때 수리하였다. 그 뒤 여러 차례의 수리를 거쳐 오늘에 이르고 있다. ○○○○○은 석가모니를 모시는 법당으로 절의 중앙에 위치한다. 네모난 돌로 쌓은 기…","a":"괴산 각연사 대웅전","c":"시도유형문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638589.jpg"},{"q":"○○○에 소장되어 있는 나무로 만든 ○○○○○인데, 불·보살의 명칭을 적어 불단에 봉안하던 불명패(佛名牌)로 일종의 위목대(位目臺)이다. 주연(周緣)이 능화형(菱花形)으로 된 몸체 부분을 연꽃무늬 대좌에 결구한 방식과 크기 등이 ○○○○○시방삼보자존패(부산광역시 문화유산자료)와 거의 비슷하다. 다만 좌·우 주연에는 구름·용무늬가 조각되어 있으며, 액(額)에는 금가루로 쓴 ‘○○○○○’라는 발원명이 있고, 대좌가 엎어놓은 연꽃무늬 10잎이 새겨져 있는 아랫받침돌과 위로 향한 연꽃무늬 10잎이 새겨져 있는 윗받침돌로 구성되어 있는 점 등에서 약간의 차이가 날 뿐이다. ○…","a":"범어사목조석가여래위패","c":"문화유산자료","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659369.jpg"},{"q":"이 판목은 조선 후기의 학자인 진계 박재형 선생이 고종 21년(1884)에 간행한 것으로, 128매가 있다. 구성을 보면 우리나라 선인들의 격언과 언행을 내외편으로 분류하여 내편은 입교로 가르치는 도리를 세운 내용 21장, 명륜으로 인륜을 밝힌 내용 43장, 교신으로 몸가짐을 삼가라는 내용 35장, 계고로서 옛일을 공부하여 고찰하는 내용 64장으로 이루어져 있다. 외편은 가언으로 아름다운 말들을 담은 내용 74장, 선행사열 등 174장이 실려 있다. 이들 내용은 생활 속에서 실천을 교육목표로 한 입문교과서라 할 수 있다. 당시 모화사상이 깊게 뿌리내리고 있었던 시기에…","a":"해동속소학판목","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640702.jpg"},{"q":"조선 말 감역(監役)을 지낸 이 마을 출신의 학자 만취(晩翠) 심원표(沈遠杓:1853~1939)의 학덕을 기리기 위해 1913년에 지은 정자이다. 심원표는 한말에 감역관(監役官)을 지내기도 했고, 일본이 주는 은사금(恩賜金)을 거부하고 고향에 은둔해 강학과 효도로써 한 평생을 마쳤다. 정면 처마 끝에는 해강 김규진과 석촌 윤용구가 쓴 ○○○ 편액 2개가 걸려 있다. 또 정자 안에는 \"나의 씨족인 심씨의 본관이 청송(靑松)으로 되어 있고 또 솔(松)이라는 나무가 언제나 울창하여 겨울 추위에도 그의 푸름을 잃지 않는 높은 절개를 갖고 잇다. 이 정자를 남쪽에 지어 '만취…","a":"만취정","c":"문화유산자료","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659683.jpg"},{"q":"불법을 수호하는 역할을 맡은 여러 신들을 그려 정법(正法)과 도량의 수호를 담아낸 것을 통틀어 ○○○라고 부른다. 울산 ○○○○○는 대웅전 오른쪽 측면에 봉안되어 있으며 가로 105cm, 세로106.5cm 크기로 한 폭의 면 바탕 위에 그려진 채색화이다. 화면의 왼쪽에는 보관을 쓰고 연꽃을 들고 있는 제석천(帝釋天)을 금강권보살(金剛眷菩薩)과 일궁천자(日宮天子)가 왼쪽에서, 금강삭보살(金剛索菩薩)과 월궁천자(月宮天子)가 오른쪽에서 시립하고 있으며, 화면의 오른쪽에는 긴 창을 들고 있는 동진보살(童眞菩薩)을 주조신(主鋤神), 주산신(主山神), 호계대신(護戒大神), 복덕…","a":"울산인성암신중도","c":"시도유형문화유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637283.jpg"},{"q":"○○○은 1624년 임진왜란 때 의병장인 사우당(四友堂) 김대진(金大振) 선생이 경상감사 이민구와 지역 사림의 협조로 건립하였으나 1721년 소실된 것을 1866년 그의 후손 김규한이 중건한 건물이다. 이 건물은 정면 5칸, 측면 1칸의 일자형 건물로 지붕은 옆면에서 볼 때 팔작지붕이다. 가운데 대청을 중심으로 오른쪽에는 1칸의 온돌방을, 왼쪽에는 2칸의 온돌방을 배치하였다. ○○○은 주위 자연환경과 잘 조화되고 건물 각부의 비례구성이 단정하고 안정감을 느끼게 하며 치목수법 및 결구상태가 치밀하고 원형을 잘 보존하여 조선후기 정자건축의 흐름을 잘 표현하는 중요한 가치…","a":"관수정","c":"문화유산자료","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659497.jpg"},{"q":"전라남도 광양시 옥룡면 운평리 ○○○에 있는 보살상으로, 왼발을 올리고 오른발을 내린 ○○○이다. 두건을 쓰고 있어서 ○○○○을 표현한 것으로 간주되기도 한다. 이런 모습은 조선초까지 더러 보이는데 전라남도 강진 무위사의 아미타불상협시○○○○상이 그 대표적인 예이다. 얼굴은 네모 반듯한 모습에서 형식화가 엿보이지만 풍만하고, 체구도 다소 둔중하지만 친근함이 느껴진다. 옷은 스님들이 입던 장삼(長衫)을 걸치고 있어 독특한 모습이다. 대좌(臺座)는 맨 밑에만 보이는데 겹겹으로 된 연꽃무늬를 새겼고 발받침대도 있다. 두건을 쓰고 장삼을 입은 스님 모습의 이 ○○○○은 친밀…","a":"중흥사석조지장보살반가상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640018.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659170.jpg"},{"q":"○○○은 조선시대 구산포에서 울릉도로 가던 수토사들이 순풍을 기다리며 머물렀던 건물이다. 이 건물의 정확한 건립연대는 확인할 수 없으나 구산동사 중수기에 의하면 1851년(철종 2년) 중수하고 ○○○이란 현판을 걸었다는 기록이 남아있다. 이 건물은 정면(남쪽) 4칸, 우측면(서쪽) 4칸, 좌측면(동쪽) 3칸의 일자형 팔작집으로 동해안 해변의 작은 포구 구산리 마을 중심부에 남향으로 자리 잡고 있으며, 현재 마을 주민들의 집회장으로 이용되고 있다. ○○○은 조선시대 동해안 구산포에서 울릉도로 가는 수토사(搜討使)들이 순풍(順風)을 기다리며 머물렀던 건물로 평면구성이나…","a":"울진 대풍헌","c":"시도기념물","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654713.jpg"},{"q":"○○○의 중앙교당으로 종교의식과 일반행사를 하는 곳이다. ○○○ 3대 교주였던 손병희의 주관으로 1918년에 공사가 시작되어 1921년에 완공되었다. 교인들로부터 성금을 모아 공사비로 충당하였는데, 공사비에서 남은 돈은 3·1운동 자금으로 사용하였다. 건물의 기초부는 화강석을 사용하고 벽은 붉은 벽돌을 사용하여 쌓았다. 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집인데, 철근 앵글로 중간에 기둥이 없게 하였다. 또한 앞면에 2층 사무실을 탑 모양의 바로크풍으로 하여 특이한 모습을 보이고 있다. 당시에는 서울시내 3대 건물의 하나로 꼽혔으며, 교회당의 구조와 비슷하면서…","a":"천도교 중앙대교당","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636118.jpg"},{"q":"‘○○○’은 삼국 시대에 처음 쌓은 것으로 추정되는 안성 백운산 무양산성(舞陽山城)에 있는 암자이다. 암자는 여러 개의 불전(부처와 보살을 모시고 기도하는 장소)과 요사(승려가 머물며 생화하고 수행하는 장소)가 세워지는 일반 사찰과는 달리 적은 인원이 수행을 목적으로 불전과 요사를 하나의 건물로 짓고 생활하는 곳이다. 전하는 이야기에 의하면 1750년에 과부가 된 장반야명(張般若明;장은 성씨이고, 반야명은 사찰에서 따로 지은 이름인 법명이다) 부인이 평생 부처님을 모시고 살아갈 것을 결심하고 무한성 밑에다 터를 닦았는데, 꿈에 노승이 나타나 성안에 지으라고 하여 여기…","a":"운수암","c":"문화유산자료","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659933.jpg"},{"q":"조선후기에 가면 각 마을마다 자제들을 교육하기 위한 서당, 강학당을 건립해 나가는 것이 일반적인 추세였다. ○○○도 이 범주에 속하는 문중자제들을 위한 강학당이다. 역사적인측면에서 ○○○는 옥산에 약 450여년간 세거해온 여강이씨의 대표적인 강학당(講學堂)이라는 점에서 역사성을 부여할 수 있다. 인근 양동마을의 대표적인 서당인 강학당(講學堂,국가민속문화유산, 1870년 건립), 안락정(安樂亭,국가민속문화유산, 1780년 건립) 보다 건립시기가 이르고 한국전쟁 이후까지도 26세손인 이지하(李志厦)에 의해 강학기능이 유지되었다는 점을 고려해 볼 때 문화유산으로 지정하여…","a":"경주 귀후재","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051422400601.JPG"},{"q":"나주 ○○○○○은 본존불인 건칠불의 좌우 협시불로 15세기 초에 조성된 것으로 추정되어 조성의 연대도 빠르고 조형성도 뛰어난 편이며 고려·조선 전기를 걸쳐 오면서 조상되는 조각사적 흐름을 엿볼 수 있어 역사적, 예술적 가치가 있다.","a":"나주불회사소조보살입상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051719163500.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 이 고인돌은 동강면의 남쪽 언덕 정상부에 약 60여 기, 주위 평지에 약 180여 기가 놓여 있어 청동기시대 이 지역에 대규모의 생활공간이 형성되었을 것으로 짐작된다. 고인돌은 덮개돌이 땅에 있는 것도 많지만 일부는 받침돌이 놓여 있고,…","a":"고흥유둔리덕암지석묘군","c":"시도기념물","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654314.jpg"},{"q":"신라 혜공왕 때 진표율사가 화암사(華巖寺)라는 이름으로 세운 절이다. 조선 인조 1년(1623)에 소실되었다가 인조 3년(1625)에 고쳐 짓는 등 여러 차례 소실과 재건을 반복하였다. 고종 1년(1864)에는 지금 있는 자리인 수바위 밑에 옮겨 짓고 이름도 수암사(穗岩寺)라 하였다가 1912년에 다시 화암사(禾岩寺)로 이름을 바꾸었다. 한국전쟁 때 다시 한 번 불에 타 훗날 법당만 다시 지었다. 1991년 세계 잼버리대회 준비를 위해 기존 건물을 철거하고 새로 지어 오늘에 이르고 있다. 현존하는 건물로는 일주문, 대웅전, 삼성각, 명부전, 요사채 등이 있으며, 조선…","a":"고성화암사","c":"문화유산자료","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660545.jpg"},{"q":"조선 중기의 문신이자 임진왜란 때 의병을 일으켜 뛰어난 공적을 세운 농포(農圃) ○○○ 장군의 묘이다. 묘역은 부인 고령 신씨(高靈申氏)와 합장한 하나의 봉분 형태다. 묘제(墓制)는 후대에 정비를 하였지만 대체로 원형이고, 석물은 옛 것 그대로이다. 봉분 앞에 묘표(墓表 ; 무덤 주인공의 이름 등을 새긴 비석)를 1기 세웠으며, 그 앞으로 혼유석, 상석, 향로석을 차례로 조성하였다. 묘표는 일반적인 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)인데, 앞면의 글씨가 웅장하고 강건하여 주목된다. 이는 한호(韓濩)의 대자집자비(大字集字碑)로, 뒷면의 기록…","a":"정문부장군묘","c":"시도기념물","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646043.jpg"},{"q":"제주도 기와집의 특징은 바람세기 때문에 기와가 특히 크며 처마끝과 용마루 주변에는 회땜질을 해서 특이한 경관을 형성했다. 지분의 물매는 초가집처럼 뜨며 안허리를 두거나 추녀를 치켜들지 않는다. 초가집에 비교하면 지분이 무거워서 부재가 굵고 단단한 나무를 사용하며 고급스럽게 치장하지만 평면의 간살이는 별로 다르지 않다.","a":"조천리 황씨 종손 가옥","c":"시도민속문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659223.jpg"},{"q":"○○○는 신라 진덕여왕때 원효대사가 안거하며 수도 정진해 붙여진 이름이다. 조선 인조 4년(1626년)에 한글로 필사된 ○○○○○은 2책 1권으로 만들어 졌는데. 글씨가 모범적이고 바르며 보존상태도 양호한 상태로 17세기초 유교적 규범이 엄격한 궁중상궁에 의해 작성한 공덕경이란점에서 귀중한 자료일 뿐 아니라 한글 표음법 연구에도 중요한 자료로 평가받고 있다","a":"의정부원효사묘법연화경","c":"시도유형문화유산","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637760.jpg"},{"q":"1917년에 세워진 살림집으로 안채와 사랑채, 행랑채보다 지붕을 한단 높여 만든 솟을대문이 남아 있다. ㅡ자형 평면의 안채는 자연석으로 쌓은 기단 위에 사각형의 주춧돌을 놓고 네모기둥을 세웠다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 화려하다. 지붕 끝부분 기와에 ‘조선개국오백이십오년병진월십일수부귀남자’라고 새긴 글이 있어 건물의 연대를 알 수 있다. 지붕 네 귀퉁이의 끝에 있는 기와에는 태극의 4괘무늬를 새겨놓았다. 건물이 세워진 연도는 오래되지 않았지만 전통적 건축의 형태를 잘 간직하고 있다.","a":"영동 가곡리 고가","c":"시도유형문화유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638622.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659174.jpg"},{"q":"조선 광해군 5년(1613) 애송당 문익현이 지어 14대째 내려오고 있다. 현 소유자인 ○○○의 5대조 문병호가 고쳐 지었으며, 1968년에는 문간채를 새로 지었다. 건물은 안채, 사랑채, 문간채 등으로 구성되어 있다. 안채와 사랑채는 앞면 5칸 규모에 앞뒤로 툇마루를 두었다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 문간채는 앞면 3칸 규모이며 문은 솟을대문 형식으로 꾸몄다. 350년 이상된 건물로 일부 수리가 있었지만, 대체로 원형을 잘 보존한 이 지방 전통 가옥이다.","a":"영암문창집가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662119.jpg"},{"q":"○○○○ 재사(齋舍)는 괴정 남준형의 묘소를 관리하고자 1780년대에 건립한 것으로 전해지며, 괴정공의 증손인 회수(華壽, 號 明厓,1781~1851) 대에 중수한 건물이다. 건물은 一자형으로 겹집형태의 구조를 취하고 있으며 평면은 전렬은 좌측으로부터 방, 2칸마루, 부엌으로 되어 있고, 후렬은 방, 방(도장), 방, 부엌으로 구성되어 있다. 자연석 주초위에 각주를 세웠으며, 상부가구는 납도리에 3평주 5량가로 맞보를 올렸다. 천정은 고미반자로 마감하고 그 위 상부는 노출시켰으나, 부엌과 전면 우측 마루부분의 천정은 앙벽을 치지 않고 산자를 노출시킨 상태로 있다.","a":"영덕괴시리스므나골재사","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663503.jpg"},{"q":"고성 ○○○의 집으로 19세기 중엽에 지은 것으로 추정한다. 이 마을은 강릉 최씨와 함씨의 집성촌으로 소유자인 ○○○은 21대째 이곳에서 살고 있다. 앞면 4칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 평면은 앞면에 2칸 마루가 있고 그 뒤에 안방을 두었으며 옆면에 사랑방과 고방이 있는 영동 북부지방의 전형적인 모습이다. 본채 오른쪽에 있는 사랑채는 사랑방 옆면에 아궁이가 있다. 또한 고방과 사랑방 사이의 벽을 바깥쪽으로 연결한 후 지붕을 덧달아 헛간으로 사용하고 있다. 본채는 ㄱ자형을 이루고 있는 가옥으로 뒤쪽에 툇마루가…","a":"고성함정균고택","c":"문화유산자료","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660477.jpg"},{"q":"이 정려는 ○○○○○의 대표를 표창하라는 왕명으로 세워진 \"○○조봉대부형조정랑 겸 춘추관 기주관 ○○○ 려\"이다. 본시 태생지인 창원 지개동에 세워졌는데(1592)임란에 소실되어 이곳으로 이건 하였다(1634년) 공은 일찍 토계의 문도가 되어 경학을 강마하였으며 사마시에 합격하고 중시에 장원급제하여 형조정량으로 승천되었다. 천상을 당해 상례가 어김 없었고 모친을 지효로 섬기니 향리는 물론 ○○, 창원, 영천의 사림이 감복하여 순찰사가 그 효행을 나라에 장개하였다. 모상을 당하여는 려묘살이를 통한 과애러 거의 죽게되니 한강, 율곡, 고봉 등 재현들이 글로서 타이르고 선…","a":"밀양 조광익 효자 정려각","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665178.jpg"},{"q":"○○○○○는 고려말 황윤보(黃允寶)에 의해 건립되어 여말선초 회덕황씨가의 적선(積善)에 의해 운영된 역사 깊은 생활유적으로, ○ 행려자(行旅者)들을 대상으로 한 구호활동에서 점차 사회구조 및 봉사활동으로 확대한 대전 최초의 사회복지 기능을 수행한 민간기관임 ○ 또한 이색(李穡)과 하륜(河崙), 변계량(卞季良), 정인지(鄭麟趾), 송시열(宋時烈) 등 당시에 정치·학문·문학으로 손꼽히는 인물들이 찬한 제영기(題詠記)에서 그 위상을 짐작할 수 있으며, ○ 청풍명월(淸風明月), 절의정신(節義精神)과 더불어 우리 지방의 향풍(鄕風) 가운데 하나인 남에게 베풀기를 좋아하는 대전…","a":"미륵원지","c":"시도기념물","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645842.jpg"},{"q":"경상남도 ○○시 삼량진읍 검세리는 예로부터 영남지방의 동·서와 남북의 중요한 교통의 요지로, ○○○이 있던 곳이다. 이곳은 여행하는 관원의 숙박소 기능과 왜적을 공격에 방어하는 기능, 작원진이라는 나루터로 출입하는 사람들과 화물을 검문하는 기능을 하였다. 즉 원(院), 관(關), 진(津)의 역할을 겸한 곳이었으며, 현재는 그 터만이 남아있다. 임진왜란 때는 ○○부사 박진 장군이 몰려오는 왜적을 맞아 결사적으로 항전을 펼친 곳으로도 유명하다.","a":"밀양 작원관지","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663975.jpg"},{"q":"조선 명종 때의 문신인 희중 민제인(1493∼1549) 선생의 시문집을 새긴 목판이다. 민제인은 중종 15년(1520) 문과에 급제하여 승정원주서, 사간원정언, 사헌부대사헌, 형조참판 등의 벼슬을 지냈다. 을사사화를 주도하여 윤임 등을 제거하는데 앞장섰으며, 1547년 좌찬성에 오른 후에는 민심을 안정시키는데 노력하였다. 1548년 윤원형 등이 을사사화를 감추고자 당시 관련 기록을 쓰고 있던 안명세를 죽이고 기록을 고치려 하자 이의 불가함을 고했고, 결국 그들의 미움을 사 공주로 귀양을 갔다. 그는 그 곳에서 을사사화에 참여하여 많은 선비를 죽인 것을 후회하다 목숨을…","a":"민입암집판각","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661499.jpg"},{"q":"개암 ○○의 문집을 널리 간행하기 위해 만든 책판이다. ○○은 남명 조식의 문인으로, 명종 4년(1549)에 진사를 지냈으며, 명종 21년(1566)에 정여창의 신원을 회복하기 위해 상소를 올렸다. 평생 학문과 후진양성을 위해 노력하였으며, 남계서원에 봉향되어 있다. 이것은 상하 1책으로 되어 있는데, 상권에는 시(詩)·서(書)·기(記)·추록(追錄)이 있고, 하권에는 세계(世系)·연보(年譜)·행장(行狀)·제문 (祭文) 등이 수록되어 있다. 서문은 숙종 32년(1706)에 정지윤이 썼으나, 간행 기록으로 보아 간행은 이미 숙종 12년(1686)에 이루어졌음을 알 수 있…","a":"강익 개암문집 목판","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641769.jpg"},{"q":"○○○는 고려말에 소윤(少尹)을 역임한 만은(晩隱) 홍재(洪載)의 불사이군(不事二君)의 절개를 지키기 위해 개성에서 남하하여 은둔한 곳이라고 한다. 만은(晩隱) 홍재(洪載)에 대한 가장 오래된 기록은 1709년의 풍산홍씨족보(豊山洪氏族譜)에서의 기록이다. 여기에는 홍재(洪載)가 문과에 급제하여 좌산기(左散騎) 직제학(直提學)을 역임한 홍보(洪保)의 아들로 되어 있고, 자신은 문과에 급제하여 소윤(少尹)·군사(郡事)를 역임한 것으로 되어 있다. 그 다음으로 보이는 기록은 좌의정 맹사성(孟思誠:1360-1438)이 1424년 4월에 찬 술했다는 행록(行錄)이 있다. 17…","a":"합천 운구대","c":"시도기념물","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657443.jpg"},{"q":"○○○ 마을 안에 자리하고 있는 탑으로, 널찍하게 마련한 돌단 위에 놓여 있다. 몇년 전까지 주변에서 기와조각이 발견되었고, 인근 민가 앞에서 작은 석불(石佛)이 발견되어 이곳이 절터였음을 말해주고 있다. 대체로 파손이 심하지 않은 이 탑은 기단(基壇)을 1층으로 쌓고, 그 위로 5층의 탑신(塔身)을 올린 모습이다. 기단은 윗돌을 괴어두는 부분에 2단의 높직한 괴임을 두었다. 탑신의 각 지붕돌은 밑면에 4단씩의 받침을 새겼으며, 직선을 그리던 처마는 양쪽 끝에서 느리게 위로 들려있다. 꼭대기에는 네모난 받침돌 위로 높직한 머리장식을 얹어 마무리하였다. 위로 올라갈수록…","a":"남문리오층석탑","c":"문화유산자료","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661246.jpg"},{"q":"대전광역시 중구 대사동 보문산(해발 406m) 정상 부분의 산세를 이용하여 쌓은 성으로, 둘레는 300m이다. 성벽은 자연지형에 따라 간단하게 다듬은 네모난 돌을 이용하여 쌓았으며, 성벽 바깥면은 조금씩 안쪽으로 둘러쌓아 쉽게 무너지지 않도록 하였다. 암반으로 형성된 동쪽과 북쪽의 급경사면에는 별도로 성벽을 쌓지 않았다. 발굴조사 결과 남문터가 확인되었고, 현재 통행로로 사용되는 북문을 통해 고려시대에는 성문폭을 좁혀서 사용한 것을 알 수 있다. 동쪽 성벽 아래에서는 청동기시대 후기의 주거지 유적과 민무늬토기, 덧띠무늬토기 등이 발견되었다. 이 성은 백제 말에 신라와…","a":"보문산성","c":"시도기념물","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645787.jpg"},{"q":"조선 중기의 학자인 곤재 정개청(1529∼1590)의 문집을 널리 간행하기 위해 숙종 15년(1689)에 왕의 특명으로 시작되어 숙종 18년(1692)에 완성된 목판이다. 정개청은 어린 시절 보성의 영주산사에서 성리학을 비롯하여 천문, 지리, 의약 등의 학문을 열심히 익혔다. 그후 서경덕을 스승으로 박순과 교류하며 학문의 깊이를 더하였으며, 명종 20년(1565)에 함평군 엄다면 제동 마을로 귀향하여 향리에서 학생들을 양성하였다. 그후 선조 22년(1589) 정여립의 모반사건에 연루되어 20여년간 이곳에서 유배생활을 하였다. 그의 저서로는『○○○』3권과『수수기』9권…","a":"곤재우득록목판","c":"시도유형문화유산","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640027.jpg"},{"q":"인도의 승려인 지공선사의 설법을 실은 1책의 목판본이다. 간행기록에 의하면 성종 6년(1475) 전라도 백운산 백운암에서 책을 거듭 간행한 것이다. 이 책의 전반부는 석가모니와 가섭존자 이하 여러 존자(尊者:학덕이 높은 불타의 제자의 경칭)들의 게송(偈頌:외우기 쉽게 게구로 지어 부처의 공덕을 찬미하는 노래)과 지공선사 자신의 게송을 실었고, 이어 송선봉과 달마대사 행론을 붙여 두었다. 후반부에는 지공선사의 설법을 게송을 첨부한 문답의 형식으로 싣고 있다. 이 책은 지금까지 잘 알려지지 않았던 책으로, 고려 후기 원나라 불교와의 교섭 양상을 이해하는데 중요한 자료로…","a":"범어사 지공직지","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636666.jpg"},{"q":"현재 ○○○ 대웅전 뒤편에 소재한 영산전에 봉안되어 있는 목조석가불좌상과 목조가섭존자와 아난존자입상의 좌우 협시상이 삼존을 구성하고 있으며, 삼존상의 좌우에는 십육나한상이 봉안되어 있다. 본존석가상은 불신 좌우, 앞, 뒤로 양감이 느껴지는 체구로 무릎 폭은 체구에 비해 좁은 편이다. 세부를 살펴보면, 머리와 육계의 경계가 뚜렷하지 않아 마치 투구를 쓴 것처럼 두부가 둥글게 표현되었고, 그 정상에는 정상계주를, 두부의 전면중앙에는 반원형의 중간계주가 새겨져 있으며 머리위에는 나발이 촘촘하다. 얼굴은 방형에 가까운 둥근 상호에 이마의 선이 수평하고 이목구비는 다소 평면적…","a":"봉은사 목 삼존불상(석가불, 가섭존자, 아난존자)","c":"시도유형문화유산","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636412.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 기록하여 후세에 전하고자 그의 묘 남동쪽에 세워두는 비로, 이비는 조선시대 중기의 문신이자 시조 작가인 농암 이현보(1467∼1555) 선생을 기리고 있다. 농암은 연산군 4년(1498) 32세의 나이로 과거에 급제하여 벼슬길에 올랐다. 38세 때 사간원정언이 되었으나 서연관의 잘못됨을 지적하다 안동에 유배되어, 중종반정 이후 다시 복직되었다. 56세 때에는 성주목사가 되어 민심을 잘 다스려 표창을 받기도 하였다. 76세 때에는 지중추부사에 임명되었으나 병을 핑계로 관직을 그만두고 고향에 돌아와 시를 지으며 남은 생을 보내었다.…","a":"농암신도비","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662473.jpg"},{"q":"이 영정은 능암당 ○○선사의 좌안 8분면 바닥가부좌상으로, 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 등받이의자를 배치하고 바닥에는 방석을 깐 후 양손에 각각 주장자와 염주를 쥐고 측면을 바라보며 앉아 있는 모습이다. 의자에는 연부에 연화당초문양이 그려진 녹색 법피를 드리우고 있다. 화면 향우측에 주지백서의 ‘양종도총섭릉암당○○지진(兩宗都摠攝庱庵堂宇伸之眞)’ 화제가 있을 뿐이다. 화면 크기는 가로 81.8cm, 세로 124.3cm이다.","a":"도암당 우신 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643010.JPG"},{"q":"1637년(인조 15) 1월에 전라병사 김준룡(金俊龍, 1586~1642)이 수원 광교산에서 청나라 군사에게 거둔 승리를 기념하고자 암반에 비석 모양을 다듬어 만들고 그 안에 글자를 새긴 것이다. 중앙에 크게 새긴 “충양공”은 김준룡 시호이며 “○○○”는 전투에서 승리한 장소를 말한다. 그리고 작은 글씨는 병자호란이 일어나자 김준룡이 임금을 위해 호남 병사를 이끌고 광교산에 이르렀다가 청나라 대장 3명을 죽였다는 내용이다. 이때의 임금은 남한산성에 피난 가 있던 인조이며 전투 중에 사살된 청나라 대장 중의 한 명이 바로 청태조 누르하치의 사위인 백양고라(白羊高羅)이다…","a":"김준룡장군 전승지 및 비","c":"시도기념물","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646044.jpg"},{"q":"○○○은 애국지사 수산 이태식 선생의 문하생과 사림들이 건립한 수산성생의 거처 겸 강학지로서 전통의 형식을 잘 보존하고 있고 역사성이 깊어 문화유산자료로 지정되었음","a":"의령 임천정","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666634.jpg"},{"q":"○○는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 ○○○○를 언제 세웠는지 정확히 알 수 없으나 조선 효종(재위 1649∼1659) 때 다시 세웠다고 전한다. 1904년에 보수하고 1987년에 동재, 서재를 복원하였다. 건물은 출입문인 외삼문, 공부하는 곳인 명륜당과 동·서재, 사당인 대성전과 동·서무 등의 건물이 있으며, 앞에 명륜당이 있고 뒤에 대성전이 있는 전형적인 전학후묘의 배치를 이루고 있다. 조선시대에는 국가로부터 토지와 전적·노비 등을 받아 학생들을 가르쳤으나, 갑오개혁(1849) 이후 제사만 지내고 있다. 다른…","a":"창녕 향교","c":"시도유형문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641861.jpg"},{"q":"○○○○○는 아미타회상장면과 아미타극락세계로의 왕생장면을 나누어 그린 불화이다. 구품은 왕생자의 근기에 따라 상품, 중품, 하품으로 나누고 각 품을 다시 상, 중, 하로 나눈 것으로 상품상생(上品上生)에서 하품하생(下品下生)에 이르기까지 9단계로 나뉜다. ○○○○○는 화면을 수평과 수직으로 각각 3등분하여 극락정토의 아미타회상 장면과 구품의 왕생장면을 나누어 그리고 있다. 상단의 중앙에는 아미타부처님과 보살·10대 제자 등이 표현된 아미타회가 자리잡고 있으며, 나머지 8장면에는 모두 전각과 연지를 무대로 구원하는 자와 구원받는 자가 표현된 극락세계가 묘사되어 있다.…","a":"고양 흥국사 극락구품도","c":"시도유형문화유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637633.jpg"},{"q":"○○○은 중국으로부터 유입된 ○○○앙의 대상물로, 마을수호신을 일컫는다. 우리나라에서는 고려 때 부터 모시기 시작했는데, ○○○의 신체가 머무는 곳인 성황당을 만들어 정기적으로 제사를 지냄으로써 마을의 안녕과 풍요를 기원하였다. 우리나라의 ○○○은 대체적으로 마을 수호에 공이 큰 인물을 신격화하여 섬기는 경우가 많은데, 순천 김씨의 시조인 김총 역시 순천의 고을신으로 모셔지고 있다. 김총의 영정은 갑옷을 입고 투구를 쓴 모습으로, 두 손에 창을 들고 있으며 검은색 의자에 앉은 무장상으로 전신을 그린 것이다. 눈은 동그랗게 부릅뜨고 있고 큰 코에 수염이 많이 나 있어…","a":"성황신김총영정","c":"시도민속문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658394.jpg"},{"q":"낙산사 법당인 원통보전의 둘레를 사각으로 에워싸고 있는 담장이다. 조선 세조(재위 1455∼1468)가 낙산사를 고쳐 지을 때, 처음 이 담장을 지었는데 대부분 터만 남아 있어 최근에 연결·보수하였다. 안쪽의 담벽을 기와로 쌓고, 바깥쪽은 막돌로 쌓은 이 담벽은 높이 3.7m·길이 220m이다. 암키와와 흙을 차례로 다져 쌓으면서 위·아래로 줄을 맞추고, 일정한 간격으로 둥근 화강석을 배치하여 단조로운 벽면을 아름답게 장식하였다. 법당을 향하고 있는 담장 안쪽에는 밑부분에 2층의 길게 다듬은 돌기단을 깔고, 그 위에 다시 한층의 긴 받침돌을 놓았다. 담장 위에는 기와…","a":"낙산사담장","c":"시도유형문화유산","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637940.jpg"},{"q":"이 목판은 조선 후기의 대유학자 우암 송시열(1607∼1689) 의 문집과 연보 등을 모아 만든 『송자대전』의 목판으로 총 11,023판이다. 송시열은 김장생의 문하생으로 힘있고 논리적인 문장과 서체에 뛰어났고 평생 주자학연구에 몰두하여 율곡 이이의 학통을 잇는 기호학파의 주류이었다. 여러 관직을 거쳐 좌의정까지 오르지만 낙향과 유배, 재기용과 은거를 거듭하며 결국은 남인들에 의해 사약을 받고 목숨을 잃었다. 『우암문집』의 초판은 1717년(숙종 43)에 민진후가 임금의 명을 받아 교서관에서 금속활자로 간행하였으며, 그 후 정조 즉위 초에 전서간행의 어명이 떨어져 글…","a":"송자대전판","c":"시도유형문화유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023030815200000.JPG"},{"q":"전국 유림들에게 항일의식을 드높인 자하 장기석 선생의 절개를 기리기 위해 세운 비이다. 장기석(1860∼1911)은 일찍 부모를 여의고 몹시 가난하여 공부를 하지 못하다 39세의 늦은 나이에 공부를 시작하여 43세에 학문을 두루 통달하였다. 그 뒤 후진양성을 위한 교육에 힘썼으며, 일제 때 경찰서장으로 부터 경축식에 참석할 것을 강요받았으나 이를 거절하여 대구형무소에 수감되었다. 그곳에서 단식을 시작하였고 의식을 잃어 일본경찰들이 음식을 먹이려 하자 그릇으로 서장을 때려 옥중에서 생을 마치었다. 비는 평평한 바닥돌 위에 비몸을 세운 간단한 형태이다. 비문은 심산 김창…","a":"해동청풍비","c":"시도기념물","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654534.jpg"},{"q":"보한재 신숙주의 초상을 모시기 위해서 지은 영당으로, 지금의 영당은 1830년 창건하여 1888년(고종 25)에 중건하였다. 앞면 3칸·옆면 2칸의 목조 기와집이며, 옆면이 사람 인(人)자 모양인 맞배지붕이다. 신숙주는 조선 전기의 문신으로 훈민정음을 만들 때 참가하여 많은 공을 세웠으며, 그 시대의 정치와 학문에도 영향력이 컸다. 영정(초상)은 마루방에 보관하고 있고, 영조(재위 1724∼1776) 때에 구봉영당에서 모시고 있는 신숙주 초상을 옮겨 그린 것이다. 옮겨 그릴 때 정범조가 초상에 대해 쓴 글이 기재되어 있다. 화상형식은 좌안8분면으로 오사모를 쓰고, 녹…","a":"청주 묵정영당","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638564.jpg"},{"q":"이 영정은 ○○○○○ 선사의 좌안8분면 바닥가부좌상으로, 왼손엔 주장자를 들고 오른손엔 염주를 쥐고 앉아 있다. 인물의 뒤편은 갈색 상단부와 돗자리가 그려진 하단부로 이루어진 이단구도를 배경으로 호형의 등받이를 배치하였다. 의자 끝부분은 금박의 원심문으로 마감하였고, 가장자리가 주색으로 마감된 녹색의 법피를 의자처럼 표현하였다. 안면부는 세필의 선묘로 뚜렷한 눈, 깊게 패인 주름과 강조된 인중 등 이목구비를 묘사하면서 당당한 상호를 드러낸 반면 의습선의 표현에서는 선염 효과없이 동일한 선묘로 처리하여 평면적이고 도식적인 느낌이 강하다. 화면 향좌측엔 주지묵서의 ‘국일…","a":"응허당 도흡 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643033.JPG"},{"q":"○○○ 아미타삼존불 후불벽에 걸었던 3폭으로 화기(畵記)는 박락되었지만 삼장보살도와 같은 시기인 1747년에 조성된 것으로 추정된다. 아미타불을 중심으로 관음보살과 대세지보살이 각각 독립된 폭으로, 현존 실내 봉안 불화 중 가장 규모가 크다. 중앙의 아미타불화는 아미타불을 화면 가득히 크게 묘사하고, 지장과 미륵보살, 문수와 보현보살이 협시하고 있고, 상단에는 두 벽지불(壁支佛)이 자리잡고 있다. 색채는 짙은 진홍과 녹색의 강한 보색 대비에 밝은 청색과 호분의 배합을 사용하였으며, 특히 담채로 은은한 분위기를 연출하고 있다. 형태에서나 색채에서 1730년의 갑사 대웅…","a":"무량사극락전후불탱","c":"시도유형문화유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051415235700.jpg"},{"q":"백산 ○○○ 선생의 ○○이다. ○○○는 독립운동가로 창남학교, 의신학교 등을 설립하여 신학문 보급에 힘을 썼으며, 민족언론의 선구자 역할도 하였던 분으로 59세로 생을 마감하였다. ○○는 안채, 사랑채 2동으로 되어 있다. 안채는 앞면 6칸·옆면 2칸 규모에 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 왼쪽에서부터 마루·방·대청·방·부엌 순으로 배치되어 있다. 사랑채는 앞면 4칸 규모의 초가 건물로 안채와 바짝 붙어 있다. 이들 건물은 모두 동쪽을 향하고 있고, 남쪽으로 마루를 1칸씩 구성하고 있어 특이하다. 또한 다양한 기능을 가진 방이 필요한데…","a":"의령 안희제 생가","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664302.jpg"},{"q":"절터로 보이는 밭가운데 서 있는 탑으로 2층 기단(基壇)에 3층의 탑신(塔身)을 올린 모습이다. 기단은 탑신의 1층 몸돌을 괴는 곳에 굵은 2단의 괴임을 두어 윗돌을 받치고 있다. 탑신의 1층 몸돌 모서리에는 희미한 기둥 모양의 조각이 보인다. 지붕돌은 각 층 모두 밑면에 3단의 받침을 두었는데, 1층 지붕돌이 약간 파손되긴 하였으나 중후하면서도 우아한 느낌이 든다. 꼭대기에는 복발(覆鉢:엎어놓은 그릇모양 장식)이 남아 머리장식을 하고 있으나 이것 역시 뒤에 보충한 것으로 보인다. 기단부가 왜소하고 간략화되어 안정감을 잃었으나 140㎝라는 작은 크기에도 불구하고 탑신…","a":"회사동석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639471.jpg"},{"q":"고려 때 장군인 강민첨(？∼1021)의 영정을 모시고 제사지내고 있는 사당이다. 장군은 목종 때 문과에 급제하고, 현종 3년(1012) 여진족이 쳐들어오자 영일, 청하 등지에서 이들을 격퇴하였다. 또한 현종 9년(1018) 거란의 소배압이 10만 대군을 이끌고 쳐들어오자 강감찬 장군의 부장으로 출전하여 적군을 대파하는데 큰 공을 세웠다. 이러한 공로로 현종 10년(1019) 응양상장군주국이 되고 이후 추성치리익대공신에 추대되었다. 이 사당의 경내에는 1910년 후세들이 세운 신도비가 있다.","a":"하동 두방재","c":"문화유산자료","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664002.jpg"},{"q":"화강암으로 된 높이 2.1m의 미륵불로서 간송미술관에 전시되어 있다. 머리에는 큰 상투 모양의 머리묶음이 있고 옷에는 주름이 사선으로 표현되어 있다. 두 손은 가슴에 올려 모으고 있으며, 몸은 긴 돌기둥 모양으로 되어 굴곡이 없는 편이다. 부처님의 마음이 과장없이 표현되었고 조각수법이 예스러운 점이 있어 토속적인 경향을 보이고 있는 이 불상은 조각수법으로 보아 고려 중기 이후의 작품으로 추정된다.","a":"석불입상","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636112.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○군 하이면 ○○○는 서쪽으로는 봉현천이 흐르고 있고 동쪽으로는 해발 142m의 야산이 있는 곳에 자리잡고 있다. 마을 앞의 들판에는 5기의 고인돌이 사방 10m 이내에 모여 있는데 지금은 논으로 경작되고 있다. ○○○의 고인돌…","a":"고성 석지리 지석묘","c":"시도기념물","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654915.jpg"},{"q":"조선 중기의 문신이자 의병장인 ○○○과 조선 후기의 실학자인 우하영(1741~1812)의 묘역이다. 1592년 임진왜란이 일어나자 의병을 모집하고 식량을 조달하여 난민을 구제하였다. 우하영은 국가·사회의 개혁방안을 담은 『천일록(千一錄)』을 저술하였다. ○○○ 묘역은 부인 양천허씨(陽川許氏)와 함께 매장된 쌍분(雙墳; 두개의 봉분)의 형태이다. 묘제(墓制)는 의병장의 묘역답게 검소한 제도와 석물로 구성되어 있다. 봉분 앞으로는 묘표, 상석, 향로석이 있고, 하단에는 망주석만 1쌍이 있고, 석인은 조성하지 않았다. 묘표는 일반적인 원수방부형(圓首方趺形; 둥근 머릿돌과…","a":"추연우성전묘역(우하영묘역포함)","c":"문화유산자료","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660246.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398)이나 태종 7년(1407)에 지은 것으로 전하고 있다. 현재 남아 있는 건물로는 제사 공간인 대성전, 교육 공간인 명륜당, 학생들의 기숙사인 동재와 서재, 삼문, 제기고 등이 있다. 대성전 안쪽에는 공자를 비롯한 중국과 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생들을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"당진향교","c":"시도기념물","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653023.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 7년(1398)에 세워진 ○○○○는 임진왜란(1592) 때 불에 탄 것을 인조 8년(1630)에 수리하였다. 그 후에도 여러 차례 고쳤다. 현재 남아 있는 건물은 대성전·명륜당·동재·서재·제기고 등이 있다. 경사지에 위치한 ○○○○는 내삼문을 경계로 배움의 공간과 제사공간을 구분하고 있다. 앞쪽에는 외삼문·명륜당·동재·서재가 있고, 뒤쪽에는 대성전과 전사청이 있어 전학후묘의 배치를 이루고 있다. 전사청은 1981년에 지은 것으로 제사를 관리하는 곳이며, 원래 대성전 앞…","a":"장흥향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639954.jpg"},{"q":"이 성은 언제 쌓았는지 정확하게 알 수 없지만 백제 때 만든 것으로 보이며, 현재 둘레 500m 정도가 남아 있다. 조선시대에 성을 보수하여 병사들의 군량미를 저장하였기 때문에 ○○○이라고 불렀다고 한다. 이 산성의 특징은 내성과 외성이 있는 점으로, 내성은 성곽의 동북쪽 모서리에 돌출되어 있는데, 성 안에서는 가장 높은 있어 조망대 구실을 한다. 성곽의 규모는 동변 19m, 북변 37m이며, 동쪽과 북쪽 성벽이 외성벽을 겸하고 있다. 성 안쪽과 구분하는 성 줄기는 남쪽 40m, 서쪽 13m이다. 북쪽에는 북문터가 있어 밖으로부터 직접 내성에 출입할 수 있게 되어있고…","a":"합미성","c":"문화유산자료","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661687.jpg"},{"q":"○○○○○은 명석면 ○○○ 산19-1번지에 소재하고 있으며 ○○○은 1921년에 용산에 거주하던 참봉 박헌경이 어머니의 극락왕생을 기원하기 위하여 건립하였다. ○○○의 구조는 맞배집형태의 기본구조에 좌우로 지붕을 달아내어 독특한 형태의 지붕구조를 갖고 있으며, 일반 ○○○과는 다르게 온돌시설에 루마루 형태의 기초를 갖추고 전퇴간을 두어 계자난간을 두른 형태를 하고 있다. ○○○의 건립연도는 그리 오래 디지 않았으나 전통건축형태에서 변형된 형태를 하고 있어 근대로 변화되는 건축기법의 일면을 보여주고 있어 전통건축연구 자료로서 가치가 높다. 또한 건축물의 형태나 활용 등…","a":"진주 용산리 용산사 대웅전","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022335900.JPG"},{"q":"○○○은 사찰의 야간법회시 불을 밝히거나 또는 숯을 피워 주변을 따뜻하게 하는 기능을 가진 석물로 \"불우리\", \"노반지주\", \"광명대\", \"화사석\", \"정료대\"등 많은 이름을 가지고 있다. 단층기단의 탑잉 유독 문경지역에만 집중적으로 나타나듯이 ○○○ 또한 문경에 남아 있는 독특한 문화유산 중의 하나이다. ○○○은 석등의 원초적 형태로 분류되지만 현재 남아 있는 것은 모두 조선시대 중,후기가 대부분이다. ○○○○○의 형태는 사각형 지대석을 놓은 뒤, 사각기둥을 한가운데 세우고 그 위에 받침이 있는 화반(化盤)을 올려놓았다. 오랜 세월 사용되면서 화반 일부가 금이 간…","a":"문경대승사노주석","c":"시도유형문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641206.jpg"},{"q":"○○○은 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있으며, 지하에 무덤방이 위치하지만, 거대한 덮개돌 아래에 고임돌을 두지 않는 형식을 별도로 개석식(蓋石式), 또는 무지석식(無支石式)이라 칭한다. ‘○○○○○’은 임진…","a":"연천학곡리고인돌","c":"시도기념물","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646840.jpg"},{"q":"○○○○는 1903년 4월 권혁중이 설립한 교회로, 현 교회당 건물은 그 해 10월에 건립되었다고 하는데 당시의 관련자료나 기록은 남아있지 않다. 이 건물은 우진각 지붕의 단층 목조 한옥 교회당으로 평면은 장방형으로 정면 2칸이고, 측면 4칸이다. 내부 천장은 지붕틀이 그대로 노출된 연등천장이며, 지붕틀은 절충식의 트러스구조이나 구조수법이 다소 조잡하다. 횡칸에는 각각 2개씩의 지붕틀을 설치하여 2개의 기둥이 평보를 받치고 있는데 부재의 치목이 거칠고 결구수법이 격식에 맞지 않아 보이나 전체적으로 자연스러운 구조미를 느끼게 한다. 이 건물의 내부공간 구성적 특징은 부…","a":"영천자천교회","c":"문화유산자료","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663491.jpg"},{"q":"동헌은 조선시대의 지방 관아건물로 고을의 수령이 일반 행정업무와 재판 등 공적일 일을 하던 곳이다. 백성을 잘 다스리고 사랑한다는 뜻의 ‘○○○’은 조선조 ○○현의 동헌으로 광무 8년(1904)에 오병선 군수가 서문을 썼다. 잘 다듬은 긴 돌로 쌓은 2단의 받침대 위에 네모난 주춧돌을 놓고 네모난 기둥을 세운 앞면 6칸·옆면 3칸의 건물이다. 오랫동안 ○○군청의 민원실로 사용되면서 뒤편으로 건물을 새로 지었고, 내부도 많이 변경되었던 것을 옛 모습대로 복원하였다.","a":"태안 목애당","c":"시도유형문화유산","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639235.jpg"},{"q":"안채, 사랑채와 헛간채가 앞뒤로 나란히 배치되어 三자 형태를 취하고 있다. 안채는 앞면 8칸·옆면 2칸 규모로 큰 一자형의 평면을 이루고 있으며, 지붕은 옆에서 볼 때 사람 인(人)자 모양의 맞배지붕이다. 사랑채는 앞면이 6칸·옆면 2칸이며 가운데 2칸 대청을 두고 대청 뒷면에 문을 두었으며 좌우에 방을 두었다. 방은 정면으로 출입하는 문이 없고 빛이 드는 창을 내었다. 건물을 지을 당시에는 일반 남부지방 건물이었으나 양쪽 측면으로 지붕을 달아내고 누마루 형식의 대청과 부엌에 필요한 광을 늘려 지어 집의 규모가 커졌다. 경사지에 대지를 조성하여 안채 기단이 없고 사랑…","a":"산청소남리권씨고가","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664222.jpg"},{"q":"조선 헌종(재위1834∼1849)의 후궁인 경빈 김씨가 자신의 거처인 순화궁에서 궁체로 쓴 두권의 책으로, 이 둘을 가리켜 『순화궁첩초』라고도 한다. 사절복식자장요람의 표지는 남색으로 용무늬가 있고, 국기복식소선은 녹색에 구름무늬가 있다. 책의 내용은 조선조 역대 왕과 왕비의 기일과 왕릉 및 국가 기일에 입는 의복에 대한 것을 기록하였다. 조선은 국초부터 유교를 숭상하고 조상숭배를 으뜸으로 하였으므로 궁실의 왕비로서 조상의 기일과 복식에 큰 관심을 가졌던 것으로 보인다. 이 두 책은 특히 복식사 연구에 귀중한 자료가 된다.","a":"국기복색소선 및 사절복색자장요람","c":"시도유형문화유산","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636282.jpg"},{"q":"정읍시 이평면 면사무소 앞 도로 건너편에 위치한 ○○○○는 1894년 동학농민운동 당시 배들평 농민 수천명이 고부로 가기 전에 모였던 곳으로 제1차 백산기포를 할 때까지 장두청을 두고 진을 설치했던 장소이다. 또한 이곳에는 180년 정도 된 ○○○ 한그루가 서 있는데, 이 나무 아래에서 ○○○○에 모여든 농민들에게 전봉준이 군수 조병갑의 탐학과 농민 수탈의 실정을 알리고 농민봉기의 필요성을 역설하였다고 전한다. 이곳 주민들은 지금도 이 ○○○의 감은 따지 않는다고 한다.","a":"말목장터와감나무","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653724.jpg"},{"q":"조선 초기의 문신이며 대학자였던 신재(愼齋) ○○○ 선생의 묘소이다. 어려서부터 효성이 지극하였으며 학문에도 열성적이었다. 중종 17년(1522) 문과에 급제한 후 여러 관직을 두루 거쳐 중종 36년(1541)에 풍기 군수가 되었다. 중종 38년(1543)에는 풍기 지방에 우리나라 최초의 서원인 백운동서원(뒤의 소수서원)을 세웠다. 명종 6년(1551)에는 황해도 관찰사가 되어 해주에 수양서원을 창설하여 최충을 모시기도 하였다. 죽은 뒤 선생의 유언에 따라 고향에 장사 지내고 조정에서는 예조판서의 벼슬을 내렸다. 선생의 묘는 3기의 묘중 가운데 위치하는 둥근 무덤으로…","a":"함안 주세붕 묘역","c":"시도기념물","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654875.jpg"},{"q":"이 집의 안채는 조선시대 후기 건물로 부용면 ○○○ 김종철(金鍾喆)씨가 살던 ○○를 이전 복원한 것으로 ‘ㄱ’자집 형태의 목조기와집이다. 광채는 지붕을 얇은 판석으로 덮은 돌기와집(석와가(石瓦家))형태로 중부지방의 산골부락에 많이 있었던 형태이다. 가옥의 구조는 안채가 ‘ㄱ’자형태의 목조와가이고 광채는 ‘一’자 돌기와집이다. 1995년 문의문화유산단지가 조성되면서 현위치로 이전 복원하였다. 1982년 전국 취락 및 전통가옥(민가)조사 기록대장에 의하면 1950년대까지 거주하였던 송동촌씨의 3대 선친이 건축했다고 전해지나 정확한 건립년대는 확인할 수 없다. 현재는 문의…","a":"청주 부강리 고가","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638794.jpg"},{"q":"조선 정종(재위 1398∼1400)의 열번째 아들인 ○○○을 모시기 위해 세운 사당이다. ○○○은 가난한 백성을 정성껏 도왔으며, 왕자의 신분에도 들에 나가 농사를 지었다. 또한 여름에 홍수로 수백명의 이재민이 발생하자 구제하였으며, 덕을 쌓은 어른이라 하여 적덕공이라고도 불렀다. 처음 연기군 남면 방축리에 있던 건물이 낡아 조선 영조 15년(1739)에 지금 있는 자리로 옮겼다.","a":"장군 덕천군사우","c":"문화유산자료","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1797531.jpg"},{"q":"「○○○○○」은 근대기 경남·부산 지역에서 활동한 완호(玩虎, 1869~1933)의 현존 작품 중 가장 이른 시기 불화 ○○으로 폭 55㎝의 한지를 화면의 너비(156㎝) 만큼 재단하여 가로로 이어 붙여 바탕질을 마련하고 먹선으로 치성광여래삼존과 칠성여래, 칠원성군을 그렸다. 화면 구성을 2단으로 나누어 1단에는 일월관을 쓰고 있는 자미대제를 중심으로 좌우 대칭구도를 이루면서 6위의 칠원성군을 배치하였다. 2단에는 일광과 월광보살의 협시를 받는 치성광여래가 원형의 두광과 신광을 겸비한 모습으로 중앙에 자리하고 그 좌우로 각각 4위씩 8명의 여래를 좌우 대칭구도로 그렸…","a":"김해 영구암 치성광여래회도 및 초본","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666685.jpg"},{"q":"○○○○○은 ○○군 장계면 ○○○ 백화산 자락에 자리한 가야 수장층의 묘역으로 직경 20~30m 내외의 대형고분 20여기가 분포되어 있다. ○○○ 고분군에 대한 2차례 발굴조사를 통해 무덤내부에서 다양한 가야토기를 비롯하여 철제마구, 꺽쇠, 교구, 환두대도 등 피장자의 위상이 매우 높았었음을 짐작케 하는 최상급 가야유물이 출토 되었다. 또한, 한 봉토 내에 주곽과 부곽이 배치된 다곽식의 형태도 파악되었으며, 주곽과 부곽 모두 가야계 수혈식 석곽묘로 확인되었다. ○○○○○은 전북특별자치도 동부지역에 기반을 두고 성장했던 가야계 소국의 존재를 알려줄 뿐만 아니라, 그 세…","a":"장수 삼봉리 가야고분군","c":"시도기념물","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653891.jpg"},{"q":"영·정조 대의 무신 ○○○ 장군의 생가다. ○○○은 1721년에 원삼면 문촌리에서 태어났으며, 수도 방위에 큰 역할을 담당하였다. 고택 주변으로 묘소, 신도비, 정자터 등이 남아있으며, 묘역은 향토유적 제4호로 지정되었다. 이 가옥은 안채와 사랑채, 행랑채로 구성되어 있다. 그리고 안채 지붕에 있는 기와 명문에 ‘乾隆十八年癸酉日造作(건륭십팔년계유일조작)’이라고 기록되어 1753년에 건축한 것으로 추정된다. 이 가옥은 채 구성, 공간분할, 조경수법 등에서 고전적인 특징을 간직하고 있으며, 본채 뒤쪽 경사지의 조절과 화계의 조성 및 담장의 구성방법에서 향촌에 조영된 조선…","a":"용인이주국장군고택","c":"문화유산자료","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660156.jpg"},{"q":"○○지역 영양 남씨 시조인 남계조의 묘를 지키기 위해 세운 재실이다. 이곳은 명당으로 건물과 비석, 천연기념물로 지정된 향나무가 질서 있게 자리잡고 있다. 1670년경 세운 것으로 알려져 있으나 확실하지 않으며 17세기 양식을 엿볼 수 있는 부분도 남아 있지 않지만 독특한 지붕 양식을 지니고 있다. 이 지역의 대표적인 재실 건축물로 민속적 가치를 지닌다.","a":"청송 화지재","c":"시도민속문화유산","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658963.jpg"},{"q":"청주 곽씨 문중에서 후세를 교육하기 위해 지은 건물이다. 1500년대에 지은 건물로 원래 삼락재라고 불렀는데, 뒷날 익성 허유가 ○○○이라 이름지었다고 전한다. 1854년 지금의 위치에서 동쪽으로 1㎞정도 떨어진 유전리에 다시 지었는데 ○○댐 건설로 1986년 10월 지금 있는 자리로 옮겨 복원하였다. 건물은 앞면 4칸·옆면 2칸 규모에, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 팔작지붕으로 꾸몄다.","a":"합천 화수당","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664060.jpg"},{"q":"○○읍 갑곶리와 김포군 월곶면을 배로 연결해 주던 곳이다. 갑곶이란 지명은 고려 고종 때 몽고가 침입하자 왕이 ○○도로 천도하게 되었을 때 이곳이 강 건너와의 거리도 짧고 수심이 얕아서 군사들이 갑옷을 벗어 쌓아 놓고 건널 수 있었다는 데서 유래되었다. 이곳은 정묘호란(1627) 당시 인조가 건넜던 나루터로, 병자호란(1636) 때에도 봉림대군이 임금을 모셨던 곳이고, 병인양요(1866) 때에는 프랑스군과 치열한 격전을 벌인 곳이기도 하다. 처음에는 나루터 시설 없이 이용되었다가, 조선 세종 원년(1419) 박신(朴信)이라는 사람이 최초로 자신의 재산을 털어 14년간…","a":"강화 갑곶나루 선착장 석축로","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645596.jpg"},{"q":"약 4등신의 신체 비례를 보이는 고려 전기 석조(石造) ○○○○으로 현재 ○○○ 산100-35번지 내 ‘자씨각(慈氏閣)’이라는 전각(殿閣) 안에 모셔져 있다. 얼굴은 장방형으로 뺨에 살이 올라 여성적이고 온화한 인상을 준다. 이마는 좁고 이목구비가 중앙으로 몰려 있는데 이러한 얼굴 표현은 나말여초의 불․보살상에 많이 보이는 형태이다. 보계(寶髻)가 높게 솟아 있고, 보계와 머리 중간에 정면과 좌우 측면에 장식이 달린 보관(寶冠)을 착용하고 있다. 불상의 육계(肉髻)처럼 높은 보계를 지닌 보살상은 강원특별자치도 원주시 매지리 석조○○○○ 등 주로 나말여초~고려 전기에…","a":"진관동 석 보살입상","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636556.jpg"},{"q":"조선 중기의 의병장인 가계 ○○ 장군의 묘소이다. 선조 25년(1592)에 임진왜란이 일어나자 의병을 일으켜 웅천·김해·문경 등에서 대승을 거둬 선조 26년(1593) 성주 목사가 되었다. 그러나 성주 전투에서 왜적을 토벌하다 그 해에 전사하였다. 장군은 날아다니듯 빠르다 하여 비(飛) 장군이라 불리었으며, 왜적도 장군을 두려워하여 싸우기를 피했다고 한다. 정조 16년(1792) 나라에서는 그의 관직을 병조판서로 높여 주었으며, 그의 조카 홍록과 함께 나라에 충성하였다 하여 이조판서 서유린에게 명하여 쌍충비문을 짓게 한 후 성주와 진주에 쌍충각을 세웠다. 현재 묘역에…","a":"창원 제말 묘","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664381.jpg"},{"q":"선조 26년(1953) 6월에 벌어진 ○○성 2창 전투에서 왜적과 맞서 싸우다가 순직한 수문장 ○○○의 묘소이다. ○○○의 순직 후 ○○지역 유학자들은 상서문을 올려 선새으이 공적을 포상하여 달라고 청원하였고 이를 인정하여 국가에서 선무원종공신에 녹훈하였다. 이때의 공적으로 ○○정내의 창열사에 선생의 위패가 봉안되어 있다. 본묘의 외형은 원형으로 봉분 가장자리를 할석으로 둘레돌을 쌓아 보호하고 있고 무덤 앞에 상석과 묘비 좌우에 망주석 석상 등을 세웠다.","a":"진주 박세항 묘","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022404900.JPG"},{"q":"○○○가 소장중인 ○○○○○ 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, 월인석보제21(상), 불설대보부모은중경이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"창원 봉림사 불교전적류","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642607.jpg"},{"q":"○○○란 옛 선현의 자취를 살피어 후세에 전하고 그를 기리기 위해 세우는 비로, 이 두기의 비들은 고려 후기의 문신인 ○○과 그의 동생 ○○의 공적을 기리고 있다. ○○의 호는 행촌으로 고려 충선왕 5년(1313) 과거에 급제하여 비성교감에 임명된 후 여러 관직을 거쳐 도관정랑이 되었다. 이후 충혜왕∼충목왕 대까지는 유배와 복직을 거듭하다가 공민왕 때에 수문하 시중이 되었다. 홍건적이 침략하여 개경을 핍박하자 왕을 모시고 안동으로 피난갔던 공이 인정되어 1등 공신이 되고 철성부원군에 봉하여졌다. ○○의 호는 도촌으로, 충숙왕 때 문과에 급제하였으며, 공민왕 때 형부상…","a":"고성 이암·이교 유허비","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664360.jpg"},{"q":"경상남도 ○○군에 있는 이 산성은 해발 197m의 자구산 장원봉과 북서쪽으로 이어진 해발 167m의 산 정상에 각각 남아 있는데, 문암 큰 성과 작은 성으로 부른다. 전체 둘레는 1100m 이고 동남쪽의 일부를 제외하고는 모두 양호한 상태로 남아 있으며, 성 폭은 대개 3m 정도로 추정한다. 큰 성은 장원봉의 8부능선 부분에 거의 둥근모양의 타원형으로 돌아가며 쌓았고, 성벽은 바깥을 돌로 쌓고 안쪽은 흙과 잡석으로 밋밋하게 만들었다.","a":"함안 문암산성","c":"시도기념물","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656278.jpg"},{"q":"‘○○○’는 삼학사[三學士 ; 홍익한洪翼漢)·윤집(尹集)·오달제(吳達濟)]의 넋을 위로하고 충성스런 절개를 기리기 위하여 세운 사당이다. 이들 삼학사는 병자호란[丙子胡亂 ; 1636년-1637년에 일어난 조선과 청나라의 전쟁] 때 중국 청나라와의 화의를 반대하여 나라를 위해 목숨 바쳐 충성했던 사람들이다. 뒷날 이들과 뜻을 같이했던 김상헌(金尙憲, 1570년-1652년)과 정온(鄭蘊, 1569년-1641년)도 추가로 사당에 모셨다. 사당은 남한산성 기슭에 세워졌으며, 1693년 왕이 내린 ‘○○○’라는 이름으로 불리게 된다. 고종의 서원철폐(書院撤廢 ; 1871년 전…","a":"현절사","c":"시도유형문화유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637318.jpg"},{"q":"관무량수경의 16관 중 제 14·15·16관에 해당되는 9품이 극락에 간 것을 묘사한 그림으로, 동화사 염불암의 ○○○○○와 함께 동일한 원본을 보고 그린 것이다. 비단 바탕에 채색하였으며, 가로 170.8㎝, 세로 166.3㎝의 규모이다. 얼굴의 이목구비를 섬약하게 표현하긴 하였으나, 조선 후기 ○○○○○의 독특한 유형을 잘 보여주며, 음영의 표현이나 적색과 녹색의 대비, 화려한 꽃무늬 등은 19세기의 불화양식을 그대로 나타내고 있다.","a":"지장사 극락구품도","c":"시도유형문화유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588024.jpg"},{"q":"영천 황보씨의 시조인 ○○○○ 장군의 묘이다. 장군은 신라말 고려초에 정치·군사적으로 큰 비중을 차지하고 있던 영천지방의 호족 출신이며 영천 지방을 지키기 위해서 ○○○을 축조한 장군으로 전해지고 있다. 고려 태조 왕건(877∼943)을 도와 고려 건국을 이룩하는데 큰 공을 세워 영천군을 식읍(食邑:국가에서 공신에게 내리어 조세를 개인이 받아 쓰게 한 고을)으로 받고 좌승지의 벼슬에 올랐다. 경상북도 영천의 운주산에 있는 장군의 묘는 비교적 큰 원형분이며 상석과 향로석을 배치하였다. 봉분 우측 앞부분에는 영조 43년(1767)에 세웠던 비문을 옮겨 적어 1947년에…","a":"전금강성장군황보능장묘","c":"시도기념물","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654474.jpg"},{"q":"○○○○는 서울특별시 중랑구 망우동에 관한 인문지리서로, 조선시대 지리지가 군현별로 편찬되는 것이 일반적인데 비해, 이 지리지는 동 단위로 편찬되었다는 특징이 있다. 내용상으로도 동계, 동규, 향약, 선생안, 선배비장 등 지방의 특수 사정을 상세히 기록하여, 조선 시대 지방사 연구의 귀중한 자료가 되고 현전사례가 매우 드물다.","a":"망우동지","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636524.jpg"},{"q":"1743년(영조 19)에 윤4월 7일에 거행된 대사례 의식을 기록한 화권(畵卷)이다. 조선시대 행사기록화로는 드문 화권 형식인 점에서 주목된다. 대사례는 오례(五禮) 중 군례(軍禮)에 해당되는 의식으로 영조(英祖)가 임진왜란 이후 폐지된 대사례 의식을 시의에 맞게 의문(儀文)을 정비하여 부활시킨 것이다. <○○○○>의 내용은 󰡔대사례의궤(大射禮儀軌)󰡕(1743년)에 의해 상세하게 밝힐 수 있다. <○○○○>는 어사도(御射圖), 시사도(侍射圖), 시상도(施賞圖)로 나뉘어진 그림 세 장면, “어사삼획(御射三獲)”이라고 쓴 어사의 성적, 집례관(執禮官) 이덕인(李德寅)과…","a":"대사례도","c":"시도유형문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636534.jpg"},{"q":"○○○은 약천 금희성의 정자로 그의 후손들이 100여 년 전에 세웠다. 금희성은 경학과 문장이 뛰어났으며, 옥산서당에서 오랫동안 많은 문인 후배 양성에 전념하였다. 계단이 있는 자리를 제외하고는 난간이 사방으로 둘렀으며, 앞면과 중간이 마루이고 좌우가 방이다. 안쪽에는 정기회가 지은 약천중기, 이유승이 지은 정시중건기 등 정자에 대한 기록과 초대 부통령을 지낸 이시영의 친필로 된 ‘○○○’, ‘반곡정사’라는 현판을 보관하고 있다. ○○○ 안에는 한 그루가 향나무가 삿갓 모양을 이루고 있으며 주위에는 노송이 둘러있어 더 한층 경관을 운치 있게 하고 있다.","a":"약천정","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662515.jpg"},{"q":"불교의 요지를 42장으로 나누어 석가의 교훈을 적절한 비유와 함께 간명하게 풀이한 것으로 보존상태가 양호하며 판각한 글씨체를 새김에 있어 정교하고 인쇄상태의 선명성과 지질로 보아 귀중한 자료가 되므로 불교사 연구뿐만 아니라 서지학 에 있어서도 가치있는 자료이다. 크기는 가로 14.5cm, 세로 21.5cm 이며 인쇄상태 및 지질로 보아 보아 1384년 판각당시의 인출본으로 생각된다.","a":"불설사십이장경","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638896.jpg"},{"q":"고려 말기의 학자 우탁(禹倬, 1263~1342)의 학문과 덕행을 추모하기 위해 1570년(선조 3) 퇴계 이황(退溪 李滉)선생의 발의로 인근의 사족과 수령들의 협조를 받아 예안을 포함한 안동지역에서 최로로 건립된 서원이다. 1684년(숙종10)에 사액을 받은 후 대원군의 서원철폐 때 훼철되었다가, 1969년 현 위치에 이건 복원되었고, 1991년에는 이곳으로 옮겨온 안동대학교에 기부되었다. 안동대학교 도서관 뒤편에 야산을 등지고 남향하고 있으며 제향 및 강학공간과 고직사가 각기 별도의 곽을 이루며 병렬로 배치되어 있다. 강학공간은 강당이 중앙에 자리 잡고 그 뒤편…","a":"역동서원","c":"시도기념물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017042810154000.JPG"},{"q":"○○○은 조선 숙종 27년(1701)에 세운 미호서원의 부속 건물인데, 제월당(霽月堂) 송규렴(宋奎濂, 1630∼1709)이 제자를 모아 가르치던 터에 지어진 건물로 건물안에는 송규렴이 지은 미호신사(渼湖新舍) 상량문이 걸려있다. 송규렴은 조선 중기 문신으로 문과에 급제하여 충청도 관찰사와 예조참판을 지내고 예조판서, 대사헌 등에 임명되었으나 모두 그만두었는데, 80세 때에 이르러 지돈녕부사에 올랐다. 학문이 뛰어나 송시열, 송준길과 함께 삼송(三宋)으로 일컫는다. 이 건물에는 정조(재위 1776∼1800)가 직접 써서 내린 ‘사호각(四皓閣)’이라는 현판이 걸려 있었…","a":"취백정","c":"문화유산자료","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659700.jpg"},{"q":"조선후기의 동화백자로 둥글게 성형한 후 동체를 깎아내어 10개의 면으로 구성한 각호(角壺)이다. 구연은 직립하였으며 구연 아래 어깨부분에는 당초문 띠를 둘렀다. 전반적으로 회백색의 어두운 태토에 동화안료로 장식하였는데 동화의 발색이 자줏빛으로 또렷하다. 동체 전면에는 10면에 걸쳐 간격을 맞추어 4곳에 이중 원 권을 두르고 그 안에 새 또는 식물을 그려 장식하였다. 동화의 발색이 좋은 편이며 동체 전면에 시문한 점이 독특하다. 굽은 수직굽이며, 흙물을 바르고 그 위에 모래를 받쳐 구운 흔적이 접지면과 굽바닥에 있다. 조선후기 동화백자는 현전하는 예가 많지 않으며, 제…","a":"백자동화원형문각호","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636467.jpg"},{"q":"조선 영조 11년(1735) 오류정 김두행(1705∼1785) 선생이 지은 살림집이다. 선생은 중국 진나라 도연명의 뜻을 따라 집 뒤뜰에 버드나무 다섯 그루를 심고 정자를 지어 오류정이라 하였다. 건물은 앞면 4칸·옆면 5칸 규모이며 ㅁ자형 평면구조를 이룬다. 사랑방 왼편으로는 2칸을 내어 마루를 깔고, 좁은 마루를 돌려 조각한 난간을 설치하였다. 안동지방을 중심으로 분포되어 있는 양반집의 대표적인 예로 귀중한 자료이다.","a":"오류정종택","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662523.jpg"},{"q":"조선 명종 11년(1556) 강릉부사 함헌이 사신으로 중국에 갔다가 오도자가 그린 공자의 초상화를 가지고 돌아와 명종 16년(1561)에 처음 세웠다. 그 후 정조 6년(1782)에는 주자, 순조 6년(1806)에는 송시열을 함께 모시면서 선현에 대한 제사와 지방의 교육을 담당하게 되었다. 흥선대원군의 서원철폐령으로 인하여 서원은 없어지고 영정과 위패는 강릉향교로 옮겨졌다. 지금의 서원은 1903년에 새로 지어졌는데 강릉지방의 유림이 사당건물을 지어 집성사라 하고, 사당 옆에는 별묘를 세워 칠봉사라 하였다. 집성사·칠봉사·문·오봉강당·묘정비각·2개의 묘정비 등이 남아…","a":"오봉서원","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637968.jpg"},{"q":"○○○란 쇄국정책을 실시하던 흥선○○○이 병인양요, 신미양요를 치르면서 더욱 그러한 의지를 굳혀, 서양세력을 배척하고 그들의 침략을 경계하여야 한다는 의지를 국민에게 심어주고자 서울 및 전국의 중요도로변에 세우도록 한 비이다. 홍성지역에 자리하고 있는 이 비는 넓적한 자연암석 위에 비몸을 꽂아놓은 모습이다. 비문에는 “서양 오랑캐가 침범하였는데 싸우지 않으면 화친을 할 수 밖에 없고, 화친을 주장하면 나라를 파는 것이 된다”라는 강한 어투의 경고문구를 적어 놓았다. 고종 8년(1871)에 전국에 일제히 세운 것으로, 1882년 임오군란이 일어나 ○○○이 러시아 공사관…","a":"대원군척화비","c":"문화유산자료","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661159.jpg"},{"q":"○○○의 오백전 앞에 자리하고 있는 석탑이다. 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 형태로, 통일신라 석탑의 전형적인 양식을 따르고 있다. 아래층 기단은 각 면에 가늘고 긴 안상(眼象)이 정교하게 조각하였으며, 위층 기단에는 면의 모서리와 가운데에 기둥모양의 조각을 새겼다. 탑신부는 몸돌과 지붕돌이 각 한 돌씩이다. 층마다 몸돌의 모서리에 기둥모양의 조각을 두었으며, 몸돌이 위로 오를수록 알맞게 줄어들어 안정감이 있다. 지붕돌은 밑면의 받침이 각 4단씩으로, 통일신라 후기∼ 고려 전기 즈음에 주로 나타나는 양식이며, 네 귀퉁이가 살짝 치켜올라가 경쾌하다.…","a":"증심사삼층석탑","c":"시도유형문화유산","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637136.jpg"},{"q":"조선 중기의 문신으로 대학자이며 의병장인 중봉(重峰) ○○ 선생의 ○○이다. 명종 22년(1567)에 문과에 급제한 후 여러 관직을 지냈다. 관직에 있을 때는 국가 정책에 있어 바른 말을 서슴치 않았으며, 특히 일본과의 친교정책에 목숨을 걸고 반대하였다. 학문에 조예가 깊었던 선생은 관직에서 물러난 뒤 ○○에 후율정사를 짓고 제자 양성과 학문을 닦는데 전념하였다. 1592년 임진왜란이 일어나자 ○○에서 의병을 모아 왜적을 공격하는데 앞장 섰으며, 영규대사가 이끄는 승군(僧軍)과 합세하여 청주성을 탈환하였다. 이어 금산에서 700명의 군사로 수만의 왜적과 싸우다 전원…","a":"옥천 조헌 묘소","c":"시도기념물","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649256.jpg"},{"q":"조선 전기 문신이었던 ○○○과 그의 아버지 판서공 변옥란, 친형인 춘당 변중량의 행적을 기록해 놓은 비를 보호하고 있는 ○○이다. ○○○은 조선 건국 초기에 예조판서 등의 여러 중요한 관직을 거쳤으며, 특히 문장에 뛰어나 20여년간 대제학을 맡아 외교문서를 작성하였다. 세종(재위 1418∼1450) 때에는 『태조실록』의 편찬과 『고려사』수정 작업에 참여하였다. 변옥란(1322∼1395)은 고려말에 3판서를 지내고, 이성계를 추대하여 조선 개국의 공신이 되었다. 변중량(1352∼1398)은 조선 태조 때 좌승지를 지냈으며 시문(詩文)에 능하였다. 담장이 둘러싸인 자그마…","a":"밀양 변계량 비각","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663846.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북으로는 해발 600m의 덕대산 기슭이 감싸고 남으로는 낙동강이 흐르고 있는 경상남도 ○○시 하남읍 ○○○에 40여 기의 고인돌 무리가 있다. 이 고인돌은 7∼10기씩 무리를 이루고 있는데 현재 확인된 것은 40여 기이지만 주민들에 따르면…","a":"밀양 남전리 지석묘군","c":"시도기념물","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654971.jpg"},{"q":"이 정자는 문종<文宗> 원년(1451)에 배환<裵桓>공이 처음 건립하였다고 전한다. 조선<朝鮮> 순조<純祖> 13년(1813)에 중건<重建>하였으나 그 후 퇴락하여 고종<高宗> 18년(1881)과 1955년에 다시 중수하였다. 안동지역에 있는 일반적인 정자의 형태를 잘 유지하고 있으나 누상주<樓上柱>에 비해서 누하주<樓下柱>가 짧은 것이 특징이며 이는 마지막 중수때에 의도적<意圖的>으로 변형했다고 생각된다.","a":"낙암정","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662809.jpg"},{"q":"○○○○○은 부산광역시 강서구 죽림동 가락산에 있는 것으로, 가락성 또는 죽도성이라고도 한다. 가락산은 동서로 길게 뻗은 독립된 야산으로, 그 동쪽 끝이 낙동강 서쪽 지류에 인접해 있어 선박을 정박시킬 수 있는 지리적 조건을 갖추고 있다. 이 성은 임진왜란 때 왜장인 니베시마가 쌓은 것으로, 해발 35m의 낮은 구릉지 양쪽에 축조되었다. 제일 높은 곳에는 소위 일본성의 양식인 본환(本丸)이 있는 것이 특징적이다. 석재는 부근에서 구하기가 어려워 먼 곳에서 육로 및 뱃길을 이용하여 운반한 것으로 보인다. ○○○○은 주변의 구포왜성, 양산왜성과 함께 삼각형을 이루어 ○○…","a":"김해 죽도왜성","c":"시도기념물","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645198.jpg"},{"q":"○○○ 내에 있는 누각으로 처음 스님이 되시는 분들의 수도장소로 사용되었다. 1930년에 ○○○ 주지 손민선사가 지었으며, 1985년에 지붕을 한차례 고쳤다. 2층 누각으로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"하동 쌍계사 청학루","c":"문화유산자료","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663890.jpg"},{"q":"성종의 장인이었던 윤호(尹壕, 1424~1496)의 생애와 공적을 새긴 비이다. '○○○'은 사후에 받은 시호이며 본관은 파평(坡平)이다. 딸이 성종의 왕비인 정현 왕후(貞顯王后)가 되자 영원부원군(鈴原府院君)에 봉해졌다. ○○○는 묘역 입구에 세워져 있다. 사각형의 받침돌에 비신(碑身 ; 글씨를 새기는 부분)을 세우고 이수(螭首 ; 용을 새겨 장식한, 비석의 머릿돌)를 올린 방부이수(方趺螭首) 양식을 갖추고 있다. 비신과 이수의 앞면은 한국전쟁 때의 탄흔으로 인해 크게 훼손된 상태이다. 다행히 뒷면의 비신과 이수는 비교적 온전하다. 이수는 구름속에서 여의주를 갖고…","a":"평정공윤호신도비","c":"문화유산자료","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660270.jpg"},{"q":"○○○○○은 안채(‘ㄷ’字, 문간채 포함), 사랑채(‘ㄹ’字)로 구성되어 있는데, 사랑채와 안채가 모두 팔작지붕에 굴도리 오량가(五梁家)로 19세기 말의 서울 부잣집(사대부집은 아님)의 주택양식을 전형적으로 보여주고 있다.","a":"가회동 김형태 가옥","c":"시도민속문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018020616320400.jpg"},{"q":"○○○는 인의리 마을 뒤편의 야산 완경사지에 배산하여 남동향으로 바라보고 있으며, 성종 시대 성리학의 대가요 대문장가인 문장공(文莊公) 매계 조위(梅溪 曺偉, 1454～1503)가 태어나 어린 시절을 보낸 유허지에 유업을 기리기 위하여 건립한 학문소로 16세기 이후 성리학적 자연관에 따라 많이 지어진 선비들의 학문 및 휴식처가 조망성이 뛰어난 곳에 자리 잡았듯이 ○○○ 또한 전망이 좋은 장소이다.","a":"김천 율수재","c":"문화유산자료","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663638.jpg"},{"q":"의성 김씨 개암공파의 종가이다. 해저마을은 영남의 대표적인 동성촌으로 의성 김씨 가문에서 정조(재위 1776~1800)대에 많은 문과 급제자들을 배출하였고, 이 시기 영남 사람들의 정치·사회적 활동에 주도적으로 참여하면서 영남의 대표적인 명문으로 자리잡았다. 1·2차 유림단 사건으로 불리는 항일 독립운동에 김창우가 주도적으로 활약하여 건국포장을 받았고, 이러한 독립운동이 주로 이 종가를 중심으로 논의되고 있었다는 점에서 뜻깊은 의의를 찾을 수 있다.","a":"개암종택","c":"시도기념물","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654643.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 3년(1403) 이곡리에 처음 지었고, 인조 24년(1646)에 지금 있는 자리로 옮겼다. ○○○의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다. ○○○○의 특색은 단군에게 제사지내는 단군묘와 최치원의…","a":"옥구향교대성전","c":"문화유산자료","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661706.jpg"},{"q":"이 비석은 예전에 이곳에 자리잡았던 화산서원에 있던 것이다. 화산서원은 조선 선조 11년(1578)에 건립하여, 조선 전기의 대학자 이언적(李彦迪)과 송인수(宋麟壽)의 위패를 모시고 제사지내던 곳이다. 이언적은 전주 부윤으로 부임하여 도덕과 예절로 백성의 교화에 힘썼고, 송인수는 전라 감사로서 청렴한 정치를 펼쳐, 각각 이 지역과 인연이 깊었다. 화산서원은 효종 9년(1658)에 나라에서 이름을 지어주고 후원하는 사액서원으로 선정되기도 하였으나, 고종 5년(1868) 서원철폐령에 따라 헐렸다. 지금은 송시열이 비문을 짓고 송준길이 글씨를 쓴 이 비석만 남아, 이곳이…","a":"화산서원비","c":"문화유산자료","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661607.jpg"},{"q":"연촌 최덕지·암계 최연손·율계 장급·사촌 장경세 등의 위패를 모신 서원이다. 조선 인조 8년(1630)에 세웠으며, 광무 원년(1897)에 철폐되었다가 그 후 1907년에 다시 세웠다. 제사지내는 장소인 사당은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 공부하는 강당 역시 팔작지붕으로 앞면 4칸·옆면 3칸 규모의 건물이다. 이 서원에서는 해마다 음력 3월에 제사를 지내고 있다.","a":"주암서원","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661637.jpg"},{"q":"조선 중기의 대학자였던 사계(沙溪) ○○○ 선생과 광산 김씨의 중흥을 이룬 허씨 부인, 김철산, 김겸광, 김공휘 등의 묘지이다. ○○○은 송악필과 이이의 문하에서 학문을 배웠으며, 임진왜란 때에는 명나라 군대의 군량조달에 공을 세우기도 하였다. 늦은 나이에 벼슬을 시작하였고 과거를 거치지 않았기 때문에 중요한 벼슬은 맡지 않았으나 인조반정 이후로는 서인을 중심으로 한 기호학파의 중심 인물이 되어 영향력이 매우 컸다. 그는 주로 학문과 교육에 시간을 보내면서 조선 예학의 한 줄기를 형성했고 제자로 송시열과 송준길 등의 대학자를 배출했다. 묘역은 주변이 소나무숲으로 둘러…","a":"김장생선생묘소일원","c":"시도기념물","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652755.jpg"},{"q":"이 일기는 파평 윤씨 충헌공파 문중에서 소장하고 있는 사료로, 25책 125권이다. 조선 경종 1년∼2년(1721∼1722) 경종의 왕위계승문제를 둘러싸고 노론과 소론 사이에 일어난 당쟁의 옥사를 기록한 것으로 필사본이다.","a":"신임일기","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661503.jpg"},{"q":"통도사 소장 고승영정(○○○영정)은 18세기에서 19세기 말에 조성된 작품들로서 당시의 화풍을 다양하게 보여줄 뿐만 아니라 경상도 지역에서 활동한 화승들의 이력과 양식적 특징을 파악할 수 있어 조선후기 고승 영정에 관한 시대 및 지역 연구에 중요한 자료임.","a":"사명당 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642983.JPG"},{"q":"현재 명부전 지장삼존상 뒤에 걸려 있는 이 작품은 두건을 쓴 지장보살(地 藏菩薩) 및 도명존자(道明尊者), 무독귀왕(無毒鬼王) 등 지장삼존을 중심에 놓고 좌우에 시왕과 판관, 사자, 옥졸, 선악동자, 사천왕 등을 배치한 그림으로 1924년 6월 고산(古山) 스님에 의해 제작된 작품이다. 7폭을 붙여 한 폭으로 완성한 작품으로 모두가 완전하게 남아 있는데, 이 작품 역시 지장사의 불화와 마찬가지로 횡폭으로 길게 그린 점이 특징이다. 또 좌우 권속들의 얼굴을 음영법으로 처리한 기법은 고산당(古山堂) 축연(竺 演)의 화풍을 잘 보여주고 있다.","a":"안양암 지장시왕도","c":"문화유산자료","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313491500.jpg"},{"q":"건칠불(乾漆佛)이란, 흙으로 대체적인 형태를 만들어 그 위에 종이나 삼베를 입히고, 칠을 바르고 말리는 과정을 반복하여 일정한 두께를 얻은 다음, 정교한 조각이 필요한 부분에 석고 등을 입혀 조각한 후 표면에 채색을 하거나 도금을 하여 완성한 것을 말한다. 계주(髻珠)가 표현되어 있는 이 불상의 육계(肉髻)는 낮고 큼지막하며 머리와의 경계가 불분명하다. 이마 한가운데 백호(白毫)가 뚜렷하며, 내려감은 두 눈과 작지만 꼭 다문 입술은 명상에 잠긴 듯한 모습을 하고 있다. 무릎 위로 내린 두 팔의 양손은 결실된 상태이다. 건칠불의 경우, 양손을 별도로 만들어 끼워 넣는…","a":"건칠여래좌상","c":"시도유형문화유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111915233400.jpg"},{"q":"조선 중기 문신인 죽창 ○○○의 충절과 공덕을 기리기 위해 세운 ○○○이다. ○○○은 인조 2년(1624) 문과에 급제하여, 같은 해 이괄의 난이 터지자 인조임금을 모시고 공주까지 수행하였다. 그 뒤 성균관전적, 사헌부장령, 봉상시정 등의 벼슬을 지냈다. 인조 14년(1636) 병자호란이 일어나자 강화로 들어갔다가 강화가 함락되자 하인에게 자기를 매장하도록 부탁한 후 목을 매어 자결했다. 후에 이조판서에 추증되었으며, 나라에서 ‘충목(忠穆)’이라는 시호를 내렸다. 앞면 1칸·옆면 1칸 규모이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○ 4면에…","a":"이시직공정려각","c":"문화유산자료","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659743.jpg"},{"q":"○○○○는 석가여래부처 당시에 부처의 이모였던 마가파도파제 부인이 부처께 금색의(金色衣) 또는 ○○○○를 한 벌 지어 올린데서 유래한 것이다. 이 때부터 ○○○○ 또는 금색의는 국가적인 차원에서 열리는 큰 행사에서 당대 최고의 고승인 증명법사(證明法師) 한 사람만 입는 법의였다. ○○○ 창건주인 고 철우선사(鐵牛禪師)의 ○○○○는 철우선사의 스승인 혜월선사(慧月禪師)에게서, 또 혜월선사의 스승이며 당대 고승인 경허선사(鏡虛禪師)에게서 전수된 것으로 여겨진다. 경허선사는 1898년 봄 가야산 해인사 조실로 초대 받고 해인사에 계시던 중 그 해 가을에 국왕의 칙명으로 추…","a":"구미금강사금란가사","c":"시도민속문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658896.jpg"},{"q":"이 건물은 광주 근대사학의 효시인 ○○○○○가 당시 학교 인가를 목적으로 1928년에 신축한 ○○○으로 광주에 남아 있는 체육시설 가운데 가장 오래된 것이며 1945년 전남대학교 의과대학에서 교사(校舍)로도 사용한바 있다. 붉은 벽돌로 건축되었으며, 독특한 박공지붕(지붕면이 양쪽 방향으로 경사진 ㅅ자 모양의 지붕), 왕대공 트러스(큰 외부하중을 지지하는, 긴 기둥간격을 가진 구조물)인 산형구조물의 중앙에 수직재가 있는 구조물 등은 당시의 건축 양식과 기술을 후세에 전하는 중요한 건축물로서 가치가 높다.","a":"광주수피아여자고등학교 소강당","c":"문화유산자료","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659684.jpg"},{"q":"범어사 북쪽 금정산 정상 부분의 화강암 절벽 위에 새긴 높이 12m의 거대한 불상이다. 가는 선으로 불상을 새겼는데 지금은 오랜 비바람으로 손상이 심하게 된 상태이다. 머리 위에는 상투 모양의 머리묶음이 둥글게 솟아 있으며, 귀는 어깨까지 길게 늘어져 있다. 얼굴은 네모진 형태이고 활 모양의 가는 눈, 큰 코 등이 토속적인 인상을 준다. 옷은 오른쪽 어깨를 드러낸 채 입고 있으나, 가슴 아래부분은 많이 닳아서 자세히 살펴보기 어렵다. 토속적인 지방색이 느껴지는 모습, 가는 선으로 불상을 만든 점 등에서 고려시대에 만들어진 작품으로 보인다.","a":"양산 가산리 마애여래입상","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641452.jpg"},{"q":"안성시 대덕면 죽리 외평마을 입구 당산나무 옆에 위치한 석불상이다. 현재 높이 2.35m의 크기로 무릎 이하는 땅에 묻혀 있다. 불상은 광배(光背 ; 붓다의 몸에서 나오는 성스러운 빛을 형상화한 것)와 한 돌로 조성되었다. 방형의 얼굴에 높은 육계(肉髻 ; 상투 모양으로 솟은 붓다의 정수리, 지혜를 상징)와 보주형의 정상계주(頂上髻珠 : 붓다의 육계 위에 표현된 보배구슬)를 표현하였다. 둥글고 큰 눈에 비하여 코와 입은 매우 작다. 짧은 목에 삼도(三道 ; 불상의 목에 표현된 세 줄의 주름으로 지혜를 상징)를 나타냈으며 목이 짧으므로 귀가 어깨에 닿았다. 양어깨를 덮…","a":"안성죽리석조여래입상","c":"문화유산자료","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660204.jpg"},{"q":"○○○○○에 보존되어 있는 그림으로, 불경 중 하나인 『우란분경』의 내용을 그림으로 설명한 것이다. 비단 바탕에 채색하여 그렸으며 가로 218.5㎝, 세로 225㎝의 크기이다. 화폭의 윗부분에는 극락의 아미타여래 일행이 지옥 중생을 맞이하러 오는 장면, 즉 아미타불·관세음보살·대세지보살 등 6여래와 지장보살이 지옥의 중생을 극락으로 인도하기 위해 온 모습과 이들을 정토로 인도하는 인도왕보살 및 수레를 그려 놓았다. 이들 주위로는 오색 구름이 둘러싸여 천상세계와 지옥세계를 구분하는 역할을 하고 있다. 가운데부분에는 중앙부에는 2구의 아귀를 특히 강조하여 크게 그렸고,…","a":"은해사백흥암감로왕도","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641045.jpg"},{"q":"전라남도 광양시 진월면 ○○○ 해발 170m 고지에 자리잡고 있고, 지도상에는 봉임산성(鳳任山城)으로 표기되어 있다. 산성의 총 길이는 100m이고, 면적은 1,422㎡, 너비는 520㎝로 동서축으로 긴 타원형을 하고 있다. 축조 시기는 삼국시대부터 있었다는 설과 임진왜란 시기에 쌓았다는 설이 있으나, 산성의 형식과 축조 기법으로 보아 백제시대에 축조되었을 가능성도 있다. 산 정상부의 일정한 공간을 둘러싸고 있는 테뫼식 산성이고 성벽의 안팎을 모두 돌로 축성한 내외협축식 산성이다. 다른 산성에 비해 정비가 잘 되어 있고 내벽의 경우 남쪽 일부분이 허물어졌지만 9단의…","a":"광양진월신아리보루","c":"문화유산자료","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662317.jpg"},{"q":"○○○○○는 선사시대 유적이 다수 분포해 있고 백제시대 이래 고려시대까지 정안현-○○부-회주목으로 이어지는 고을이 있던 지역이다. 고려시대 말기에 왜구로 인해 치소를 옮긴 뒤, 고읍으로 불리게 되며 임진왜란이 지난 뒤 ○○위씨가 입향하여 집성촌을 이룬다. 전통 반가는 물론 사당과 서재를 갖추고 있고 존재 위백규 등 학자들이 활동하여 문집, 고문서, 전적류와 민속문화유산이 잘 남아 있다. 이러한 역사 전통을 가진 ○○○의 입향 선조가 초기에 정착한 현 ○○○○의 터는 역사공간으로서도 의미가 있고, 1905년에서 1907년 이전에 지어진 것으로 확인되어 방촌에 소재한 현…","a":"장흥 방촌리 근암고택","c":"시도민속문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2020031014182000.JPG"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리. 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 현재 남아 있는 신산 ○○○○ 성벽의 길이는 약 600m이다.","a":"신산환해장성","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657927.jpg"},{"q":"○○○은 조선 세종 때 단성현감을 지낸 윤자선이 1450년 하향하여 이곳에 정자를 건립하고 산수를 즐기며 강학하덕 곳임. 건물은 정면 4칸, 측면 2칸으로 전면에 툇마루를 두고 좌측 2칸은 대청, 우측 2칸은 방으로 구성되어 있고, 계자난간이 있는 누마루 형식으로 되어있음. 전체적으로 정자의 규모와 내외부의 공간구성이 주변의 자연경관에 잘 조화된 목조와가 건물임. 또한 이곳은 1919년 지방 유림들이 이 곳에 모여 \"파리장서거사\"를 의논한 곳이며, 현 ○○ 초등학교의 전신인 창남의숙을 세워 교육하던 곳임. 건물 옆에는 윤공의 유허비가 있으며 파평 윤씨의 자손과 외손,…","a":"거창 심소정","c":"문화유산자료","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663943.jpg"},{"q":"○○○○이란 석가모니가 인도에 있는 영취산에서『법화경』을 설한 법회모임을 말한다. 그러나 시대를 지나면서 ○○○○의 개념은 석가의 설법자체를 의미하는 것으로 바뀌었다. 이 그림은 ○○○○을 이 땅에 실현하고자 하는 강한 신앙심의 구체적 표현이기도 하다. ‘○○○○○’는 대웅전이나 영산전의 불상 뒤편에 봉안되는 것이 보통이다. ○○○○은 일반적으로 석가여래를 중심으로 좌우에 2대 또는 4대·6대·8대 보살과 10대 제자, 불법을 지키는 선신들로 구성된다. ○○○ 대웅전의 후불탱화로 제작된 ‘○○○○○’는 길이 410㎝, 폭 273㎝로, 항마촉지인을 한 석가모니불을 중심…","a":"진주청곡사영산회상도","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642304.jpg"},{"q":"원주 ○○○○○ 소장 ○○○○○참법은 성종 5년(1474) 간행한 원본에 비해 후에 인쇄된 것이나 오래된 고판으로 목판 인쇄기술사를 연구하는 중요한 자료적 가치를 지니고 있다.","a":"원주고판화박물관소장예념미타도량참법","c":"문화유산자료","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660676.jpg"},{"q":"○○○의 영산회괘불탱(국보 제302호)을 보관하는 함이다. 영산회괘불탱은 석가모니가 영취산에서 법화경을 설법하는 장면을 묘사한 그림으로 9구의 불·보살이 그려져 있다. 중앙에 석가불이 화면을 가득 채우며 서 있고 좌우에 문수보살과 보현보살이 연꽃가지를 들고 서 있으며, 그 뒤쪽으로 석가의 2대 제자인 가섭과 아난이 배치되어 있다. 조선 경종 2년(1722) 의겸스님이 제작한 것으로, 석가불 얼굴의 묘사 기법과 의복의 묘사에 가해진 기법 등은 당시 불화의 특징을 잘 보여준다. ○○○은 두꺼운 목판을 이용해 튼튼하게 제작하였는데, 각 모서리마다 금속장식을 붙이고, 옮기기…","a":"진주청곡사괘불함","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642087.jpg"},{"q":"비슬산 ○○○는 통일신라 신덕왕 원년(912)에 보양국사가 처음 지었다고 전한다. 조선 세종 1년(1419)에 천일대사가 다시 지었고, 임진왜란으로 불탄 것을 여러 해에 걸쳐 다시 지었다. 이렇게 지어진 건물은 200여 칸이 넘고 승려도 500여 명이나 되는 큰 절이었다고 한다. 아미타불을 모신 ○○○은 영조 4년(1728)에 다시 지었다. 앞면 3칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 간결한 맞배지붕집이다. 지붕처마를 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 배치된 다포 양식으로 조선 후기 건축 양식을 잘 보존하고 있는 건물이다…","a":"용연사 극락전","c":"시도유형문화유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636919.jpg"},{"q":"영산 동쪽 밀양으로 가는 도로 옆에 있는 10여 기의 무덤들이 분포하는 곳이다. 구조는 네모꼴이며 네 벽면은 자연석으로 쌓았다. 판돌로 덮인 천장은 다른 지방과 같으나 돌방 안쪽이 폭이 좁고 길이가 길며 비교적 높은 것이 특징이다.","a":"창녕 영산고분군","c":"시도기념물","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656050.jpg"},{"q":"병인양요(1866) 때 프랑스군을 물리쳐 승리를 한 ○○○ 장군의 공적을 기리고 있는 비이다. 프랑스는 조선 고종 3년(1866) 10월 천주교 탄압을 구실 삼아 극동함대 소속 군함 7척으로 우리나라를 침입하였는데 당시 순무천총 ○○○ 장군이 정족산성에 포수 500여 명을 매복 시켰다가 밤에 기습 공격하여 물리쳤다. ○○○ 장군은 헌종 4년(1838) 무과에 급제하여 선전관이 되었고, 병인양요 때 공을 세워 한성부 좌윤으로 특진되었으며 부총관·금위·어영 등을 거쳐 형조판서·금위대장·공조판서 등을 역임하였다. 비는 긴 직사각형으로, 윗변을 둥글게 다듬었다. 고종 10년…","a":"양헌수 승전비","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645638.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로, 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. ○○○○○은 포구의 방파제 부근에 1기, 북서쪽 바닷가에 1기 등 모두 2기가 있는데, 그 중 방파제 부근인 남쪽 포구에 있는 탑으로 ‘큰개탑’,‘생이탑’이라 부르기도 한다. 탑이 포구 밖 암반 위에 놓여 있어 하단부는 물에 잠길 때가 많다. 탑의 상단부는 50㎝ 정도가 오목하게 패여 있어 새가 자주 앉기도 하는데, 음탑(陰塔)을 뜻하는 것이라 한다.","a":"신흥리방사탑1호","c":"시도민속문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659269.jpg"},{"q":"도상 구성이나 배색의 상태 등으로 미루어 보아 19세기 작품으로 백군, 양록을 사용해 화면의 화사함을 더하고 인물의 다양한 묘사가 돋보이는 근대에 조성되는 신중도의 과도기적 특징을 보여주는 중요한 자료임","a":"사천 백천사 신중탱","c":"문화유산자료","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666709.jpg"},{"q":"이 불상은 광진구 광장동 ○○○에 봉안되어 있는 ○○○○○으로 원래 불상 전체에 두껍게 호분이 발라져 있었으나, 최근에 호분이 벗겨진 뒤에 원래의 모습이 드러나게 되었다. 전체적으로 머리가 큼직하고 신체가 날씬한 ○○○○○으로 머리가 신체에 비해서 높고 큼직하며, 육계도 유난히 큰 것이 특징이다. 머리와 육계 앞면이 다소 깨어졌지만, 머리칼은 소발(素髮)로 표현된 것을 알 수 있다. 얼굴은 사각형에 가깝게 넓지만 양감이 부드럽고 유연하며 눈, 코, 입이 단아하고 미소를 띠고 있어서 원만하게 보인다. 귀는 적당하게 길지만 앞 머리카락 한 줄이 내려와 귀의 중심을 가로…","a":"상부암 석보살입상","c":"시도유형문화유산","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636478.jpg"},{"q":"분 류 유물 / 불교회화/ 탱화/ 불도 수량/면적 1폭 지정(등록)일 2005.12.27 * 명칭변경(○○○ 석가모니후불탱 →○○○○○), 변경사유 : 동일성격문화유산 명칭통일 소 재 지 부산 강서구 명지동 445 시 대 일제강점기 소유자(소유단체) ○○○ 관리자(관리단체) ○○○ 상 세 문 의 부산광역시 강서구 문화체육과 051-970-4065","a":"청량사 영산회상도","c":"문화유산자료","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659382.jpg"},{"q":"복전암(福田庵)에서 ○○○성으로 오르는 등산로를 따라 1㎞쯤 올라간 곳에 위치한 높이 약 6m의 바위 남쪽에 새겨진 ○○○○○이다. 일명 '장수부처'라고 불린다. 두광(頭光)과 신광(身光)을 지니고 연화대좌 위에 앉은 부처를 얕은 부조(浮彫)와 선각(線刻)으로 새겼는데, 얼굴과 어깨부분은 얕은 부조기법으로 입체감을 살렸으며 그 아래 부분은 선각에 가깝게 처리하여 마치 바위에 그림을 그린 것 같다. 불상의 머리 위쪽의 바위가 균열되면서 머리의 오른쪽(향좌) 나발(螺髮)이 일부 떨어져 나간 것을 제외하고는 보존 상태는 양호한 편이다. 이목구비는 큼직한 편으로, 깊게 패인…","a":"보문산마애여래좌상","c":"시도유형문화유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637207.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위하여 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련한 초소이다. 대개 높은 평지에 쌓아두는데, 밖은 성곽으로 높게 하고, 안은 낮게 하여 포를 설치해 두는 시설물이다. 이 돈대는 높이 2.2m, 둘레 128m의 규모로, 성곽은 돌을 이용해 직사각형으로 쌓고, 해안쪽을 향해 4개소의 포좌(포놓는 자리)를 설치해 놓았다. 성곽 위에는 몸을 숨길 수 있도록 낮게 쌓았던 담의 흔적만 남아 있다. 출입구는 윗부분이 무지개 모양을 이루고 있어 다른 돈대와는 다른 독특한 모습이다. 조선 숙종 5년(1679) 윤이제가 ○○…","a":"강화 미루지돈대","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645647.jpg"},{"q":"○○○○ 내 안국사 경내 남쪽 축대 아래에 있는 ○○○○에는 인조21년(1643) 이조판서겸 대제학인 이식(李植)이 왕명으로 사고를 순찰하고, 정축란 이후 문란해진 사고의 관리와 성내의 방비를 철저히 하기 위하여 왕에게 진상(秦上)하여 1645년 ○○○○를 창건하게 된 경위가 기록되어 있다. 고종 35년(1898) 간행된 적성지(赤城誌) 고적조(古迹條)에 비문의 전문이 게재되어 있다. 대리석으로 만든 비는 이면비(二面碑)로 전체 높이는 1.78m이다. 직사각형 모양을 한 비석의 받침돌로 사면에 안상(眼象)을 배치하고, 좌우에 구름모양의 무늬를 조각했으며, 중앙에는 4…","a":"적상산성 호국사비","c":"시도유형문화유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639487.jpg"},{"q":"하나의 화강암을 끝이 뾰족하게 다듬어 부처의 몸에서 나오는 빛을 형상화한 광배(光背)를 만들고, 그 위에 ○○○○을 돋을새김한 것이다. 둥근 얼굴에 살짝 감은 눈, 잔잔한 미소를 띤 입, 길게 늘어진 귀에서 원만한 인상을 풍기고 있다. 옷은 양 어깨에 걸쳐서 입고 있는데, U자형의 옷주름이 무릎까지 이어지고 있다. 오른손은 가슴까지 들어 손바닥이 밖을 향하고 손가락이 위로 향하고 있으며, 왼손은 손가락이 아래로 향하고 있다. 둥근 어깨와 양감있는 가슴, 잘록한 허리의 굴곡 등에서 통일신라시대 불상의 사실적인 모습이 나타난다. 이 불상은 통일신라시대 불상 양식의 전통을…","a":"나주만봉리석조여래입상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639906.jpg"},{"q":"이 ○○○○은 원래 전라감영에서 서적을 간행할 때 사용하였던 것으로 전라감영 내에 보존․관리되고 있었으나 1899년 당시 전라관찰사이었던 조한국의 명으로 전라감영 내에 분산되어 있던 책판을 모아 ○○○○에 보존하게 되었다. 1920년대에 책고를 지어 관리해 오다가 1987년 전주시에서 장판각을 건립하고 목재로 서가를 만들어 오늘에 이르고 있다. 장판각에 소장된 ○○○○은 총 5,059개에 9,830면이 서각되어 있으며, 서각되지 않은 면수는 288면이다. 이들 목판의 책판 종류는 자치통감강목(1,775개), 동의보감(151개), 주자대전(1,471개), 율곡전서(49…","a":"전주향교소장완영책판","c":"시도유형문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639778.jpg"},{"q":"무주군 무주읍 읍내리 ○○○ 극락전에 봉안되어 있는 ○○○○○은 조성 당시인 1657년(효종 8)의 복장 발원문 외에 1736년(영조 12)과 1928년 중수 발원문을 살펴보면, 1657년 4월 조성하기 시작하여 5월에 완성된 후, 덕유산 운수암 극락전에 봉안되었고, 1736년에 경월사로 옮겨졌다. 1736년 3월 21일에 중수 개금을 위하여 적상산 안국사 보월전으로 이안되었으며, 개금 후 다시 경월사로 옮겨졌다. 1928년에 다시 개금되어, ○○○에 봉안되었다. ○○○○○은 삼존상이 아닌 단독상일 가능성이 높으며, 전라도 지역에서 주로 활동하던 숭일(勝一)을 수화사…","a":"북고사 목조아미타여래좌상","c":"시도유형문화유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639672.jpg"},{"q":"구한말 유학자인 심산 ○○○ 선생의 생가이다. 선생은 구한말 유학자이며 독립운동가이고 정치인으로 경상북도 성주 출신이다. 1905년 일제에 의해 강제로 을사조약이 체결되자 이승희와 함께 상경하여 상소를 올리고 이완용을 비롯한 매국오적을 성토하였다. 3·1운동이 일어나자 130여명의 연명으로 한국 독립을 호소하는 진정서를 작성하여 만국평화회의에 보내기도 하였다. 1953년 전국에 흩어져 있는 향교 재단을 규합하여 성균관 대학의 종합대학 승격을 인가받고 성균관대학교 초대 총장에 취임하였다. 저서로 시문집인 『심산만초』와 『벽옹만초』 등이 있다. 생가는 선생이 22세 되던…","a":"심산김창숙생가","c":"시도기념물","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654536.jpg"},{"q":"윤사형이 아들 윤무에게 노비,전답을 별급한 문기. 윤사형이 장손 윤여경의 생자를 기념하여 노비전답을 별급한 문기. 정밀의 첩 량정이 남편에게 자신 소유의 노비를 기상하는 문기 김몽린이 4자녀와 첩에게 재산을 분급하는 분급문기. 이중에 사위 문현도 있음 정밀이 아들 승업, 승훈에게 재산을 분급하는 분급문기. 정밀이 아들 승업, 승훈에게 재산을 분급하는 분급문기. 처변재산 중 토지를 분급. 정승업, 승훈 형제의 화회○○○. 모변 재산중 노비 분재. 하위보의 자 하증 등 5형제가 합의하여 재산을 나눈 문기. 하증이 아우 하협의 처 진양정씨에게 노비, 전답을 별급하는 문기…","a":"분재기","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642726.JPG"},{"q":"머리는 나발(螺髮)이고 육계(肉髻)가 솟았다. 얼굴은 둥글고 귀가 상대적으로 크고 이목구비(耳目口鼻)가 거의 남지 않았으며, 어깨는 좁고 밑으로 흘러 내려졌다. 수인(手印)은 시무외․여원인(施無畏․與願印)으로 오른손이 들려있고 손 부분은 파손되었으며, 왼손은 내려져 있으며 손끝이 뭉특하다. 법의는 통견이고 옷주름은 U자형으로 목부터 다리 발목부위까지 주름이 있다. 좌대는 입상 바로 아래 앙련(仰蓮)이 작게 조각되었고, 그 밑에 복련(覆蓮) 8면이 크게 조각되어 있고, 맨 밑에 8화형 받침이 있으며, 좌대는 밑부분이 뚫려있다. 전체적으로 색깔은 흑색이고 녹청색 녹과 먼…","a":"강릉 청학사 소장 청동불입상","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660652.jpg"},{"q":"김천일 선생의 6대손인 통정대부 초은 김상락 공이 고종 27년(1890) 후진을 양성하기 위해 세운 학당이다. 조선 후기 건물로 일선 김씨 초은파 5대에 걸쳐 공부하였으며 100년간 300여명을 가르쳤다.","a":"합천 도천재","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664514.jpg"},{"q":"남명 조식(1501∼1572)의 학문과 사상을 이해하고 추모하기 위하여 그를 향사하고 있던 ○○○○의 묘정에 세웠던 비석이다. ○○○○은 1576년 가회면의 회현(晦峴) 아래 세워졌다가 임진왜란 때 불탄 회산서원(晦山書院)의 후신으로, 1601년 봉산면에 세워졌던 향천서원(香川書院)이 1609년 사액되면서 얻은 명칭이다. 이 ○○○는 조선 순조 12년(1812)에 세워진 것으로 가로 80㎝, 세로 180㎝, 폭 25㎝이다. 비의 형식은 거북 모양의 비석 받침돌 위에 태극무늬의 직사각형 비몸을 세우고 머릿돌을 얹은 모습이다. 비문은 우암 송시열(1607∼1689)이 지…","a":"합천 용암서원 묘정비","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664752.jpg"},{"q":"만치당 김수남(1576∼1636)의 충절을 기리기 위해 세운 서원이다. 김수남은 조선 중기 문신으로 임진왜란 때 조정을 따라 강화도로 피난하였으나 그곳에 적군이 침입하자 순절하였다. 이 서원은 숙종 13년(1687) 가야곡면 조정리에 송시열, 송준길이 세웠는데 숙종 16년(1690)에 지금 있는 자리로 옮겼다. 정조 5년(1781)에는 매죽헌 성삼문과 송재 조계명의 위패를 추가로 모셨다. 그 뒤 고종 5년(1868)에 흥선대원군의 서원철폐령으로 서원이 철거되자 제단을 마련해 모시다가 1977년 사우를 세워 오늘에 이르고 있다. 위패를 모시고 있는 사우에서는 해마다 음…","a":"금곡서원","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661010.jpg"},{"q":"이 불상은 ○○○에 봉안되어 있는 고려 후기의 ○○○○이다. 현재 상의 전체크기는 143cm 이지만 원래는 지금의 광배보다 긴 주형거신광배(舟形擧身光背)에 얕은 부조로 ○○○을 새긴 상이었을 것으로 추정된다. 이중 원으로 이루어진 두광(頭光)과 신광(身光)에는 초화문(草花紋)이 새겨져 있어 장식성을 느낄 수 있다. 머리 위에 동그랗게 새겨진 육계는 작은 편이며, 거의 원형에 가까운 둥근 머리에는 짧은 귀가 표현되었고 역시 아주 동그란 얼굴에 이목구비가 얕게 새겨져 있다. 목은 길고 삼도(三道)가 뚜렷하게 나타나 있고, 두부에 비해서 좁고 각이 진 어깨위에 통견식(通肩…","a":"환희사 석불입상","c":"시도유형문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593348.png"},{"q":"조선시대 만들어진 높이 107㎝, 입 지름 73㎝의 종이다. 종을 메다는 고리는 용이 여의주를 갖고 있는 형상이며, 옆으로 소리 울림을 도와 주는 음통이 있다. 종 윗부분에는 꽃무늬로 띠를 두르고, 아래 구슬 모양의 돌기가 한 줄 돌려 있다. 밑으로는 8개의 원을 양각하여 그 안에 범자를 새겨 넣었다. 몸통의 중심에는 머리 뒤에 둥근 광배를 두르고 보관을 쓴 보살 입상과 전패(殿牌)가 있고, 보살 입상 사이에는 사각의 유곽을 배치하였다. 유곽 안에는 9개의 꽃무늬로 된 유두가 있다. 종의 가장 아랫부분에는 덩굴무늬를 두르고 있다. 동종에 씌여있는 글을 통해 숙종 42…","a":"송광사동종","c":"시도유형문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639600.jpg"},{"q":"수산진은 조선시대 제주의 대표적인 방어유적으로 3성(三城) 9진(九鎭)에 속하며 정의현 관할이었다. 이 성은 세종21년(1439) 목사 한승순에 의해 처음으로 축성되었으나, 임진왜란 때 목사 이경록에 의하여 성산으로 잠시 이설되기도 했다. 선조 32년(1599) 목사 성윤문에 의하여 다시 복원되었다. 성곽 둘레 1,164척(352.72m), 높이 16척(4.84m)이며, 동쪽과 서쪽에 각각 문이 있었다. 현재 도내 9진 가운데 비교적 원형에 가깝게 보존되어 있으며, 성 서쪽과 북쪽 모서리에는 치성 일부가 남아 있기도 하다. 성 내부 북북동쪽에는 성을 축조할 때 부역을…","a":"수산진성","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658011.jpg"},{"q":"놋쇠로 만든 시루로, 시루는 떡이나 쌀 등을 찔 때 쓰는 주방 기구이다. 현종 3년(1664)에 제작된 이 시루들은 187자의 글자가 새겨져 있어 제작장소, 제작시기, 시주자 등 시루의 제작과정을 알 수 있다. 또한 시루를 제작할 즈음에 ○○○의 주지를 지낸 스님들의 이름 등도 써 있어 당시 ○○○의 상황을 파악하는데 좋은 자료이다.","a":"범어사명 유제시루","c":"시도유형문화유산","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636686.jpg"},{"q":"○○○○은 대승불교에서 가장 사랑받아 온 보살 중 하나로, 중생의 구제와 관련하여 중요하게 인식되었기 때문에 오랜 시간 동안 널리 신앙되었고 그 상 또한 많이 조성되었다. 이 상은 중국 明나라 때 만들어진 ○○○○○으로, 이중연화좌(二重蓮花座)위에 오른쪽 다리는 세우고 왼쪽 다리는 가부좌를 한 윤왕자(輪王座)를 취하고 있다. 머리에는 연주문(連珠文)띠를 두른 보관(寶冠)을 쓰고 있는데, 훼손이 심하지만 본래 화불(化佛)이 있었을 것으로 추정된다. 머리 위에 살짝 얹는 형식으로 양 측면에서 시작한 끈을 뒤에서 묶는 독특한 형식이다. 이마에는 백호(白毫)가 뚜렷하다. 부…","a":"청동관음보살좌상","c":"시도유형문화유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111914302100.jpg"},{"q":"조선 명종 1년(1546)에 김응생이 고향의 후진교육을 위해 자양면 노항동에 지은 서당이다. 지금의 건물은 후대에 다시 지은 것으로 보인다. 1976년 영천댐 건설로 인하여 지금의 위치로 옮겨지었는데, 이때 건물 주위에 담장을 두르고 문을 세웠다. 학생들이 모여 글을 읽는 대청마루와 생활을 위한 방 만으로 평범하고 소박하게 꾸며져 있다. 일반적인 서당건물에는 앞쪽에 따로 내어 단 툇간이 있으나, ○○○○에는 없다. 서당 안에는 퇴계 이황이 직접 쓴 현판이 걸려있다. 한편 동린각에 충무공 이순신과 함께 모셔져 있는 김완 장군은 김응생의 셋째 아들이다.","a":"자양서당","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640376.jpg"},{"q":"○○○○은 추담 윤선(1559∼1640) 선생의 공적과 학덕을 기리고 충효정신을 선양하기 위하여 무오년(1918)에 건립되었다. 윤선 선생은 선조에서 광해군의 양대에 걸쳐 대사간, 대사성, 도승지, 의정부 우참찬 등을 역임하였으며, 청백리에 녹선되었다. 선생의 위패는 ○○ 임란창의사에 봉안되어 매년 5월 10일 향사를 지내고 있다. 뒤쪽 경사지형에 대문채와 서당을 일직선상에 배치하고 강당의 좌·우에 동·서재를 앉힌 ‘口’자형 배치형식이며 정면과 측면의 일부에 담장을 둘렀다. 서당은 정면 6칸, 측면 2칸의 전·후툇집으로 실의 구성은 가운데 2칸의 대청을 중심으로 좌측…","a":"합천 회계서당","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664881.jpg"},{"q":"조선 전기 문신이자 5현 중의 한 사람인 일두 ○○○의 문집을 새긴 책판이다. ○○○은 김굉필과 김종직의 문인으로 무오사화 때 종성으로 유배되었다. 그리고 갑자사화 때에는 부관참시(部灌斬屍:죽은 시체에 형을 가함)를 당하였다. ○○○은 당시 성리학의 대가로 경사(經史)에 통달했으며 역행실천을 통해 많은 독서를 했으나 사화 때문에 저술이 거의 전하지 못하고 있다. 다만 얼마되지 않은 유집만 전할 뿐이다. 이 문집은 정구(鄭逑)와 ○○○의 증손자 정수민이 함께 수집·검수한 것을 인조 13년(1635)에 처음 발행하였다. 이어 영조 19년(1743)에 도암 이재(李縡)가…","a":"정여창 일두문집 목판","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641767.jpg"},{"q":"○○○<靈隱寺>는 [공산지]에 의하면 조선 세조 4년(1458)에 지은 사찰이며 광해군 8년(1616)에는 이곳에 승장<僧將>을 두어 전국의 사찰을 두어 전국의 사찰을 통치하였다는 기록이 있다. 현재 ○○○ 내에는 주불전인 원통전<圓通殿>과 강당인 관일루<觀日樓>가 있다. 원통전은 정면 3칸, 측면 2칸으로 기둥 위에는 보를 받치고 장식도 겸해 새날개 형태의 부재<部材>를 짜맞춘 익공계의 맞배지붕을 하였다. 규모는 21m로 현재의 건물은 1933년 12월에 보수하였다. 관일루는 처마의 하중을 받고 장식도 겸해 나무쪽을 짜맞춘 공포를 기둥 위에만 배치한 주심포 계통의…","a":"영은사대웅전","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660953.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓는 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 제주대학교 사범대학 부속고등학교 운동장 남쪽에 있는데, 고인돌의 남서쪽을 제외한 주위가 흙과 잡석으로 묻혀 있다. 형태는 바둑판식이나 덮개돌 밑에 여러 매의 넓고 납작한 돌을 둘러 돌방을 만들어서 개석식으로 재분류된다.…","a":"용담지석묘1호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657652.jpg"},{"q":"동야공 김양근(1734∼1799)이 태어나 공부하였던 곳으로 그의 호를 따서 ‘○○○○’이라 하였다. ○○ 김씨 19대손인 김중안이 지었다고 하나 지은 시기를 확실하게 알 수는 없다. 건물은 一자형 사랑채와 Π자형 안채가 있어 트인 ㅁ자형 배치를 이루고 있다.","a":"안동 소산동 동야고택","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658917.jpg"},{"q":"고려의 개국공신 ○○○ 신숭겸 장군의 묘소이다. 평산 신씨의 시조로서, 918년 배현경·홍유·복지겸 등과 함께 궁예를 몰아내고 왕건을 추대하여 고려 건국에 이바지하였다. 태조 10년(927) 대구 공산에서 후백제 견훤의 군대와 싸우다가 태조가 적군에게 포위되어 위급해지자 태조의 옷을 입고 변장하여 맞서다가 전사하였다. 적군이 신숭겸을 태조로 오인하고 그의 목을 베어가자 태조는 머리없는 시신에 금으로 머리를 만들어 장례식을 치루었다고 한다. 도굴을 막기 위하여 묘는 하나인데 봉분을 3개 만들었다고 전해지고 있으며, 현재 이 묘에는 3개의 봉분이 나란히 있다. 묘역에는…","a":"신장절공묘역","c":"시도기념물","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647789.jpg"},{"q":"강원특별자치도 춘천시 강원특별자치도청의 뒷산인 ○○○ 능선에 쌓은 산성으로, 가파른 지형을 이용해서 쌓았다. 원형은 많이 훼손되어 1991년에 105m를 복원하였고, 1993년에 40m를 복원하였다. 『신증동국여지승람』에는 봉산 산성의 둘레는 2,463척이고 높이는 10척이라 기록되어 있다. 『고려사절요』에 의하면 거란족의 침입으로 안찰사 노주한이 이곳에서 전사하였고, 『고려사』에는 몽고족의 4차 침입 때 춘천 주민들이 산성에 들어가 항거하였다는 기록이 있다. 또 임진왜란 때에는 강원특별자치도 조방장(助防將) 원호(元豪)의 활동지역이었으며, 한국전쟁 당시에도 격전지였…","a":"춘천봉의산성","c":"시도기념물","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647851.jpg"},{"q":"○○○○○은 선교사로 광주에서 활동하다 순교한 오웬과 그 할아버지를 기념하기 위해 세워졌다. 2층의 회색 벽돌건물로 평면은 정방형이지만 모서리에 있는 설교단을 중심으로 좌우가 대칭되는 구조이다. 이 건물의 특징은 객석에서 설교단을 내려다 볼 수 있도록 1층 바닥과 2층 발코니를 모서리의 설교단을 향해 약간 경사지게 한 것이다.","a":"오웬기념각","c":"시도유형문화유산","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637168.jpg"},{"q":"현재 강남구 삼성동 ○○○ 진여문(奉恩寺 眞如門) 안에 봉안되어 있는 이 ○○○○ 4구(軀)도 원래는 ○○○ 진여문과 법왕루 사이에 있던 천왕문에 봉안되어 있었으나 천왕문 철거로 현재의 위치에 임시 봉안되게 되었다. 이 ○○○○은 복장물 기록에 따르면 1746년(영조 22년)에 조성되었는데 능창군 이씨(綾昌君 李氏: 선조宣祖의 7子인 인성군仁城君의 증손)와 상궁 박필애(尙宮 朴弼愛) 등 궁중 관련 인물 현상성(賢上城)에서 건달바(乾達婆,Gandharva)와 비사사를 거느리고 동쪽 인간세계 사람들, 특히 국가와 국왕을 보호하는 역할을 한다고 알려져 있다. 이러한 지국천…","a":"봉은사 목 사천왕상","c":"시도유형문화유산","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590263.png"},{"q":"○○○는 만행산에 있는 절로 신라 헌강왕 원년(875) 도선국사가 세웠다고 전한다. 선조 30년(1597) 정유재란 때 불타버려 철불만 남아 있던 것을 영조 30년(1754) 약사전과 명월당을 다시 지었다고 한다. 정유재란 때 타지않고 남은 철제여래좌상(보물 제422호)은 약사전에 모시고 있다. 지금 있는 건물들은 1960년대를 전후로 주지였던 일학이 신도계의 도움으로, ○○○과 명월당을 헌 뒤 그 자리에 명부전을 세우고 석탑과 탑비 등을 마련하여 늘려 지은 것이다. ○○○에는 위봉사 보광명전의 주불을 옮겨 모시고 있다.","a":"선원사대웅전","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661662.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로, 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. ○○○에서 단산으로 가는 길에는 ‘알뱅디’라 불리는 넓은 평지가 있는데, 이곳에 4기의 ○○○이 자리하고 있었다. 마을에 불이 자주 나고 가축이 병들어 죽는다 하여 쌓아 놓은 것인데, 1950년대 훈련소가 들어서면서 군인들이 허물어버려 2기만 남아 있다. 2기 중 동쪽에 있는 것이 이 탑으로, 윗부분이 상당히 무너져 탑 위에 세웠던 석상이 탑 옆에 따로 놓여 있다. 높이는…","a":"인성리방사탑1호","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659278.jpg"},{"q":"경상남도 ○○시 영곡면 원내리 한산사에 모셔진 비로자나불이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위에 상투 모양의 머리묶음이 솟아 있다. 얼굴은 네모에 가까운 타원형이며, 입은 작지만 희미한 미소를 띠고 있다. 신체는 당당한 어깨에 허리가 잘록하여 사실성이 강하다. 손은 왼손 검지를 오른손으로 감싸고 있는 모습으로 비로바나불이 일반적으로 취하는 손모양이다. 대좌(臺座)는 상·중·하대로 구성되었으며 4각형의 하대에는 연꽃무늬가, 중대에는 사천왕상이 새겨져 있다. 9세기 말 10세기 초의 양식을 보여주는 작품이다.","a":"진주 고산암 석조비로자나불좌상","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642015.jpg"},{"q":"운흥사는 신라 진평왕(재위 579∼632)시기, 원효대사가 창건하였다고 전한다. 이후 고려 말 지공대사가 중건하였으나, 임진왜란 때 소실되었고, 1614년(광해군 6)에 대희선사가 재건하였다. 『조선왕조실록』,『신증동국여지승람』등에 운흥사에 관한 기록이 남아있다. 그러나 1749년(영조 25)『학성지』의 기록에 의하면 이미 폐사되고 없었으므로, 그 이전에 폐사되었을 것으로 추정된다. 조선시대 운흥사는 불교 경판의 간행으로 유명하였는데 1672년부터 1709년까지 많은 불경 간행이 이루어졌다. 대부분의 사찰 불경목판은 발문(跋文)이 있고, 권말에 간행연월일과 간행장소,…","a":"운흥사지","c":"시도기념물","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645924.jpg"},{"q":"○○○는 신라 무열왕때 의상조사가 창건하여 웅정암이라 하였으나 임란때 소실한 후 1603년 지조와 원찬이 중창하고 이름을 ○○○로 바꿨다. 그후 조선 영조 50년(1774) 중수하여 오늘에 이르고 있으며, 유적 유물로는 대웅전과 명부전, ○○○, 요사채 2동 등이 있다. ○○○ 규모는 정면3칸, 측면 2칸이며, 구조는 중층 누각에 익공계 팔작집이다. 상하층은 벽 없이 사방이 트여 있고, 대웅전 앞 중정에서 진입할 수 있게 후면 어칸에 통로를 내어 출입하고 있다. 현재 ○○○ 좌우로는 대웅전 영역으로 접근하는 통로가 있다. 상층에는 사방으로 계자각헌함을 돌리고 내부 바…","a":"영천 영지사 범종각","c":"문화유산자료","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051421555100.JPG"},{"q":"전라남도 순천시 주암면 ○○○에 있는 이 ○○○○은 현재 개인 소유의 밭 가운데 위치하고 있다. 둥근 얼굴은 비교적 원만한 모습으로, 눈은 약간 위로 치켜 뜨고 있고 입은 작게 표현되어 있다. 귀는 유난히 얇아져 뒤로 바싹 붙어 있으며, 신체에 비해 두꺼운 목에는 3개의 주름인 삼도(三道)가 희미하게 새겨져 있다. 양 어깨에 걸치고 있는 옷는 가슴 아래에서 U자형으로 퍼져 나갔으며, 오른팔 아래에서 띠매듭이 지나간 형식이 있는 점이 특이하다. 두 손은 아래로 내려 손바닥이 밖을 향하고 있는데 오른손이 너무 과장되게 조각되어 균형을 잃고 있다. 목 부분이 신체 부위에…","a":"창촌리석불입상","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661982.jpg"},{"q":"한국전쟁 중 UN군에 포로가 되었던 공산군을 수용하던 장소이다. 1950년 11월부터 고현·상동·용산·양정·수월·해명·저산지구 등 360만평에 ○○○○○를 설치하여, 인민군 15만, 중공군 포로 2만, 여자포로와 의용군 3천명 등 최대 17만 3천명을 수용하였다. 이 곳에서 반공포로와 친공포로간의 유혈사태가 자주 발생하였으며, 1952년 5월 7일에는 ○○○ 소장인 돗드 준장이 납치되는 불미스런 사건까지 있었다. 1953년 7월 27일 휴전협정 후 폐쇄되었고, 친공포로들은 판문점을 통하여 북으로 보내졌다. 현재는 ○○○의 잔존건물 일부만이 곳곳에 남아 당시의 상황을…","a":"거제포로수용소","c":"문화유산자료","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664043.jpg"},{"q":"한개마을 북쪽 영취산 기슭에 자리잡고 있는 한옥으로 대문에서 내려다 보이는 가옥 경치가 눈길을 끄는 곳이다. 1911년 이전희씨가 지은 집으로 가묘와 별당은 1930년에 늘려 지은 것이다. 집 이름은 이전희씨의 부인이 초전면 월곡동에 시집왔다하여 붙였다고 한다. 건물들은 대문채, 안채, 사랑채, 중문채, 고방채, 사당 등으로 구성되어 있다. 정침이 一자형을 갖추고 있고 아래채, 고방채, 중문채 등은 튼 ㅁ자형으로 배치되어 있다. 대문채는 남쪽에 있으며 안채의 공간 구조는 규칙적이고 정교하다. 가장 넓은 터를 차지하고 있는 사랑채는 안채와 달리 담과 건물들의 선이 틀에…","a":"대산동월곡댁","c":"시도민속문화유산","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658645.jpg"},{"q":"『성호선생문집』책판은 조선 후기 우리나라 문화와 사상사에 하나의 신기원을 이룩한 실학자인 성호 ○○의 방대한 문집을 ○○에 새겨 발행한 것으로, 총 27책 800여 장으로 여주 이씨 문중의 천연정에서 간행되었다. ○○은 둘째형 이잠이 장희빈을 두둔하는 상소를 올렸다가 47살의 나이로 옥에서 죽자, 과거에 나아갈 뜻을 버리고 평생을 조상들의 묘가 있는 안산의 첨성리에서 살았다. 그의 학문은 철저하게 유교적인 기반 위에서 이루어진 것이었으나, 당시의 세계관과 역사의식이 확대되면서 자기나라에 대한 새로운 인식과 실증적인 태도를 갖추었다. 양반도 생산적인 일에 직접 종사해야…","a":"이익 성호문집 목판","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641785.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생의 행적을 기리고 있다. ○○○은 선조 22년(1580) 문과에 급제하여 승문원에 등용되었다. 임진왜란(1592), 이봉학의 난(1596), 이괄의 난(1624) 당시 큰 공을 세웠으며, 생을 마친 후에는 영의정에 추증되었다. 선조, 광해군, 인조에 걸친 세 임금을 섬기면서 백성의 생활안정과 지방민을 평온하게 하였던 그의 공로를 찬양하고자 이 비를 세웠다. 조선 효종 9년(1658)에 세운 비로, 비문은 송시열이 글을 짓고, 송준길이 글씨를 썼으며…","a":"진천 이시발 신도비","c":"시도유형문화유산","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638612.jpg"},{"q":"○○○는 어떤 사건이나 사업에 관련된 사실이나 자취를 기록한 비로, 이 비는 ○○읍성을 수리·복원한 사실에 관해 적고 있다. 형태는 길쭉한 직사각형의 비몸 위에 지붕돌을 얹은 모습이다. 비몸에는 성의 수리에 관한 내용들을 새겨 넣었다. 비문에는 조선 고종 3년(1866) 병인양요 후 성과 군용기구 등을 수선하였고, 비상사태에 대비하기 위해 고종 6년(1869)에 전면적인 수리를 하였다는 내용이 기록되어 있다.","a":"충주 축성사적비","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638492.jpg"},{"q":"조선시대 ○○읍성의 남문으로 이름은 멀리 지리산이 보인다는 뜻으로 망악루라 했으나 1932년 지금의 자리로 옮기면서 ○○○로 고쳤다. 앞면 3칸·옆면 2칸의 2층 건물이며 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 2층 내부는 단청으로 칠했으며 난간을 둘렀고 나무로 된 계단을 설치해 1층으로 통하게 만들었다. 1층에는 기둥에 남아있는 흔적으로 보아 기둥 사이에 벽과 문짝이 있었음을 알 수 있다. 이것은 읍성의 남문으로 사용했을 때 있던 것으로 보인다.","a":"함양 함화루","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642077.jpg"},{"q":"사경은 공덕 수행을 위한 신앙의 차원에서 정성들여 경문을 쓰고 불경을 요약한 변상(變相)을 그려 장엄하게 꾸민 것을 총칭한다. 후진(後秦)의 구마라습이 번역한 금자경은 불상의 몸에 넣기 위해 처음에는 전체길이 7m의 종이를 이어 붙여 두루마리로 만들었는데 지금은 가로 7.4㎝, 세로 16.5㎝크기로 병풍처럼 접은 첩모양이다. 간행기록이 없어 정확한 연대를 알 수 없지만 나옹화상의 어록과 발원문(發願文:책을 만드는 이유와 만든 사람들에 대해 적은 글)이 있는 것으로 보아 나옹 이후에 쓰여진 것으로 보인다. 나옹화상(1320∼1376)은 고려 공민왕의 스승이 되어 다시…","a":"안동광흥사장금자사경","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641008.jpg"},{"q":"○○○은 상량문에 따르면 1897년에 지었다. 이 당안의 돌들은 양근석 모양이었으나 모두 도둑맞았다. 보성군민들은 고목을 신체로 섬기고 있으며, 이곳처럼 양근석을 7개나 모신것은 보기 드문 일이다. 이곳 주민들은 돌 일곱개는 칠성님을 상징한다고 말하고 있다. 그리고 칠성신체인 돌은 양근석을 닮아서인지 아기 못 낳은 여인들이 공을 들이는 장소로 많이 이용되었다. 또 양근 귀두부분을 여자들이 깍아가서 수난을 당하기도 하였다.","a":"보성당촌별신당집및당제","c":"시도민속문화유산","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658401.jpg"},{"q":"○○○ 안에 있는 연못 중 하나이다. 전체적인 모습은 석축을 단이 지게 정연하게 쌓아 동서로 최대 길이 21m, 너비 12m 정도로 위를 넓게 하고, 아래는 최대 길이 9m, 너비 4m로 좁혀 쌓아 석탑을 거꾸로 세워놓은 모양을 하고있다. 서남 방향에는 잘 다듬은 돌 2매씩을 길게 쌓아 10여 개의 계단을 설치하여 출입할 수 있는 통로를 마련하였다. 바닥에는 판판한 돌을 깔았고, 동·서벽쪽에는 너비 40㎝의 배수로를 설치하여 물의 흐름을 쉽게 하였다. 이 연못은 백제 때부터 계속하여 이용되었던 것으로 추정되고 있다. 특히 연못에 이를 수 있는 암문(성벽에서 잘 보이지…","a":"공주공산성연지","c":"시도기념물","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652735.jpg"},{"q":"훌륭한 유학자들의 위패를 모시고 제사지내며, 지방 백성의 교육과 교화를 담당하기 위해 세운 국립교육기관이다. 조선 태조 7년(1398)에 계명산 아래에 처음 지었으나, 임진왜란(1592) 때 불에 타 없어진 후 인조 7년(1629)에 지금의 자리로 옮겨졌다. 남아있는 건물은 대성전과 동무·서무·명륜당·동재·서재·내삼문·외삼문 등이다. 대성전에는 공자를 비롯한 중국의 훌륭한 유학자들의 위패를 모시고 있으며, 동무와 서무에는 우리나라의 18명의 현인들의 위패를 모시고 있어 제사공간을 이루고 있다. 명륜당은 학생들이 모여 공부하는 강당이었는데, 갑오개혁(1894) 이후 교…","a":"충주향교","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638472.jpg"},{"q":"고을을 다스리는 수령과 관리들이 집무를 보던 관청건물이다. 조선 영조 41년(1765)에 지어진 것으로 보이는데, 고흥군청 안에 관아의 정문인 아문과 본채인 ○○○이 남아있다. 본채인 ○○○은 앞면 5칸·옆면 3칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 정문인 아문은 3칸인 3문 형식으로, 가운데 칸의 지붕이 양쪽 칸의 지붕보다 높으며 3칸 모두에는 2짝씩의 널판장문을 달았다.","a":"고흥존심당및아문","c":"시도유형문화유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639888.jpg"},{"q":"○○○는 성주산문(聖住山門)과 밀접한 관계에 있었던 낭혜화상(朗慧和尙)의 제자였던 원랑선사(圓朗禪師, 816~883)가 머무르면서 이 지역 선종의 보급과 발전에 중요한 역할을 수 행하였던 곳으로 보물 ○○○○○ 원랑선사탑비와 도 유형문화유산인 ○○ 송계리 대불정주범자비와 관련된 역사 문화 환경 유존지역이다. 충북지역의 수많은 사찰과 폐사지들 중에서도 절대연대를 가름할 수 있는 신라 하대의 사찰로 중요한 학술적 의미를 갖는다.","a":"제천 월광사지","c":"시도기념물","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020030310363100.jpg"},{"q":"○○○○는 옛날 화성과 광주의 경계에 위치한 지지현의 산마루 위에 있는 비석이다. 조선 제22대 왕인 정조의 지극한 효성을 추모하기 위해 순조 7년(1807) 화성 어사 신현(申絢, 1764~1827)의 건의로 세워졌다. 정조가 아버지 사도세자의 능인 현륭원(顯隆園, 현재 화성시 융릉)에 참배를 하러 갈 때, 아버지의 묘가 내려다보이는 데도 묘까지 가는 시간이 너무 더디게 느껴져 \"왜 이리 더딘가\"하고 한탄하였다고 한다. 또, 참배를 마치고 한양으로 돌아가는 길에 이 고개를 넘으면 더 이상 아버지의 묘가 보이지 않아, 그리워하는 마음에 안타까워하며 이 고개에서 눈물을…","a":"지지대비","c":"시도유형문화유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637376.jpg"},{"q":"담양 ○○○ 고택은 고하 ○○○의 성장했던 곳으로 한말 호남의병의 영수인 성재 기삼연이 1차 의병을 일으켰다가 조정의 해산조치에 반항하여 체포된 후 감옥에서 탈출하여 은거했던 곳이다. 이곳에서 기삼연은 ○○○를 교육하였고 후일의 의병활동을 구상하여 한말의병의 중핵인 3차의병의 중심역을 했던 호남의병을 일으킬 수 있게 하였다. ○○○는 항일운동과 교육활동, 그리고 해방 전의 활동이 국가 민족에게 공헌한 바 컸으므로 1963년 3월 1일에 건국 공로훈장이 추서되었다. 현대 민족사에 있어서 중요한 위치를 차지한 고하 ○○○의 고택으로 성장지이며 한말의병이 총수인 기삼연의…","a":"담양송진우고택","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662303.jpg"},{"q":"상평초등학교 현서분교 운동장 반대편 건물 뒷쪽에 서 있는 탑으로, 원래는 이곳에서 동쪽으로 약 200m 떨어진 논에 있던 것을 1965년 옆에 있는 ○○○○석조비로자나불좌상(강원특별자치도 문화유산자료)과 함께 이곳으로 옮겨 보존하고 있다. 탑은 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단과 탑신의 1·2층 몸돌 모서리에는 기둥 모양을 새겨 놓았다. 급한 경사가 흐르는 지붕돌은 둔하고 무거워 보이는데, 네 귀퉁이가 경쾌하게 들려있어 무거운 맛을 덜어주고 있으며, 밑면에는 1·2층은 4단, 3층은 3단의 받침을 두었다. 꼭대기에는 머리장식의 받침대역…","a":"양양서림사지삼층석탑","c":"문화유산자료","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660558.jpg"},{"q":"1636년(인조 14)에 ○○○사 정양필이 창건하고, 1711년(숙종 37) ○○○사 이정신이 ○○○으로 편액을 붙여 조선시대 말기까지 ○○으로 사용되었다. 일제시기 이후에는 동래군청 청사로 사용되다가 1973년 동래군 이 양산군으로 편입됨에 따라 양산군 보건소 동래지소로 사용되었고, 1977년 부산광역시에서 매입하여 초석 이상을 해체복원하여 지금까지 보존되고 있다. 이 건물은 ○○○사 등 동래의 수령이 일을 처리하던 곳으로 지금의 부산광역시장 집무실과 비슷하다. 지붕은 팔작지붕이고, 처마는 겹처마이며, 천장은 연등천장이다. ○○○은 원래는 양옆에는 방, 가운데는…","a":"동래부 동헌 충신당","c":"시도유형문화유산","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636597.jpg"},{"q":"○○○○○은 탐진안씨가 누대로 세거하고 있는 ○○군 입산마을의 중앙부에서 위치하고 있으며, 1948년 대한민국 정부 수립 때 초대 문교부장관을 역임한 ○○○ 박사의 생가이다. ○○○○○에서 건축사적 가치를 가진 것은 1911년에 건축한 안채뿐이며, 안채를 제외한 아래채, 협문 등은 건축연대가 늦고, 건물 배치 및 외부공간의 구성면에서 볼 때 사랑채와 대문채 및 기타 부속건물의 멸실로 인해 원형이 크게 훼손되어 있는 상태이다. 안채는 정면 5칸, 측면 1칸의 일(一)자형 건물로, 전후좌우에 퇴가 발달한 홑처마 맞배집으로 종도리 받침장여에 “歲在辛亥二月十五日....”이라…","a":"의령 안호상 고택","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666381.jpg"},{"q":"고려 후기 문신인 민안부 선생의 묘 근처에 세운 재실이다. 민안부가 예조판서로 있을 때 고려는 국운이 기울기 시작하여 이성계가 위화도회군을 하고 최영, 정몽주의 제거와 혁명을 일으킨 어수선한 시기였다. 그는 벼슬을 버리고 고려 유신 72현과 두문동(지금의 경기도 개풍군 광덕산)에 들어가 조선을 반대하며 항쟁하다 겨우 죽음을 면하고 경상남도 ○○군에 내려가 은둔하였다. 그곳에서 자연과 더불어 여생을 보냈으며 그의 아들들도 그의 뜻에 따라 조선시대에 벼슬을 하지 않았다. 그 뒤 후손들이 번성하여 ○○ 민씨의 시조가 되었다. 처음에는 묘 근처에 개울이 있었다고 하는데 지금…","a":"산청 송계재","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664315.jpg"},{"q":"장충사는 조선 인조 10년(1632)에 나라를 위해 목숨을 바친 이들의 순국정신을 기리고, 본받기 위해 세운 서원이다. 효종 8년(1657)에는 임금이 직접 글씨를 쓴 액자를 하사 받은 사액서원으로 고종 5년(1868) 서원철폐령으로 해체되었다가 1964년 지방 유림들에 의해 새로 지어져 오늘에 이르고 있다. 장충사에서는 임진왜란 때 힘껏 싸우다 전사한 동래부사 천곡 송상현을 비롯하여 무장공 신호, 장무공 김준의 제사를 모시고 있다.","a":"정충사지","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653575.jpg"},{"q":"이곳은 정침 1동, 사당 1동, 정자 1동 등 모두 3동의 건물이 ‘○○○○○’이라는 명칭으로 민속문화유산으로 지정되어 있다. ○○○○의 건물배치는 뒤편의 야산을 등지고 정침, 정자, 사당, 방앗간 등이 남향으로 배치되어 있다. 배치구성은 1993년 복원된 대문간채를 들어서면 넓은 마당을 사이에 두고 정침과 정자가 나란히 배치되어 있으며, 그 뒤에는 사당이 자리 잡고 있다. 이 지역의 상류주택 특성을 잘 보여준다. 안채(정침)은 정면 7칸 × 측면 6.5칸 규모의 □자형 건물로 홑처마 맞배기와집이며, 전면 양측으로 1칸씩 돌출되어 양날개집의 형상을 하고 있다. 안채의…","a":"울진 평해황씨 해월종택","c":"시도민속문화유산","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658935.jpg"},{"q":"우리나라는 고려중기 이후로부터 금속활자 인쇄기술이 매우 발달되었던 사례를 보이고 있다. 이러한 역사적 사실을 바탕으로 ○○○는 조선시대에 들어와서 계미자와 경자자 다음에 세 번째로 세종 16(1434) 갑인년에 구리(銅)를 주성분으로 주조된 금속활자이다. 특히 세종대의 고도의 과학기술과 장인정신을 바탕으로 주조되었던 까닭에 한국활자사에 있어서 가장 아름답고 정교한 활자로 평가되고 있는 것이다. 그리하여 조선시대의 가장 대표적 활자로 6차례 이상 개주를 거듭하였던 관계로 맨 첫 번째로 주조된 ○○○를 ‘초주○○○’로 구분하여 이름하고 있다. 조선은 유교를 국시로 삼고…","a":"선덕사소장갑인자복각묘법연화경 권1~2","c":"시도유형문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643312.jpg"},{"q":"○○○○란 회색 또는 회흑색의 바탕 흙 위에 정선된 백토로 표면을 분장한 뒤에 유약을 씌워 구운 조선 전기의 도자기이다. 높이 43.4㎝, 아가리 지름 16.0㎝로, 조선시대 즐겨 만들었던 ○○○○○의 대표적인 형태이다. 밖으로 살짝 벌어진 아가리 가장자리와 곧고 짧은 목 언저리를 가졌으며, 어깨가 팽창되고 몸체가 긴 편이다. 특히 몸체에 새겨진 ‘全ㅅ道’라는 글로 미루어, 충효동 가마가 있는 ○○○ 지방이 조화·박지 ○○○○의 산지였다는 것을 알 수 있다.","a":"분청사기전라도(전라도)명항아리","c":"문화유산자료","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659678.jpg"},{"q":"○○○라는 마을 위쪽의 밭에 서 있는 3층 석탑이다. 3면이 산으로 둘러싸인 탑 주변은 기와조각이 흩어져 있을 뿐 다른 유물은 없다. 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올렸는데, 현재 세번째 탑신은 없어졌다. 1 ·2층 기단과 탑신의 몸돌에는 기둥 모양을 새겼다. 지붕돌은 네 귀퉁이가 살짝 치켜올라 갔고, 밑면에는 4단의 받침을 두었다. 전체적으로 기단과 탑신 몸돌에 새긴 기둥조각 등은 정교하나, 1층 몸돌에 비해 2층 몸돌이 급격히 줄어들어 균형을 이루지 못하고, 또한 3층 몸돌을 잃어버려 아쉬운 감이 있다. 1962년 해체 ·복원시 곱돌로 만든 소…","a":"공주동원리석탑","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639085.jpg"},{"q":"○○○의 여러 부처와 보살을 모시고 종교의식을 치르는 건물인 불전 중에서 가장 중심이 되는 건축물이다. ○○○○○은 임진왜란으로 불에 타 없어져 1684년에 다시 짓고, 1725년에 크게 수리한 것이다. 건물의 생김새를 보면 별도의 축대는 없이 거칠게 다듬은 자연석 기단만 한 단을 두고, 자연석 주초와 둥근 기둥을 사용하여 몸통을 구성하고, 지붕은 옆면이 수직으로 마감되는 맞배지붕을 하고 있다. 지붕 아래쪽 처마와 기둥 사이에는 건물의 무게를 지탱하고, 화려하게 돋보이도록 하는 장치인 공포를 앞뒤에만 두고, 옆면에는 두지 않았다. 전체적으로 1725년 수리 때의 모습…","a":"석남사대웅전","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637541.jpg"},{"q":"노수신 적소는 조선 중기의 유명한 신하인 노수신(1515∼1590)이 귀양살이를 하던 곳으로, 후에 건물명을 ○○○이라 하였다. 노수신은 중종 38년(1543) 과거시험에 합격하여 이황과 같이 학문을 연구하다가 정권다툼으로 관직에서 물러나고 순천, ○○ 등지에서 귀양살이를 하다가 선조 즉위 후 다시 관직에 올라 영의정에까지 오른 인물이다. 건물은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"괴산 수월정","c":"시도기념물","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650014.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손엔 목리문이 그려진 주장자를 오른손엔 염주를 쥐고 측면을 향해 앉아 있다. 그 옆으로는 서책들이 올려진 서안이 보인다. 화면은 녹색바탕에 운보문의 충진구도인 상단벽면과 돗자리의 이단구도로 이루어져 있다. 화면 향우측엔 양종대법사○○○○○지진(兩宗大法師凝庵堂僖愈之眞) 화제가, 향좌측 외곽에는 묵서로 쓴 영찬이 있다. 화면 크기는 가로 75.0cm, 세로 113.1cm이다.","a":"응암당 희유 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643019.JPG"},{"q":"○○○○는 서왕모(西王母)의 거처인 곤륜산(崑崙山) 요지(瑤池)에서 열리는 연회장면을 그린 것으로 총 8폭의 병풍에 담은 것이다. 중국의 옛 문헌인『죽서기년 竹書紀年』과『목천자전 穆天子傳』에 실린 서왕모와 주목왕(周穆王)의 연회에 군선(群仙)들이 초대되어 가는 이야기가 결합된 고사에 연원을 둔 것이다. 화면 중앙 4～5폭에 서왕모와 그녀를 방문한 주목왕(周穆王)의 연회가 베풀어지는 장면이 위치해 있고, 7～8폭에는 여러 신선들이 그 곳을 향해 바다를 건너오는 모습이 생동감 있게 그려졌다. 화면전체에 상징적 의미가 내포된 인물과 반도(蟠桃)를 비롯한 각 종의 동식물들이…","a":"요지연도","c":"시도유형문화유산","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637753.jpg"},{"q":"후진(後秦)의 구마라습(鳩摩羅什)*이 번역하고, 송(宋)의 계경(戒璟)이 해석한 것을 1448년에 이녕대군(李寧大君)과 안평대군(安平大君)의 발원(發願)으로 주조인출(彫造印出)한 목판본(木版本) 보물 766호『○○○○○ 권4~7(卷四~七)』과 동일한 판본의 후쇄번각본(後刷飜刻本: 한 번 새긴 책판을 본보기로 삼아 그 내용을 같은 판 뒤에 인쇄하여 다시 새긴 책)으로 추정된다. 766호(號)의 판식(版式)과 변상도(變相圖)*의 형식을 그대로 따른 점으로 보아 임진왜란 이전에 판각(板刻) 인쇄한 것으로 보인다. 전7권 가운데 ○○○권까지 1책으로 구성되어 있으며, 변상도…","a":"묘법연화경 권1~3","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638882.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 충청남도 논산 ○○○에 있는 고인돌은 탁자식과 바둑판식이 함께 섞여 무리를 이루고 있다. 1965년 국립중앙박물관의 조사에 의해 탁자식 2기가 발견되었으며, 그 후 계속된 조사를 통해 현재는 15기의 고인돌이 확인되었다. 이곳의 고인돌은…","a":"논산신기리지석묘","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661327.jpg"},{"q":"○○○는 신라시대 원효대사가 ‘미륵원’이라는 이름으로 세운 절이다. 언제부터 ○○○로 이름이 바뀌었는지는 알 수 없으나 『신증동국여지승람』에는 ‘신왕사’로 기록하고 있고, 미륵전 건물에서 발견한 기록에 따르면 정조 13년(1789) 무렵 까지는 ‘신황사’로 불렸던 듯하다. 고려 현종 2년(1011)에 거란군이 침입하자 현종이 이곳 나주로 몽진하여 나라의 평안을 위해 기도를 올렸다고 전하는데, ‘신황사(神皇寺)’라는 이름에서 황제 황(皇)자를 쓰고 있는 것으로 보아 임금이 이 절의 대법회에 참여했을 가능성이 있는 것으로 추정된다. 경내에는 미륵전, 극락전을 비롯하여 고…","a":"심향사","c":"문화유산자료","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662024.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 언제 처음 지었는지 정확히 알 수 없으나, 조선 초 각 지방 군·현에 향교들이 건립될 때인 1407년(태종 7)~1413년(태종 13)에 창건되었을 것으로 추측된다. 처음에는 동교리에 있던 것을 지세가 협소하여 성현을 추가로 모시거나 제사를 올릴 때 법도대로 모시지 못하여 1649년 현감 이창윤(李昌胤)에 의해 현의 남쪽으로 이건되었다. 그러나 1684년(숙종 8) 율곡 이이와 우계 성혼을 추가로 제향하면서 건물이 협소해 다시 현재 위치로 이건하였다. 교육 공…","a":"전의향교","c":"시도기념물","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658034.jpg"},{"q":"◦ 이곳 오천은 조선시대 충청도수군절도사영이 설치된 곳이었으나 1895년 폐영되었다가 1901년에 오천군이 신설된 곳임. ◦ 오천군 신설과 동시에 이곳 유림들은 고을에 향교를 갖추려 하였으나 여의치 못하여 간단한 제향을 할 정도의 기물과 시설을 갖춘 채 향교의 터전을 잡았음. ◦ 그 후 1905년에 이르러 토지 기증․헌납 등을 통한 유림들의 노력과, 군수의 조력으로 ○○○ 건물을 완성하여 향교의 모습을 갖추고 이 고을 유교문풍을 진작하면서 오늘까지 그 맥을 이어오고 있음. ◦ 그리하여 ○○○○는 우리나라에서 가장 짧은 역사를 가진 향교로 규모는 작지만 ○○○에 이어…","a":"오천향교대성전","c":"문화유산자료","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661117.jpg"},{"q":"불신만 남아 있는 이 불상은 왼쪽 팔목의 보수를 제외하면 보존상태가 좋은 편이다. 신체에 비해서 큰 얼굴은 앞으로 숙여져 있으며 옷은 왼쪽 어깨만을 감싸고 있다. 손은 오른손 바닥을 무릎에 대고 손끝이 아래를 가리키고, 왼손은 손바닥을 위로 향하게 하여 배꼽 앞에 놓은 모습이다. 왼발을 오른쪽 넓적다리 위에 얹어 놓은 앉은 자세는 그 예가 드문 편이다. 평판적이고 굴곡이 없는 네모진 상체, 목에 있는 3개의 주름, 둔감한 옷주름선 등에서 도식화되는 경향을 보이는 고려시대 말기 불상으로 추정된다.","a":"괴산 봉학사지 석조여래좌상","c":"시도유형문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638446.jpg"},{"q":"나주 나씨인 나사침(1526∼1596)을 비롯하여 3대에 걸친 충신 두 분과 효자 두 분 그리고 열녀 네 분의 행적을 기리기 위해 마을 입구에 세운 정려문이다. 나사침은 16세 때 어머니가 병으로 위급해지자 자신의 손가락을 잘라 피로 봉양하여 위기를 넘기고 어머니의 병을 낫게 하였다고 한다. 또한 그의 손자인 나득소(1607∼1640)는 어려서부터 효성이 지극하고 아버지인 덕현이 돌아가시자 3년상을 치르고 효를 다해 그의 할아버지와 함께 효자로 정려되었다. 나사침의 큰아들인 나덕명(1551∼1610)과 여섯째 아들인 나득소(1607∼？)는 기축옥사에 연루되어 종성지방…","a":"나씨삼강문","c":"문화유산자료","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662026.jpg"},{"q":"임진왜란시 의병을 일으켜 ○○수성(安東守城)에서 공을 세운, 대박 김철의 묘소를 보호하기 위해 세운 재실이다. 조선 중기에 세운 이 건물은 제사를 지내는 방인 정침을 중심으로 좌우에 건물을 두었고 앞쪽으로는 5칸의 누각이 설치되어 ㅁ자형 구조를 보여준다. 원래는 임하면 사의동에 있었으나 인하댐 건설로 1987년 이곳으로 옮겨 세운 것이다.","a":"안동 송석재사","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658912.jpg"},{"q":"금오산 자락 아래 해발 약 230m 지점의 능선에 위치하고 있는 국사골 ○○○○는 남산 동쪽 남산 순환도로 입구에서 오른쪽으로 나 있는 등산로를 360m 정도 올라가다 북쪽으로 난 계곡을 건너 다시 소로를 따라 북쪽 산등성이를 향해 약 300m쯤 올라가면 나타나는 대숲을 지난 지점에 위치한다. 이곳은 고깔바위 아랫부분에 해당하며, 서남쪽으로는 南山 浮石이 건너다보인다. 절터에는 모두 7개의 축대가 불완전하게 남아 있으며, 5개소의 건물지가 확인되었다. ○○○○은 이 절터의 가장 높은 지점에 서 있다. 지대석과 북서쪽 기단 면석만이 원위치를 지키고 있고 나머지 부재는…","a":"경주남산 국사곡 제4사지 삼층석탑","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641256.jpg"},{"q":"전라남도 ○○군 무정면 ○○○ 외당 마을 동쪽으로 1㎞가량 떨어져 있는 도로변에 위치하고 있는 불상이다. 하나의 돌에 불신과 광배(光背)를 돋을새김하여 표현하였다. 불상 주위에서 옛 기와조각이 발견된 것으로 보아 이곳이 예전에 절터였음을 알 수 있다. 전하는 말에 의하면 고려시대에 몽고군과 싸우다가 죽은 승려들의 넋을 기리기 위해 만든 불상이라고 한다. 이 불상에서 특이할 만한 것은 두툼한 입술인데, 이런 표현은 고려시대 유행한 지방화된 불상 양식 중 전라남도 지방에서 많이 나타나는 것이다. 옷은 양 어깨에 걸쳐 입고 있으며 옷자락은 U자형의 주름을 이루면서 다리 밑…","a":"담양 오룡리 석불입상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640126.jpg"},{"q":"이 곳은 절의 이름이나 유래가 전해지지 않는 백제의 절터로, 마을 이름인 ‘인갱’을 따서 임강사터라 하였다. 지금은 작은 마을이지만 조선시대까지만 해도 역이 설치될 정도로 중요한 곳이었다. 절터는 위와 아래로 구분되며, 앞면 5칸·옆면 4칸의 건물지도 발굴되었다. 출토된 유물로는 연꽃무늬 수막새 기와, 치미조각, 흙으로 만든 불상 조각, 탑의 머리장식 등이다. 주변에서 백제 기와를 굽던 가마터와 조선시대의 분청사기 가마터도 확인되었다.","a":"임강사지","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652687.jpg"},{"q":"절 주변에 호도나무가 많기로 유명한 광덕사는 신라 진덕여왕 6년(652) 자장이 창건하였다. 절내의 대웅전에서 북쪽으로 약 150m 떨어진 산기슭에 4기의 부도가 자리하고 있는데, 각각 청상당 부도, 적조당 부도, 우암당 부도, 무명 부도라 일컫는다. 청상당 부도는 청상스님의 사리를 모신 부도이다. 스님은 조선 선조 36년(1603)에 출생하여 현종 12년(1671) 은적사에서 입적하였는데 그 제자들이 스님의 사리를 얻어와 이곳 광덕사에 부도를 세웠다고 한다. 형태는 전체가 거의 8각을 이루고 있으며, 기단부(基壇部)와 탑신부(塔身部) 그리고 머리장식을 갖추고 있다.…","a":"광덕사부도","c":"시도유형문화유산","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639137.jpg"},{"q":"○○○는 ¨전등사본말사지¨등의 기록에 의하면 백련사 및 청련사와 함께 고구려 장수왕 4년(416)에 창건되었고, 처음에는 적련사(赤蓮寺)였다는 전설이 전하고 있다. ○○○를 오르는 길목 오른쪽에 자리한 ○○○○○는 숙종 40년(1714)에 세워진 것으로 전체 높이가 3m94cm이고 비신의 높이 3m4cm, 너비 69cm이다. ○○○의 재질은 화강암이고, 지붕모양의 뚜껑돌이 얹혀 있으며 비신의 상부에 ¨고려산○○○지비(高麗山積石寺之碑)¨라는 비의 제목이 있다. 비문에는 불교의 전래 및 사찰의 증건 ·중수상황과 고려시대 몽고 침입에 대항하여 ○○에 도읍을 옮겨 올 때 임…","a":"강화 적석사 사적비","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101617211600.jpg"},{"q":"덕양마을 인근 산기슭에 넘어져 있던 탑으로, 1972년 마을사람들이 이곳으로 옮겨 세웠다. 탑은 전체의 무게를 받치는 기단(基壇)이 1층으로 되어 있으나, 원래는 2층이었을 것으로 보이며 그 위로 3층의 탑신(塔身)을 쌓아 올렸다. 기단의 네 면과 탑신부의 몸돌은 모서리마다 기둥모양을 본떠 새겼을 뿐 다른 꾸밈은 없다. 몸돌을 덮고 있는 각층의 지붕돌은 밑면에 4단의 받침을 두었다. 전체적으로 가벼운 느낌이 들며, 기단에서 기둥 모양의 조각을 모서리에만 두고 면의 가운데에는 두지 않은 점을 제외하면 대체로 통일신라 석탑의 양식을 잘 따르고 있어 이 시기의 작품으로 추…","a":"청도덕양동삼층석탑","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640462.jpg"},{"q":"○○○ 법당 앞마당에 서 있는 탑으로, 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 있다. 기단과 탑신의 몸돌에는 기둥 모양의 조각을 하였다. 지붕돌은 네 귀퉁이가 살짝 치켜올라갔으며, 밑면에는 층마다 3단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식받침)과 복발(覆鉢:엎어놓은 그릇모양의 장식)이 한돌로 조각되어 머리장식을 하고 있다. 돌을 다듬은 솜씨가 세련되지 못하고, 기단이 1층으로 줄어든 점 등으로 보아 고려시대에 세운 것으로 보인다.","a":"갑장사 삼층석탑","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662641.jpg"},{"q":"조선 중기 학자인 정극후(1577∼1658)의 별장이라 전한다. 조선 광해군 12년(1620)에 세웠으며 영조 4년(1728)에 다시 지었다. 높은 석축 위에 자리잡은 3칸 규모의 정자로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 가운데 칸에 마루를 두고 좌우에 방을 두었으며, 건물 앞면 전체에 툇마루를 내어 난간을 두른 누각형 정자이다. 건축 기법에서는 조선 중기 양식과 후기 양식이 섞여 있어 그동안 여러 차례 보수가 있었음을 알 수 있는데, 지금 있는 건물은 대체로 조선 영조(재위 1724∼1776) 때의 양식을 취하고 있다.","a":"수재정","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662733.jpg"},{"q":"이 불상은 1930년대까지 야산의 산 속에 묻혀 머리부분만 노출되어 있던 것을 그 후 ○○○의 법당 안에 모셔 봉안하고 있다. 거대한 자연석을 다듬어 앞부분에는 불상을 조각하고 뒷면은 조각없이 그대로 처리하였는데, 높이 280㎝, 어깨폭 148㎝, 앉은 높이가 3m에 달하는 거불(巨佛)이다. 워낙 거대한 자연석을 이용하여 조각하여서인지 전체적으로 둔중한 느낌을 주는 한편 얼굴과 옷자락의 조각은 사실적인 수법을 보여준다. 머리에는 상투 모양의 육계가 큼직하게 솟아 있고, 소라 모양의 머리칼인 나발이 표현된 흔적이 있으나 현재는 많이 마멸되었다. 신체는 어깨가 넓어 장대…","a":"미륵사석불좌상","c":"시도유형문화유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639729.jpg"},{"q":"임진왜란 때 승병장이 되어 나라를 구하려다 전사한 영규대사의 충혼을 기리고 있는 비이다. 영규대사(?∼1592)는 조선 선조 25년(1592) 임진왜란이 일어나자 3일동안 통곡한 후 스스로 승병장이 되었다. 승병 수백명을 모아 관군과 더불어 청주성의 왜적을 쳤고, 이어 조헌과 함께 금산전투에 참가하여 장렬히 싸우다 전사하였다. 이 일은 이후 전국적으로 승병이 일어나게 되는 계기를 마련하였다. 숙종 5년(1839) 5월 금산군수 조취영이 세운 비로, 일제가 1940년 비를 보호하던 비각을 부수고 비를 묻어놓았던 것을, 해방 후 다시 꺼내 세워놓은 것이다.","a":"의병승장비","c":"문화유산자료","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660904.jpg"},{"q":"무등산 장원봉의 동남쪽으로 비탈진 곳에 위치한 무덤들이다. 모두 6개의 무덤이 있으나 널(관)을 넣었던 돌방(석실)이 완전히 드러난 것은 2기 뿐이다. 1호와 2호 무덤은 유사한 구조를 가지고 있는데, 바닥은 얇은 판돌들을 물이 잘 빠지도록 이중으로 깔고, 가장 밑바닥은 회갈색의 단단한 진흙을 냇돌과 섞어 기초를 다졌다. 올라가면서 무덤방의 너비를 줄인 후 정상부에 2매의 뚜껑돌을 올려 그 무게로 동서벽을 유지하게 한 맞조림식 돌방무덤이다. ○○○ 돌방무덤은 이 고장의 백제사 연구가 문헌상 어려운 실정에서, 이 지방에서 보기드문 백제식 돌방무덤의 출토로 고고학 연구에…","a":"운림동석실고분","c":"문화유산자료","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659602.jpg"},{"q":"청음 김상헌(1570∼1652)과 그 조카의 편지글을 모아 놓은 책으로, 김상헌의 친필 7장, 김광찬의 친필 7장, 김광혁의 친필 1장 등 총 15장으로 구성되었다. 이 중에는 김상헌이 72세의 나이로 심양에 포로로 끌려가 옥중에 있을 때 쓴 서한도 있다. 책의 앞 표지에는 선생의 시호인 ‘문정’과, ‘왕고’가 쓰여 있어 그 손자대에 장첩한 것을 알 수 있다.","a":"문정공왕고간독","c":"문화유산자료","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659722.jpg"},{"q":"○○○ 명부전에 봉안된 ○○○○○이다. 최근 개금불사에서 출토된 복장품에서 강희12년 계축4월일(1674)에 조상했고 건륭6년 신유3월20일(1741)에 중수개금을 시작하여 4월6일에 마쳤다고 하는 복장기를 확인하였다. 즉 조상연대와 중수기록이 있고 또한 ○○○○로서는 비교적 큰 규모이며 조선후기 작품이면서도 조선 전기 양식을 일부 간직하고 있어 조상사 연구에 좋은 자료가 된다.","a":"소재사 목조지장보살좌상","c":"문화유산자료","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659507.jpg"},{"q":"청동기시대의 집자리 유적으로, 서호면 면소재지에서 동남쪽으로 약 500m 떨어진 ○○○ 괴음마을 앞 도로변에 자리하고 있다. 지름 4.3∼5.2m의 움집터이며, 형태는 원형 내지 타원형을 이루고 있다. 중앙에 얕은 구덩이가 있고, 바닥면 가장자리에 기둥구멍이 마련되어 있는데, 화로터나 출입구가 없는 것이 특색이다. 출토된 유물로는 항아리형·사발형의 무늬없는토기, 화살촉·가락바퀴·삼각형 돌칼 등 석기류가 있다. 1984년 목포대학 박물관에서 발굴조사한 것으로, 한반도 서남부지역에서만 볼 수 있는 독특한 문화권의 유적이다.","a":"영암장천리선사주거지","c":"시도기념물","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654247.jpg"},{"q":"○○○○○는 평탄 대지상의 밭 한가운데에 위치하고 있음. ○○○ 주변에는 무문토기편과 석기가 발견되고 있다. 상석은 길이 205cm, 폭은 162cm, 두께 35~75cm로 상면이 다소 평평한 타원형임, 장축방향은 남서쪽으로 5도 정도 깅루어져 있음. ○○○는 남서쪽에 길이 72cm,폭 26cm, 두께 15cm인 대형판석상 지석이 남서쪽 모서리에 원상에서 벗어나 기울어지게 고여 있는데 상석무게를 못이겨 내려않은 것으로 추정됨. 따라서 상석의 남서쪽이 크게 들리어지게 축조한 것으로 판단됨. 상석고임에서 벗어나 누워 있는 상태로 발견되었고 산석의 남동쪽에 길이 25cm,…","a":"일과리지석묘","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657738.jpg"},{"q":"봉림사가 소장중인 불교전적류 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, ○○○○○, 월인석보제21(상), 불설대보부모은중경이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"불정심관세음보살 대다라니경","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642620.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○○○는 2001년 5월―2002년 2월까지 매장유산조사기관의 발굴조사 결과 모두 4기가 확인되었다. 4기 중 가장 북쪽에 자리하고 있는 4호는 상당부분 유실된 상태였으나 나머지 3기는 비교적 양호한 상태로 확인되었다. 1호 가마는 전체길이 2,450㎝ 내외로서 일부분이 유실되었을 뿐 아궁이와 소성실(燒成室), 굴뚝부가 완전한 형태로 남아 있으며, 특히 천장부는 약 3m 정도가 남아 있다. 소성실은 5칸으로 이루어져 있는데 폭은 150―160㎝ 내외이며 약 4m의 간격으로 불창기둥과 불턱을 축조하여 계단…","a":"고창용산리분청사기요지","c":"시도기념물","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653751.jpg"},{"q":"화면을 상하로 이분한 뒤 상단에 향우측으로부터 화영당, 인한당, 해경당을, 하단에 향우측으로부터 세염당, 나월당, 효월당, 송곡당을 순서대로 그리고 인물의 오른쪽 어깨위로 각각의 화제명호란을 만든 후 기입하였다. 스님들은 모두 좌안7분면에 결가부좌를 하고 있으며 손에는 염주 또는 주장자를 쥐고 있는 모습이다. 잿빛장삼에 홍가사를 걸치고 있으며 녹색, 군청색, 황토색의 매듭으로 가사를 수하고 있다. 짙은 잿빛과 옅은 잿빛 장삼을 교대로 배치하고 지물들도 변화를 주어 단조로움을 피하고 있다. 철선묘로 곧게 그린 후 약간의 음영을 가하여 입체감을 표현한 얼굴과 깊게 주름진…","a":"남해 용문사 칠화상 진영","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001666210.jpg"},{"q":"○○○은 18세기 중엽에 세워졌던 것으로 입구의 암벽에 [송정선생장구지소(松亭先生杖구之所)]라고 새겨져 있어 이곳이 송정 하수일(1553~1612)이 머물렀던 곳임을 알 수 있다. 처음 건립된 후 1909년에 중수된 ○○○은 예부터 이름난 서부경남 일대의 유림의 강학소겸 정사로서 입지와 배치가 훌륭하고 부분적 변형은 있지만 전통목조 건축의 수법을 잘 간칙하고 있다. 부속건물로 사우와 함청헌이 있다.","a":"진주 낙수암","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022385200.jpg"},{"q":"이중환의 택리지에 ‘조선인재반재영남(朝鮮人材半在嶺南)’이라는 대목이 나온다. ‘조선 인재의 반이 영남에서 태어났다’는 뜻이다. 특히 진주는 강․하․정씨가 본관을 두고 있을 정도로 많은 인물들이 탄생하였으니, 진주지역에도 인명록 출판이 성행하였다. 곧, 연계안(蓮桂案)이나 ○○이 그것들이다. 연계안은 진주출신으로서 과거에 급제한 인물들의 이름을 적은 명부이고, ○○은 진주에서 학식과 덕행을 두루 갖춘 선비의 이름을 적은 인명록이다. 조선시대 ○○과 연계안에 이름이 기록된 조상을 둔 후손들은 진주시 옥봉동에 연계재(蓮桂齋)를 지어서 인명록을 소중하게 보관하면서 큰 명예로…","a":"향안","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642532.jpg"},{"q":"○○읍 평곡리 탑정이라는 옛 절터에 있던 탑으로, 1934년 경호정(옛 연풍정) 앞으로 옮겨 세웠다. 형태는 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단의 네 모서리와 탑신부의 각 몸돌에는 기둥 모양을 조각하였다. 지붕돌은 밑면에 3단의 받침을 두었고, 네 귀퉁이에서 살짝 들려있다. 꼭대기에는 연꽃 봉우리 모양의 머리장식을 얹어 놓았다. 전체적으로 통일신라 전성기의 석탑 양식에 비교할 때, 기단이 2층에서 1층으로 줄어들고, 기단의 가운데기둥 조각이 생략되었으며, 지붕돌 받침은 3단의 줄어 들었다. 이처럼 각 부분의 양식이 약식화되고 있어 고려…","a":"음성 읍내리 삼층석탑","c":"시도유형문화유산","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638592.jpg"},{"q":"○○○란 어떠한 사건에 관련된 사실이나 자취를 기록한 비로, 이 비는 ○○○의 창건에 관하여 기록하고 있다. ○○○는 비문에 의하면, 신라 눌지왕 3년(419)에 아도화상이 창건하였고, 창건 당시에는 ‘보현사’라 이름하였다 한다. 임진왜란으로 불에 타 버린 것을 인조 22년(1644) 정현대사가 다시 건물을 지어 ‘○○○’라 고쳐 부르게 되었다. 비는 거북받침돌 위로 비몸을 세우고, 그 위로 구름과 용이 새겨진 머릿돌을 얹은 모습이다. ○○○○○ 건립연대 표기 ‘숭정기원후재경오(崇禎紀元后再庚午)’는 1690년으로 알려 졌는데, 숭정 재위 기간의 경오(1630년)는 포…","a":"고흥 능가사 사적비","c":"시도유형문화유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639914.jpg"},{"q":"1972년에 청담대종사의 사리탑 및 사리탑비·사적비 등을 조성하기 위해 사리탑 부지를 터파기할 때 고려 범종 1점을 비롯한 ○○시(靑銅匙) 5점, ○○저(靑銅箸) 1짝, ○○국자 2점, 동경 1점, 동전 1점이 ○○로 출토되었으며, 현재 청담기념관에 보관중이다. 출토지가 분명한 이 ○○들은 전형적인 고려시대 금속공예품과 조선시대 상평통보(常平通寶), 그리고 일본 에도시대 동경이 서로 섞여 있는데 이는 사리탑 부지가 오랜 기간 존속된 건물지임을 증명해주고 있다.","a":"도선사 청동 종 및 일괄 유물","c":"시도유형문화유산","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594733.jpg"},{"q":"경상북도 성주군 가천면 해발 955m의 독용산 정상에 있는 산성으로, 둘레가 7.7㎞에 이른다. 성 안에 물이 풍부하고 활용공간이 넓어 장기전투에 대비하여 만들어진 것으로 보인다. 이와 같이 계곡을 포함하여 산정을 두른 형태를 포곡식이라 하는데, 영남지방의 산성 중 가장 큰 규모이다. 성이 만들어진 시기는 정확하지 않으나 가야 때 쌓은 것으로 추정되며, 임진왜란을 피하던 중에 발견되었다고 한다. 이 성은 임진왜란 때 전쟁의 화를 입지 않은 유일한 성이기도 하다. 조선 숙종 원년(1675)에 동·서·남·북에 7개의 포루, 아치형 동문, 수구문, 남소문을 다시 고쳐 쌓았…","a":"독용산성","c":"시도기념물","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654572.jpg"},{"q":"○○○○ 묘소의 ○○○은 망주석 바깥에 서로 마주보고 있는 형태로 서 있는데, 그 크기는 높이 190cm, 앞면의 너비가 55cm로서 보통 사람보다는 훨씬 덩치가 큰 모습이다. 문인의 얼굴 모습은 반듯하고, 머리에 쓴 관과 입은 관복이 매우 섬세하게 표현되어 있으며, 옷의 주름이나 얼굴 곳곳의 부분 모습이 마치 실제 입은 옷을 보는 것 같고 마치 살아 있는 모습을 보는 것처럼 사실적이고 부드럽게 묘사되어 있다. ○○, 상석, 향로석, 망주 ○○○○을 위시하여 묘소 주변의 자연석으로 축조한 내룡이나, 상석을 기준으로 얕은 돌을 쌓아 제향 공간과 분리해 둔 점이나, 그…","a":"산청 장수황씨 묘비 및 문인석","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665984.jpg"},{"q":"○○○란 옛 선현의 자취를 살피어 후세에 알리고 이를 계기로 그를 추모하기 위하여 세워두는 비로, 이 비는 조선시대 전기의 문신이자 생육신의 한 사람인 ○○○ 선생의 공적을 기리고 있다. 선생의 호는 ○○으로, 길재의 제자가 되어 가르침을 받고 과거에 급제하여 벼슬길에 올랐다. 거창 지역에 현감으로 있을 때에는 어진 다스림을 베풀어 고을 사람들의 칭송을 받았으며 ‘청백리’라는 호칭을 얻었다. 수양대군이 어린 조카인 단종의 왕위를 빼앗을 조짐이 보이자 벼슬을 버리고 고향인 선산으로 돌아왔고, 단종이 영월 땅으로 유배되자 귀머거리에 장님 행세를 하며 단종을 그리워하다 8…","a":"경은 이맹전 유허비 및 묘비","c":"문화유산자료","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663184.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 충청남도 태안군에서 서북쪽으로 13.6㎞ 떨어진 해안가에 있는 조선시대 읍성으로, 조선 중종 9년(1514)에 쌓은 것이다. 이 곳에 성을 쌓게 된 동기는 왜구의 침입을 막기 위해서였는데, 특히 고려 말부터 이 지역에 나타난 왜구의 침입으로 인해 지역 주민들의 피해가 심각했다고 한다. 이 성은 서쪽으로는 서해에 접하고 있으며, 동·남·북벽은 자연지형을 이용하여 성벽을 구축하였다. 성의 둘레는 650m 정도인데 대부분이 무너지고 현재는 동문터 부근만이 남아 있다. 동문터의 북벽을 보면…","a":"태안소근진성","c":"시도기념물","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652844.jpg"},{"q":"본 작품은 화기를 통해 볼 때 ○○○ 불화조성을 19세기 전반까지 영향을 미친 화사(畵師) 지연(指演)에 의해 제작된 귀중한 작품으로 건륭(乾隆) 57년(1792)에 제작되었다. ○○○○○ 도상 연구에 있어서 자료적 가치가 높다.","a":"양산 통도사 건륭57년명 삼장보살탱","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642475.jpg"},{"q":"조선 후기 유학자인 이항로(李恒老, 1792년-1868년)가 세운 사당[노산사(蘆山祠)]이 있는 터를 말한다. 이항로는 생전에 중국 송나라 시대의 유학자 주희(朱熹)와 조선 후기 유학자 송시열(宋時烈)의 학문을 잇고자, 그가 태어난 집터에 두 사람의 위패와 초상화를 모신 사당[노산사(盧山祠)]을 지었다. 이후 이항로가 죽자 후손들이 그의 학문과 뜻을 길이 전하고자 사당 중앙에는 주희를, 동쪽으로는 송시열을, 서쪽에는 이항로를 각각 모셨다. 현재의 노산사는 한국 전쟁으로 불타 없어졌다. 이후 1954년에 지역 유림(儒林)들에 의해 다시 세워졌고, 1985년에 중수(重修…","a":"노산사지","c":"시도기념물","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646067.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라 성덕왕 23년(723)에 삼법이 지었으며, 문성왕 2년(840)에 진감국사가 다시 지었다. 원래 이름은 옥천사였으나 정강왕(재위 886∼887) 때 ○○○로 이름을 바꾸었다. 임진왜란 때 불타 없어진 것을 벽암이 조선 인조 10년(1632)에 다시 지어 오늘에 이르고 있다. ○○○○○은 숙종 30년(1704)에 박봉스님이 지었고 순조 25년(1825)에 고쳤으며, 현재의 건물은 고산스님이 1978년에 다시 수리한 것이다. 사천왕을 모시는 문으로 사천왕은 부처님께 의지하여 불법을 수호하고 수도하는 스님과 선량한 사람을 돕…","a":"하동 쌍계사 천왕문","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641658.jpg"},{"q":"목천면사무소에서 병천으로 가는 길 왼쪽 산기슭에 있는 불상으로 원통형의 돌을 다듬어 만들었다. 갸름하면서도 복스러운 얼굴에 감은 듯한 눈, 오똑한 콧날, 작고 단정한 입 등이 단아하고 자비로운 인상을 준다. 양 어깨를 감싼 옷은 두꺼워서 신체의 굴곡이 거의 드러나지 않지만, 드러낸 가슴에서부터 무릎 아래까지 U자형의 옷주름을 표현하고 있다. 오른손은 손바닥을 정면으로 하여 손가락이 위로 향하고, 왼손은 손바닥을 정면으로 하여 손가락이 아래로 향한 손모양을 하고 있다. 전체적으로 통일신라시대의 불상양식의 전통을 잘 계승하고 있는 고려시대의 작품이다.","a":"용화사 석조여래입상","c":"시도유형문화유산","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639100.jpg"},{"q":"임란 후에 간행된 경전 7책중 하나로, 십지경론(하) 난승지 제5권 7~ 법운지 제10권 12, 간집록, 대방광불화엄경소초 권34, ○○○○○, 대방광원각수다라요의경 권6, 묘법연화경 권1,2 이다. 각수를 적어놓은 형태나 어미 모양 등 지방 사찰에서 간행된 목판본의 형태와 판본류를 확인해 볼 수 있으며 조선후기 각 지방의 경전 간행의 경향을 알 수 있는 중요한 자료로 인정됨","a":"경덕전등록 권22~24","c":"시도유형문화유산","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643188.JPG"},{"q":"보문산공원 진입로 우측에 있는 정려각에 보관된 송두원과 그의 할머니 윤씨부인의 정려현판이다. 1745년 영조가 명정(銘旌)하였으며 유림에서 주관하여 건립하였다. 송두원은 우암 송시열의 조카인 송기학의 손자이다. 부모에 대한 효성이 지극하였으며, 음식을 철에 맞추어 손수 맛을 본 후에 올렸으며, 부모가 좋아하는 것은 무엇이든 구하여 드렸다. 부모상을 당하여서는 예법에 따라 정성을 다하여 장례를 치르고, 시묘 중 잠시도 상복을 벗은 적이 없었다. 산소에 흰제비가 날아와 둥지를 틀고 살았는데 사람들이 그의 정성이 하늘에까지 닿은 것이라 하였다. 윤씨부인은 호조참판을 지낸…","a":"송씨양세정려","c":"문화유산자료","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659754.jpg"},{"q":"조선시대 초대 남원부사 김희를 추모하기 위해 세운 사당이다. 김희는 남원부사로 재임하면서 백성을 인자하게 다스리고 판결이 명백하고 공정하여 주민들의 칭송을 받았으나 불행히도 재임 중에 병으로 별세하였다. 선조 30년(1597)에 불에 타버려 영조 때 다시 지었는데, 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 제사는 봄(4월)에는 사당에서 지내고, 가을(10월)에는 송정리 무덤에서 지낸다.","a":"유애묘","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661675.jpg"},{"q":"○○군 이원면 현(縣) 마을 옛 ○○○○ 자리에 서 있는 이 ○○○는 1682년 숙종(肅宗) 8년 ○○○○ 이라는 사액(賜額)을 받고 세운 비로서 우암(右菴) 송시열(宋時烈) 선생이 글을 짓고 곡운(谷雲) 김수증 (金壽增)이 글을 썼다. 이 비는 장방형(長方形)의 기초석(基礎石) 위에 비신 (碑身)을 세웠으며 비신 위에는 기와지붕 모양의 비 갓을 사실적으로 표현하여 올려 놓아 조선시대의 전형적인 모습을 잘 나타내고 있다.","a":"옥천 창주서원 묘정비","c":"시도기념물","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650457.jpg"},{"q":"조선시대 직제학 설순 등이 임금의 명에 따라 우리나라와 중국의 서적에서 군신·부자·부부의 삼강에 모범이 될만한 충신, 효자, 열녀의 행실을 모아 만든 책이다. 조선 전기의 윤리와 의례에 관한 것을 기록한 것으로, 초판은 조선 세종 14년(1432)에 이루어졌지만, 본 책자는 재판인 것으로 보인다. 이 책은 조선 전기의 사회규범 연구에 좋은 자료로 평가된다.","a":"삼강행실도","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641756.jpg"},{"q":"○○○○○은 당초 1890년에 코프(한국명 고요한) 신부에 의해 지어졌으나 한국전쟁 때 소실되었고 현재의 건물은 1956년에 중건된 것이다. 중건 당시 기초를 철근 대신 ‘H’형강을 사용하였다. 건물 형태는 지붕의 목조트러스를 제외하고, 외벽과 주요부재는 화강암으로 견고하게 쌓아올린 중세풍의 석조이나 한국의 전통적인 목구조 처마양식을 가미하였으며 창호 및 벽체 부분의 처리가 뛰어나다.","a":"인천 내동 성공회 성당","c":"시도유형문화유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637121.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 충청남도 부여군 초촌면 ○○○의 ‘바우재’또는 ‘쇠울’이라 불리우는 구릉에 동서로 2기의 고인돌이 나란히 있다. 동쪽 고인돌의 덮개돌은 길이 5.8m, 너비 3.7m의 크기이며, 하부구조는 모두 파헤쳐져 알 수 없으나 바둑판식으로 추정된다…","a":"부여산직리지석묘","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652731.jpg"},{"q":"이 가옥은 1807년(순조 7)에 현 소유자 ○○○閔正基의 6대조인 민형현閔亨顯이 건립한 가옥으로 안채와 사랑채, 사당, 문간채 등을 갖추고 있다. 안채 상량 기록 “숭정기원후사을사중수崇禎紀元後四乙巳重修”로 보아 1845년(헌종 11)에 다시 지은 것이다. 안채는 6칸 규모의 ‘一자형’ 집으로 앞뒤에 툇마루를 두었으며, 대청 한쪽에는 곡식을 저장하는 안광을 설치하였다. 특히 누마루 난간은 아자형, 원형, 조롱목형 등 다양한 문양으로 장식되어 독특하다. 사랑채는 앞면 5칸, 옆면 1칸 규모로 중앙 대청과 양쪽 온돌방을 갖추었다. 사랑채 건물로는 보기 드물게 맞배지붕으로…","a":"해남민정기가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662187.jpg"},{"q":"○○○에 자리잡고 있는 옛 집으로, 19세기 초반에 지은 것으로 보인다. 선성 김씨들이 대대로 살던 집이지만 구체적인 연혁은 알 수 없다. 안채는 초가 까치구멍집이고 사랑채는 기와집으로 되어 있었는데, 1975년경에 안채의 초가지붕을 기와지붕으로 고쳤다. 까치구멍집은 지붕에 구멍을 내어 집안에서 생기는 연기를 빼내고 빛을 받아들이도록 지은 집이다. 안채는 출입구인 봉당을 중심으로 뒤에 마루를 두고, 왼쪽에는 사랑방, 오른쪽에는 부엌을 배치하였다. 마루 좌우로는 도장방과 안방을 마련하였다. 사랑채는 앞면 5칸·옆면 1칸반의 규모이며, 지붕은 옆면이 여덟 팔(八)자 모양…","a":"영주수도리김뢰진가옥","c":"시도민속문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658850.jpg"},{"q":"○○○○○은 고려시대에 우리나라 연안을 빈번히 침범하던 왜구의 노략질을 막기 위해 설치한 구라량의 진영이 있던 곳이다. 그 뒤 구라량이 폐쇠되어 쇠퇴했던 것을 조선 순조(재위1801∼1834) 때 진주 병마절도사가 진주목 관하의 창선도와 적량첨사와의 군사적 연락을 위해, 둑을 쌓아 ○○을 만든 것이다. 당시에는 300여 명의 상비군과 전함 2척을 상주시켜 병선의 정박지로 삼고 왜구를 방어하였다. 이 ○○○○○을 쌓기 위하여 진주목 관하 73개면에서 수천명이 동원되어 1820년경에 완공하였다고 전한다.","a":"사천 대방진 굴항","c":"문화유산자료","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664034.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 19년(1437)에 처음 지었으며 임진왜란으로 완전히 불타 없어진 것을, 영조(재위 1724∼1776) 때에 다시 지어 오늘에 이르고 있다. ○○○의 규모는 앞면 3칸·옆면 3칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"함열향교대성전","c":"문화유산자료","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661698.jpg"},{"q":"척화비란 쇄국정책을 실시하던 흥선대원군이 병인양요, 신미양요를 치르면서 더욱 의지를 굳혀 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국 중요 도로변에 세우도록 한 비이다. 신창 초등학교 입구에 자리하고 있는 이 비는 높직한 사각받침 위로 비몸을 세운 모습이다. 비문에는 “서양오랑캐가 침범함에 싸우지 않으면 화의인데, 화의를 주장함은 나라를 파는 것이다.”라는 강한 경고 문구가 쓰여 있다. 척화비는 고종 8년(1871) 신미양요를 치른 후 같은 해에 일제히 세운 것으로, 고종 19년(1882) 임오군란이 일어나고 대원군이 러시아 공사관으로 납…","a":"신창척화비","c":"문화유산자료","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661293.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 세종 3년(1421)에 지어진 ○○○○는 중종 5년(1510)에 현재의 위치로 옮겼으며, 선조 25년(1592) 임진왜란으로 불타 없어진 것을 다시 지었다. ○○○○○는 지어진 시기를 정확히 알 수 없다. ‘○○○’란 말은 ‘공자지도 만물화생’에서 따온 것이라 하며, 현판은 조선 정조 18년(1794)에 조항진이 쓴 것이다. 앞면 4칸·옆면 2칸으로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 특히 이곳은 기단의 중앙 부분을 끊어 넓은 계단을 설치한 점과 앞면을 짝…","a":"태인향교만화루","c":"시도유형문화유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639548.jpg"},{"q":"○○○는 통일신라시대에 처음 지어진 사찰로, 한국전쟁으로 인해 불에 타 없어졌던 것을 최근에 다시 지어 명맥을 이어가고 있다. 절 안에 남아 있는 이 탑은 커다란 바위 위에 서 있는데, 바위가 탑의 기단부(基壇部)를 대신하여 그 위로 3층의 탑신(塔身)이 쌓여 있는 모습이다. 탑신의 각 몸돌은 모서리마다 기둥모양을 본떠 가지런히 새겼다. 비교적 보존이 잘된 지붕돌은 밑면에 3단의 받침을 얕게 두었는데, 그에 따라 낙수면의 경사도 완만하다. 처마는 수평을 이루다가 양끝에서 살짝 들려 가벼운 상승감이 느껴진다. 꼭대기에는 단조로운 머리장식이 비교적 잘 남아 있는데 후대에…","a":"함양 금대사 삼층석탑","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641405.jpg"}]);